  str_homestory_chat_15222002 = "PlayerName、天空ノ谷って、\nこの大陸で一番私に合ってるところだと思わない？",
  str_homestory_chat_15222003 = "どうしてそう思ったの？",
  str_homestory_chat_15222004 = "天空ノ谷では、誰にもこき使われないし、\n終わりのない残業もない…",
  str_homestory_chat_15222005 = "何より、好きなだけ寝坊できるでしょ！",
  str_homestory_chat_15222006 = "こき使われないから？",
  str_homestory_chat_15222007 = "いい推理。でも、それだけじゃないよ。",
  str_homestory_chat_15222008 = "昼寝にいい場所、\n4つも見つけてあるんだ。",
  str_homestory_chat_15222009 = "誰にもジャマされず、\n日が沈むまで寝てられるの。",
  str_homestory_chat_15222010 = "天空ノ谷をずいぶん気に入ってるんだね。",
  str_homestory_chat_15222011 = "気に入らない人なんて、\nこの世界にいないでしょ！",
  str_homestory_chat_15223001 = "今、忙しい？",
  str_homestory_chat_15223002 = "PlayerName、私、遅刻防止チャレンジのリストを作ったんだ。\n一緒にやる？",
  str_homestory_chat_15223003 = "急にマジメになってどうしたの？\n君らしくないね。",
  str_homestory_chat_15223004 = "ちょっと見せて…",
  str_homestory_chat_15223005 = "時間通りに睡眠に挑戦…\n時間通りに散歩に挑戦…",
  str_homestory_chat_15223006 = "賞味期限の近いポテトチップスを\n期限までに食べる挑戦…",
  str_homestory_chat_15223007 = "さすがだね…",
  str_homestory_chat_15223008 = "それほどでもないよ。",
  str_homestory_chat_15223009 = "こんなの、挑戦じゃないでしょ！",
  str_homestory_chat_15223010 = "「時間通りに散歩」は、\nけっこう挑戦のしがいがあると思うよ？",
  str_homestory_chat_15251001 = "珍しい魚を見かけたらしいね？",
  str_homestory_chat_15251002 = "あー…うん、数日前、川で仕事をサボ――ポッ！\nどうしたらもっとうまく仕事できるかな～って考えてた時…",
  str_homestory_chat_15251003 = "…もっとうまいサボり方を考えてたんでしょ？",
  str_homestory_chat_15251004 = "ポッポ！仕事だよ、仕事のことを考えてたの！\nそれよりほら、魚の話だよ。気になるんでしょ？",
  str_homestory_chat_15251005 = "うん、気になる。",
  str_homestory_chat_15251006 = "ただ、手元にある仕事を終わらせるために、\nちょっと必要なものがあるの、ポッポ！",
  str_homestory_chat_15251007 = "そうだろうと思った…で、何が必要なの？",
  str_homestory_chat_15251008 = "短い葉のアーサーの種がほしいんだ。",
  str_homestory_chat_15251009 = "分かった。じゃあ、探してくるね。",
  str_homestory_chat_14899999 = "あんた今、私に声かけたか？",
  str_homestory_chat_14801001 = "うん、そうだよ。",
  str_homestory_chat_14801002 = "ジャマしちゃった？",
  str_homestory_chat_14801003 = "別に。ただ、わざわざ立ち止まってあいさつしてるほど、\nヒマじゃないんだ。",
  str_homestory_chat_14801004 = "何しろ、やらなきゃならないことが\n山ほどあるからな。",
  str_homestory_chat_14801005 = "え、それだけ？もう行っちゃうの？",
  str_homestory_chat_14801006 = "言いたいことがあるなら、\n最初から言えばいいだろ。",
  str_homestory_chat_14821001 = "何を探してるの？",
  str_homestory_chat_14821002 = "ロビンを見なかったか？",
  str_homestory_chat_14821003 = "ロビン！…おーい、ロビン！！",
  str_homestory_chat_14821004 = "見かけなかったよ…",
  str_homestory_chat_14821005 = "急ぎなの？だったら、僕も手伝うよ。",
  str_homestory_chat_14821006 = "もちろん、急ぎだよ。\nもう10分もあいつを見てないんだ！",
  str_homestory_chat_14821007 = "こんなに長いことあいつを見かけないなんて、\n今までなかったんだ！",
  str_homestory_chat_14821008 = "そ、それは、少し大げさじゃ…",
  str_homestory_chat_14821009 = "あっちにいたよ…",
  str_homestory_chat_14821010 = "そう言えば、君はいつもロビンを探してる気がするけど、\nどうしてだろう？",
  str_homestory_chat_14821011 = "どういう意味だ？何が言いたい？",
  str_homestory_chat_14821012 = "い、いや、特別な意味はないよ…",
  str_homestory_chat_14821013 = "それより、急いでロビンのところに行ってあげなよ…",
  str_homestory_chat_14822001 = "タイクツしてる？",
  str_homestory_chat_14822002 = "ああ…あんたのとこに、\n何か面白いモンないか？",
  str_homestory_chat_14822003 = "「面白いもの」？",
  str_homestory_chat_14822004 = "例えば、年代物の花びんとか、\n古い文字が刻まれた石とか…",
  str_homestory_chat_14822005 = "あんたのとこに、\nそういうモノはないか？",
  str_homestory_chat_14822006 = "あるよ！",
  str_homestory_chat_14822007 = "今度、連れて行ってあげるよ。",
  str_homestory_chat_14822008 = "宝探しのガイドなんてやってくれるのか？\n面白そうじゃないか。",
  str_homestory_chat_14822009 = "ないよ…",
  str_homestory_chat_14822010 = "そうか、予想通りだな。",
  str_homestory_chat_14822011 = "まあ、いい。\nないからって、大した問題じゃない。",
  str_homestory_chat_14823001 = "ヒマそうだね。",
  str_homestory_chat_14823002 = "まったくタイクツだ。\nケンカも起こりやしない。",
  str_homestory_chat_14823003 = "ここに来る前に十分気晴らししたでしょ…？",
  str_homestory_chat_14823004 = "血生臭い生活は散々経験して来たんでしょ？\nそろそろ、ゆっくり過ごすようにしたら？",
  str_homestory_chat_14823005 = "分かった、分かった。\nあんたの言う通りだな…",
  str_homestory_chat_14823006 = "ちょっとどいてくれ。",
  str_homestory_chat_14823007 = "何をするつもり？",
  str_homestory_chat_14823008 = "木を何回か斬りつけて、\n気が済んだら…",
  str_homestory_chat_14823009 = "あとはゆっくり過ごす。",
  str_homestory_chat_14823010 = "ちょっと！環境破壊はダメだよ！？",
  str_homestory_chat_14824001 = "今日の予定は？",
  str_homestory_chat_14824002 = "予定？まったく考えてないな。",
  str_homestory_chat_14824003 = "毎日予定通りに暮らすなんて、\n面白くないだろ。",
  str_homestory_chat_14824004 = "…まさか、あんたは毎日計画通りに生活してんのか？",
  str_homestory_chat_14824005 = "そうだよ！",
  str_homestory_chat_14824006 = "毎日しっかり計画を立てると、何か安心できるんだ。",
  str_homestory_chat_14824007 = "PlayerNameも\nそういうタイプだったのか。",
  str_homestory_chat_14824008 = "もっとテキトーに生きてると思ってたよ。",
  str_homestory_chat_14824009 = "いいや…",
  str_homestory_chat_14824010 = "いくら予定なんか立てても、\nどうせ予定外のことが起こるし…",
  str_homestory_chat_14824011 = "だよな！",
  str_homestory_chat_14824012 = "毎日違ったことが起きる。\nそれこそ生きてて楽しいってもんだ！",
  str_homestory_chat_14825001 = "服を買いたいの？",
  str_homestory_chat_14825002 = "あんたの天空ノ庭には、服を売ってるような所はないみたいだね？",
  str_homestory_chat_14825003 = "だって必要ないからね…ダイナが服を買いたいなら、影ノ街に行けばいいんじゃない？",
  str_homestory_chat_14825004 = "あんたに買ってあげるんだよ、解体屋。",
  str_homestory_chat_14825005 = "えっ？僕に？",
  str_homestory_chat_14825006 = "どうして？",
  str_homestory_chat_14825007 = "だっていつもその服を着てうろちょろしてるだろ。もう見飽きたよ。",
  str_homestory_chat_14825008 = "それはまあ…確かに。",
  str_homestory_chat_14825009 = "僕は要らないから",
  str_homestory_chat_14825010 = "それなら、私と影ノ街に行ってみないか？",
  str_homestory_chat_14825011 = "考えてみるよ。",
  str_homestory_chat_14825012 = "考えるって何をさ。これ以上その服で走り回ってたら、キューブだって見飽きちまうよ。",
  str_homestory_chat_14826001 = "稽古？",
  str_homestory_chat_14826002 = "時々は剣術の稽古もしないとね。いつも魚や木ばかり相手にしてられないから。",
  str_homestory_chat_14826003 = "あの木の傷は君がつけたんだね…",
  str_homestory_chat_14826004 = "ちょうどいい練習相手を探してくれよ！",
  str_homestory_chat_14826005 = "ここにはいないよ。",
  str_homestory_chat_14826006 = "やっぱり木を相手にしてたら？",
  str_homestory_chat_14826007 = "あるいは…岩とか？",
  str_homestory_chat_14826008 = "適当にあしらおうとしてるな、解体屋。",
  str_homestory_chat_14826009 = "だってここは平和な場所なんだから、ここに来たらリラックスすべきだよ。",
  str_homestory_chat_14826010 = "どうやら自分で標的を探すしかなさそうだな。そこのキューブがいいかもな！",
  str_homestory_chat_14826011 = "動きは遅いし、反撃もしないし、殴っても耐えられそうだ。",
  str_homestory_chat_14826012 = "それはやめてー！",
  str_homestory_chat_12299999 = "今日はいい天気だぜ。ディーゼルオイルを1杯どうだ？",
  str_homestory_chat_12221001 = "…遠慮しておくよ。",
  str_homestory_chat_12221002 = "年代もののディーゼルオイルだ、すっげぇうまいんだぜ。\nホントに要らないのか？",
