  str_homestory_chat_12222005 = "きっと啓光のヤツらが裏で値段を釣り上げてるに違いない！",
  str_homestory_chat_12222006 = "…言うべきかどうか、迷ってるんだけど…",
  str_homestory_chat_12222007 = "ボス、遠慮はいらないぜ？",
  str_homestory_chat_12222008 = "ディーゼルオイルは――全部R・Wの人たちが運んできてるんだよ。",
