  str_homestory_chat_12222010 = "怒った？",
  str_homestory_chat_12222011 = "ボス、教えてくれてありがとよ――",
  str_homestory_chat_12222012 = "つまりディーゼルオイルがタダ飲みできるってことだ！",
  str_homestory_chat_12223001 = "ディーゼルオイルのことより…",
  str_homestory_chat_12223002 = "何を見てるの？",
  str_homestory_chat_12223003 = "ボス、ラビを見かけなかったか？",
  str_homestory_chat_12223004 = "ラビに何か用なの？",
  str_homestory_chat_12223005 = "もう半日も見てないんだ…",
  str_homestory_chat_12223006 = "万が一何かあって、\n僕が側で守ってやれなかったら――",
  str_homestory_chat_12223007 = "一生後悔するだろ！？",
  str_homestory_chat_12223008 = "ボス、早く僕とラビを助けてくれ！",
  str_homestory_chat_12223009 = "…お、落ち着いて…君の単なる想像だよ…",
  str_homestory_chat_11299999 = "こんにちは！",
  str_homestory_chat_11201001 = "こんにちは、ナミシス。",
  str_homestory_chat_11201002 = "今日も私と共に正義を執行しに行きますか？",
  str_homestory_chat_11201003 = "ナミシスがいるなら、\nここも安全だね。",
  str_homestory_chat_11201004 = "当然です。どんな小さな片隅の暗闇も、\n私は決して見逃しません！",
  str_homestory_chat_11221001 = "最近は本当に平和だよ",
  str_homestory_chat_11221002 = "はい、ですが、パトロールを\nおこたってはなりません。",
  str_homestory_chat_11221003 = "必要ないよ",
  str_homestory_chat_11221004 = "ここにいる人はみんな友だちだし、\n争いごともないよ。",
  str_homestory_chat_11221005 = "確かに一理ありますね。",
  str_homestory_chat_11221006 = "しかし、何事も未然に防ぐことが肝心…\nそれが執行者として、私の行うべきことです。",
  str_homestory_chat_11221007 = "いい考えだね",
  str_homestory_chat_11221008 = "全員友だちだけど、\n多少のもめ事は起こるものだからね。",
  str_homestory_chat_11221009 = "ケンカにでもなったら大変だ。",
  str_homestory_chat_11221010 = "私の仕事の価値を認めてくださる方がいて、\nうれしい限りです。",
  str_homestory_chat_11221011 = "この平穏は、私が守ります。",
  str_homestory_chat_11222001 = "何かあったの？",
  str_homestory_chat_11222002 = "先ほど、天空ノ谷の環境を\n破壊しようとした人物がいたので阻止しました。",
  str_homestory_chat_11222003 = "え、何をしてたの！？",
  str_homestory_chat_11222004 = "花畑の花を折って\n持ち去ろうとしていたのです。",
  str_homestory_chat_11222005 = "そのような規則違反、\n私は決して許しません！",
  str_homestory_chat_11222006 = "それで、その人に何をしたの？",
  str_homestory_chat_11222007 = "裁きの刀で5mほど吹き飛ばしました。",
  str_homestory_chat_11222008 = "ナミシス、ここの環境を守ってくれてありがとう…",
