  str_homestory_chat_11222010 = "どのような？",
  str_homestory_chat_11222011 = "花を摘むと危ないって…",
  str_homestory_chat_11223001 = "何だか嬉しそうだね…",
  str_homestory_chat_11223002 = "今日は何かいい事でもあったの？",
  str_homestory_chat_11223003 = "迷子のネコを飼い主のもとへ戻す\nお手伝いができたのです。",
  str_homestory_chat_11223004 = "ネコも飼い主さんも、\n私にとても感謝してくれました。",
  str_homestory_chat_11223005 = "今日の日差しはことのほか、\n輝いていますね…",
  str_homestory_chat_11223006 = "本当にいい日だね。",
  str_homestory_chat_11223007 = "あなたと考えを共有できてうれしく思います。",
