  str_homestory_chat_11224001 = "人手を増やしたいって？",
  str_homestory_chat_11224002 = "はい。この地の治安を守るために、\nパトロール隊を結成したいのです。",
  str_homestory_chat_11224003 = "ここは啓光連邦じゃないんだから、\nそんなに気を張らなくても…",
