  str_homestory_chat_10222003 = "山、谷、川、そして森…桜だけはありませんが。",
  str_homestory_chat_10222004 = "桜も植えましょうか？",
  str_homestory_chat_10222005 = "何かしてもらうために\n言ったわけではありません。それに…",
  str_homestory_chat_10222006 = "少し植えましょう",
  str_homestory_chat_10222007 = "ここに桜を？",
  str_homestory_chat_10222008 = "そう考えてます。",
  str_homestory_chat_10222009 = "桜の生長に適さない場所もあります。",
  str_homestory_chat_10222010 = "ううん、じゃあ、詳しい人に聞いてみます。",
  str_homestory_chat_10223001 = "何をしてるんですか？",
  str_homestory_chat_10223002 = "…",
  str_homestory_chat_10223003 = "どうして刀を叩いてるんですか？",
  str_homestory_chat_10223004 = "打ち粉をふっているのです。",
  str_homestory_chat_10223005 = "「打ち粉」って何ですか？",
  str_homestory_chat_10223006 = "刀身にふると、刀に付いた\n古い油を取り除くことができます。",
  str_homestory_chat_10223007 = "つまり、栄角刀の手入れをしているのです。",
  str_homestory_chat_10223008 = "不思議ですね！",
  str_homestory_chat_10223009 = "もう少し見ていてもいいですか？",
  str_homestory_chat_10223010 = "どうぞ。",
  str_homestory_chat_10224001 = "静かですね…",
  str_homestory_chat_10224002 = "瞑想に向いています。",
  str_homestory_chat_10224003 = "瞑想にいい場所ってどういう所ですか？",
  str_homestory_chat_10224004 = "山のふもと、小川のほとり、林の中…\n目を閉じれば、心の奥底まで沈んでゆけます…",
  str_homestory_chat_10224005 = "PlayerName、あなたも試してみるといいでしょう。\n力が湧き出てきますよ。",
  str_homestory_chat_10224006 = "ううん、確かに試してみる価値がありそうですね。",
  str_homestory_chat_10224007 = "瞑想できない場所もあるんですか？",
  str_homestory_chat_10224008 = "いいえ。騒がしい街の中でも、瞑想は出来ます。",
  str_homestory_chat_10224009 = "心を静めさえすれば、\nすべての音が耳に入らなくなりますから。",
  str_homestory_chat_10224010 = "しかし、ここは喧噪から遠く離れた場所です。\nより心を静めやすい…",
  str_homestory_chat_10224011 = "あなたも試してみるといいでしょう。",
  str_homestory_chat_10225001 = "何かを警戒してるんですか？",
  str_homestory_chat_10225002 = "武人はいかなる時も、\n周囲の状況に注意していなければなりません。",
  str_homestory_chat_10225003 = "確かにそうですね",
  str_homestory_chat_10225004 = "そうやって集中力を鍛えてるんですね。",
  str_homestory_chat_10225005 = "…",
  str_homestory_chat_10225006 = "（ヒイロさんの修行をジャマしちゃったみたいだ）",
  str_homestory_chat_10225007 = "そんなに張り詰めてる必要はありませんよ。",
  str_homestory_chat_10225008 = "ここにいる人は友だちばかりです。",
  str_homestory_chat_10225009 = "落ち着ける環境でも、\n気を抜いてはなりません。",
  str_homestory_chat_10225010 = "それが私の集中力の鍛え方です。",
  str_homestory_chat_10225011 = "…そうですか。\nでは、ヒイロさんのジャマをしないようにします。",
  str_homestory_chat_10226001 = "瞑想してるんですか？",
  str_homestory_chat_10226002 = "いいえ、今は風景を楽しんでいるだけです。",
  str_homestory_chat_10226003 = "え？ヒイロさんもただ風景を眺めることがあるんですね？",
  str_homestory_chat_10226004 = "驚くことではないでしょう。\nこの世の万物を観察し、悟りを得ることは、\n修練の一環です。",
  str_homestory_chat_10226005 = "何だか難しいですね…",
  str_homestory_chat_10226006 = "あなたも試してみるといいでしょう。",
