  str_homestory_chat_10226008 = "わ、分かりました。\n僕もやってみます。",
  str_homestory_chat_11199999 = "同胞よ。次に私にあいさつをする時は、\nまず姿勢を正すのだ。",
  str_homestory_chat_11101001 = "でも…",
  str_homestory_chat_11101002 = "あいさつぐらい、そこまで厳格にする必要は\nないんじゃないですか？",
