  str_homestory_chat_12121007 = "花も僕も、失望の時が訪れないことを願っていますよ…",
  str_homestory_chat_12121008 = "いいね！",
  str_homestory_chat_12121009 = "ここは日差しもあるし、\nジョラの園芸の才能が思う存分発揮できそうだね。",
  str_homestory_chat_12121010 = "ああ、なんとお優しい言葉でしょう！",
  str_homestory_chat_12121011 = "あなたの言う通りです。\nここには自然の美が満ち溢れています――",
  str_homestory_chat_12121012 = "僕にふさわしい所です。",
  str_homestory_chat_12122001 = "何を笑ってるの？",
  str_homestory_chat_12122002 = "たくさんの子どもたちが\nここに入ってきていますね…",
  str_homestory_chat_12122003 = "実に喜ばしいことです。",
  str_homestory_chat_12122004 = "子どもが好きなの？",
  str_homestory_chat_12122005 = "そうです。彼らの無垢で純粋な瞳、\n赤いほおをした、つやつやの顔…",
  str_homestory_chat_12122006 = "さまざまな花の姿を思い浮かべずにはいられません！",
  str_homestory_chat_12122007 = "残念なことに、生やす枝を間違えた花のように、\n言うことを聞かない子もいますから…",
  str_homestory_chat_12122008 = "そのような花を見た時には、\n僕は一切ためらわず、剪定しなければなりません。",
  str_homestory_chat_12122009 = "いま、何か物騒なことを聞いたような…？",
  str_homestory_chat_11499999 = "PlayerName、ここで会えたことを嬉しく思うぞ。",
  str_homestory_chat_11401001 = "こんにちは、ソルラドさん。",
  str_homestory_chat_11401002 = "こうしてお主の故郷を訪ねることができるとはな。\n招待に感謝しよう。",
  str_homestory_chat_11401003 = "これぐらいのことで、\nそこまでかしこまらないでください。",
  str_homestory_chat_11401004 = "お主の統治のもと、\nこの地に繁栄がもたらされることを願っている。",
  str_homestory_chat_11421001 = "ここをどう思われますか？",
  str_homestory_chat_11421002 = "整然としている。悪くない。\n心を尽くしていることが伝わってくる。",
  str_homestory_chat_11421003 = "PlayerNameよ、この地を治めていくにあたり、\nいずれ困難は避けられぬであろう。",
  str_homestory_chat_11421004 = "助けが必要となれば、余も時を惜しまない。",
  str_homestory_chat_11421005 = "ありがとうございます！",
  str_homestory_chat_11421006 = "きっとたくさん教えて頂きたいことが\n出てくると思います。",
  str_homestory_chat_11421007 = "ひとつの土地を治めるためには、\n秩序こそがすべての核となる…",
  str_homestory_chat_11421008 = "時には厳しさをともなうかもしれぬが、\nそれが無くてはならぬものなのだ。",
  str_homestory_chat_11421009 = "（うっ…難しい話が始まりそう…）",
  str_homestory_chat_11421010 = "今のところは、大丈夫です…",
  str_homestory_chat_11421011 = "ここにいるのはみんな、友だちですから。\n「治める」必要はありません。",
  str_homestory_chat_11421012 = "お主のやり方でこの地に繁栄がもたらされることを、\n心から願っている。",
  str_homestory_chat_11422001 = "ようこそ！",
  str_homestory_chat_11422002 = "お主の故郷は白夜城と同様、\n心地のよい晴天が広がっているのだな。",
  str_homestory_chat_11422003 = "この天気は――",
  str_homestory_chat_11422004 = "釣り日和ですね！",
  str_homestory_chat_11422005 = "川のほとりに腰かけ、\n悠々と泳ぐ獲物が針に掛かるのを待つ…",
  str_homestory_chat_11422006 = "そのような息抜きが、この地での流行か？",
  str_homestory_chat_11422007 = "試してみますか？",
  str_homestory_chat_11422008 = "悪くない。",
  str_homestory_chat_11422009 = "ジョギング日和ですね！",
  str_homestory_chat_11422010 = "老骨には向かぬな。",
  str_homestory_chat_11422011 = "余はそばで見ていることとしよう。",
  str_homestory_chat_11423001 = "読書ですか？",
  str_homestory_chat_11423002 = "このような日差しの中、読書に勤しむ…\n実に心地のよい過ごし方であろうな。",
  str_homestory_chat_11423003 = "PlayerName、興味があるならば、\nお主に余の蔵書を貸しだそう。",
  str_homestory_chat_11423004 = "ありがとうございます！",
  str_homestory_chat_11423005 = "ソルラドさんが読むような本なんて、\nきっと面白いんでしょうね。",
  str_homestory_chat_11423006 = "余は「楽しむ」ために読書をするのではない。",
  str_homestory_chat_11423007 = "書の中にある無限の宇宙に遊び、\n人のさがの奥深さを探りたいのだ。",
  str_homestory_chat_11423008 = "しかし、お主が書から楽しみを得るというのなら、\nそれも悪いことではない。",
  str_homestory_chat_11423009 = "大丈夫です…",
  str_homestory_chat_11423010 = "本を読んで一休みしたいところですが、\nやることがたくさんあるので…",
  str_homestory_chat_11423011 = "もし手に負えないことならば、\n余に託すのも一つの手だ。",
  str_homestory_chat_12999999 = "あら、やっぱり…",
  str_homestory_chat_12921001 = "えっ？",
  str_homestory_chat_12921002 = "あなたが来ることは、\n風が教えてくれていたの。",
  str_homestory_chat_12921003 = "そんな力があるの？",
  str_homestory_chat_12921004 = "あなたの息づかいは特別だもの。",
  str_homestory_chat_12922001 = "ヒマそうだね。",
  str_homestory_chat_12922002 = "鳥かごの中で日向ぼっこしてると、\n面白いことが起きるって気付いたの…",
  str_homestory_chat_12922003 = "どんなこと？",
  str_homestory_chat_12922004 = "顔の一部分だけ熱くなって、\n別の所はひんやりするのよ。",
  str_homestory_chat_12922005 = "どうしてそうなるの？",
  str_homestory_chat_12922006 = "私にも分からないわ…",
  str_homestory_chat_12922007 = "考えたくないわ。疲れるもの。",
  str_homestory_chat_12922008 = "鳥かごのせい？",
  str_homestory_chat_12922009 = "かごが顔に影を作って、そこだけ日の光が当たらないから、\nひんやりするんじゃないかな。",
  str_homestory_chat_12922010 = "その通りかもしれないわね。",
  str_homestory_chat_12922011 = "でも、はっきりさせようとは思わないわ。\n考えるのって、疲れるもの。",
  str_homestory_chat_12923001 = "ここを気に入ってくれたみたいだね。",
  str_homestory_chat_12923002 = "暖かな日の光…",
  str_homestory_chat_12923003 = "…ふぅ…そうね。まるで自分が綿になったみたい…",
  str_homestory_chat_12923004 = "…ふぅ…ああ、私、まだ起きてるわ…",
  str_homestory_chat_12923005 = "（眠りのジャマにならないようにしておこう）",
  str_homestory_chat_12924001 = "何してるの？",
  str_homestory_chat_12924002 = "聞こえた？",
  str_homestory_chat_12924003 = "ここは、音でいっぱいだわ…",
  str_homestory_chat_12924004 = "小川から、林から、山や谷から…\n絶えることなく聞こえてくるの。",
  str_homestory_chat_12924005 = "そうだね",
  str_homestory_chat_12924006 = "白夜城では、一番よく聞くのは風の音。\nそれ以外は、みんな光霊の音ね。",
  str_homestory_chat_12924007 = "どちらかというと、\n私はここの音の方が好き。",
  str_homestory_chat_12924008 = "気付かなかったな",
  str_homestory_chat_12924009 = "でも、言われてみれば、本当にそうだ…",
  str_homestory_chat_12924010 = "耳をすませば、思いもよらなかった\n喜びが聞こえてくるものよ。",
  str_homestory_chat_12925001 = "木材？",
  str_homestory_chat_12925002 = "ええ、木材。軽くて丈夫なものはあるかしら？",
  str_homestory_chat_12925003 = "うーん……急に木材が必要だなんて、何をするつもりなの？",
  str_homestory_chat_12925004 = "鳥籠を改造したいのよ。何しろ大きくて重いものだから。",
  str_homestory_chat_12925005 = "確かに、木材が軽ければ、君も少し楽になるよね。",
  str_homestory_chat_12925006 = "でも君が言うような木材は、天空ノ庭ではなかなか手に入らないと思う。",
  str_homestory_chat_12925007 = "ここにあるのは、どれも木材にするには難しそうな不思議な木ばかりだから。",
  str_homestory_chat_12925008 = "それに……キューブが承諾してくれなさそうだよ。",
  str_homestory_chat_12926001 = "高いところ？",
  str_homestory_chat_12926002 = "天空ノ庭で風景がきれいな場所を探してて、あれこれ考えてるところなの……",
  str_homestory_chat_12926003 = "天空ノ庭を一望できるような、もうちょっと高い場所があればいいのに。",
  str_homestory_chat_12926004 = "あら、だからあなたに聞いているのよ。",
  str_homestory_chat_12926005 = "あるよ",
  str_homestory_chat_12926006 = "風の塔なんかいいんじゃない？",
  str_homestory_chat_12926007 = "でもキューブが承諾してくれるかしら。",
  str_homestory_chat_12926008 = "確かに……ダメだね。",
  str_homestory_chat_12926009 = "ないよ",
  str_homestory_chat_12926010 = "あら……やっぱり実現は難しそうね。",
  str_homestory_chat_12926011 = "そもそも何をしようとしているの？",
  str_homestory_chat_12926012 = "鳥籠を高いところに吊るして、そよ風に鳥籠が揺れる感覚を楽しみたかったの。",
  str_homestory_chat_12926013 = "とても眠りにつきやすく、心地いいのよ。",
  str_homestory_chat_12926014 = "確かにね。でも高いところは風も強いかもしれないよ。鳥籠が激しく揺れちゃう。",
  str_homestory_chat_12926015 = "そうね、確かにあなたの言う通りだわ。",
  str_homestory_chat_12926016 = "だから、やっぱり現状維持がいいよ。",
  str_homestory_chat_12699999 = "あ…私に近寄りすぎないで…",
  str_homestory_chat_12601001 = "どうして？",
  str_homestory_chat_12601002 = "私の力で…やけどするわ…",
  str_homestory_chat_12601003 = "大丈夫だよ、十分注意してるから。",
  str_homestory_chat_12601004 = "そうだといいけど…私は貴方を傷つけたくない…",
  str_homestory_chat_12621001 = "おしゃべりしようか？",
  str_homestory_chat_12621002 = "おしゃべり？",
  str_homestory_chat_12621003 = "何を話せばいいの…？私には分からない…",
  str_homestory_chat_12621004 = "例えば、最近やったことは？",
  str_homestory_chat_12621005 = "意義のないことを、覚える気はないわ…",
  str_homestory_chat_12621006 = "でも、意義のあることって何…？\n…私には、分からない。",
  str_homestory_chat_12621007 = "例えば、最近見た風景は？",
  str_homestory_chat_12621008 = "私の耐爆格納器の中の\n暗闇のことを言っているの…？",
  str_homestory_chat_12621009 = "ときどき、私の炎で照らしだされて…",
  str_homestory_chat_12621010 = "や、やっぱり別の話題にしよう。",
  str_homestory_chat_12622001 = "今、何て言った？",
  str_homestory_chat_12622002 = "…何を話すか…考えさせて…",
  str_homestory_chat_12622003 = "え――ちょっと？",
  str_homestory_chat_12622004 = "…なに？",
  str_homestory_chat_12622005 = "話してる最中なのに、\nどこかに気を取られてるみたいだったよ。",
  str_homestory_chat_12622006 = "…気が散ってなどいない…私はただ、考えていただけ…",
  str_homestory_chat_12622007 = "私のような者と話すのって、大変でしょう…",
  str_homestory_chat_12622008 = "そうだね",
  str_homestory_chat_12622009 = "自分の世界に深くはまっちゃった時は、\nときどき顔を上げて、僕たちを見て。",
  str_homestory_chat_12622010 = "難しいことじゃないよ。だから、試してみて！",
  str_homestory_chat_12622011 = "そんなことないよ",
  str_homestory_chat_12622012 = "たまには沈黙があった方が、一息つけるし…",
  str_homestory_chat_12622013 = "一緒にいる時間を楽しもうよ。",
  str_homestory_chat_12623001 = "君の火の環について話そう",
  str_homestory_chat_12623002 = "私の火環？火環は私の過去と関係があるもの…",
  str_homestory_chat_12623003 = "過去を振り返ると、苦しくなるわ…",
  str_homestory_chat_12623004 = "じゃ、じゃあ、この話題はやめておこう。",
  str_homestory_chat_12623005 = "そう…でも、苦痛は私にとって、いつものことよ…",
  str_homestory_chat_12623006 = "話したからといって、大して変わらない…",
  str_homestory_chat_12624001 = "何か変わったことでもあった？",
  str_homestory_chat_12624002 = "…何について話すの…？",
  str_homestory_chat_12624003 = "聞いた話だと、バイスが外で食事を作ってて、\nうっかりテーブルクロスに火をつけちゃった時…",
  str_homestory_chat_12624004 = "君が火環で消火を助けてくれたんだよね。",
  str_homestory_chat_12624005 = "…ええ。",
  str_homestory_chat_12624006 = "炎を吸い取るなんて…",
  str_homestory_chat_12624007 = "カッコイイね！",
  str_homestory_chat_12624008 = "そう…？\nううん…ほめてくれてありがとう…",
  str_homestory_chat_12625001 = "最近の調子はどう？",
  str_homestory_chat_12625002 = "よくはないわ…",
  str_homestory_chat_12625003 = "な、何か至らないところがあったかな？",
  str_homestory_chat_12625004 = "いいえ…ただ、少し、困ってるだけ…",
  str_homestory_chat_12625005 = "天空ノ谷は…自然でいっぱいで…",
  str_homestory_chat_12625006 = "眠くなるけど…そうすると…",
  str_homestory_chat_12625007 = "草や木に火をつけてしまうから…",
  str_homestory_chat_12625008 = "えっ！？",
  str_homestory_chat_12625009 = "そのたびに、火環で炎を吸い込んでいるわ…",
  str_homestory_chat_12625010 = "ただ、焦げ跡が草地に残ってしまう…",
  str_homestory_chat_12625011 = "か、構わないよ。",
  str_homestory_chat_12625012 = "草は焦げても、また生えてくるから！",
  str_homestory_chat_12625013 = "君がケガしたり、\n建物が焼けたりさえしなければ、いいんだよ。",
  str_homestory_chat_14699999 = "ごきげんいかが？",
  str_homestory_chat_14601001 = "こんにちは、他の子たちは？",
  str_homestory_chat_14601002 = "別のことをしてるよ。",
  str_homestory_chat_14601003 = "ナビゲーター様は、やることないの？",
  str_homestory_chat_14601004 = "…さようなら。",
  str_homestory_chat_14621001 = "ご飯は食べた？",
  str_homestory_chat_14621002 = "野菜は食べない♪",
  str_homestory_chat_14621003 = "苦いのが嫌い♪",
  str_homestory_chat_14621004 = "野菜は体にいいんだよ？",
  str_homestory_chat_14621005 = "ナビゲーター様、私は健康だよ。",
  str_homestory_chat_14621006 = "不健康なナビゲーター様こそ、野菜を食べなよ。",
  str_homestory_chat_14621007 = "だって、明らかに野菜不足でしょ？",
  str_homestory_chat_14622001 = "最近、本は読んだ？",
  str_homestory_chat_14622002 = "物語を読まないと♪",
  str_homestory_chat_14622003 = "毎日ゆっくり長くて辛くなる♪",
  str_homestory_chat_14622004 = "何かやることを探せばいい",
  str_homestory_chat_14622005 = "ナビゲーター様、\n物語の本をもっとたくさん読むといいよ。",
  str_homestory_chat_14622006 = "人助けをする気持ちになるかもね。",
  str_homestory_chat_14622007 = "後で探すのを手伝うよ",
