  str_homestory_chat_14622009 = "そのうち忘れる♪",
  str_homestory_chat_14623001 = "ここについて、感想は？",
  str_homestory_chat_14623002 = "ここが好きかと聞かれたら♪",
  str_homestory_chat_14623003 = "もちろん好き、とっても好き♪",
  str_homestory_chat_14623004 = "ありがとう！",
  str_homestory_chat_14623005 = "ナビゲーター様が聞きたいことを言っただけ♪",
