  str_homestory_chat_14625004 = "ナビゲーター様は後ろめたい♪",
  str_homestory_chat_14625005 = "そんなことないよ！",
  str_homestory_chat_14625006 = "ぼ、僕はただ、\n天空ノ谷の建設で忙しいだけ！",
  str_homestory_chat_14625007 = "ああ、忙しい、忙しい♪",
  str_homestory_chat_14625008 = "大した目的もないのに♪",
