  str_homestory_chat_14625013 = "ちょっと！？",
  str_homestory_chat_12399999 = "わ、私に…あいさつですか？\nそ、それなら…どうも、こんにちは…",
  str_homestory_chat_12301001 = "そんなに緊張しないで。",
  str_homestory_chat_12301002 = "わ、分かりました。勇気を出さないと…",
