  str_homestory_chat_12301004 = "うわあ！いきなり声が大きい！",
  str_homestory_chat_12321001 = "楽器の演奏ができるんだよね？",
  str_homestory_chat_12321002 = "クラリンはクラリネットが上手だって聞いたよ。",
  str_homestory_chat_12321003 = "え？な、なんですか？私を演奏会に？",
