  str_homestory_chat_12321013 = "僕も皆も、楽しみにしてるね！",
  str_homestory_chat_12322001 = "少しのどが乾いたなあ。",
  str_homestory_chat_12322002 = "PlayerNameさん、コ、コーヒーは、いかがですか？",
  str_homestory_chat_12322003 = "飲みたくなければ…構いません。捨てますから…",
  str_homestory_chat_12322004 = "飲みたい！",
  str_homestory_chat_12322005 = "でも…おいしくなかったら…",
  str_homestory_chat_12322006 = "捨てちゃうの？",
  str_homestory_chat_12322007 = "いれ方の練習中なんです。\nそれで、何杯も余って…",
  str_homestory_chat_12322008 = "うう…やっぱり、捨てます。\nたぶん、おいしくないので…",
  str_homestory_chat_12322009 = "ちょっと待って！",
  str_homestory_chat_12322010 = "僕にはコーヒーの味なんて\nどうせ分からないから、心配しないで。",
  str_homestory_chat_12322011 = "飲んで気分がすっきりすれば、それでいいんだ。",
  str_homestory_chat_12322012 = "分かりました…",
  str_homestory_chat_12323001 = "どうしたの？",
  str_homestory_chat_12323002 = "すごく、まぶしいですね…",
  str_homestory_chat_12323003 = "日差しが、強すぎます…",
  str_homestory_chat_12323004 = "私はもう少し薄暗い場所が…",
  str_homestory_chat_12323005 = "木陰に行けば、少し気分が良くなるんじゃない？",
  str_homestory_chat_12323006 = "そ、そうかもしれませんね…",
  str_homestory_chat_12324001 = "誰と話してるの？",
  str_homestory_chat_12324002 = "…もう、分かったから…\nあっ、ごめんなさい…！",
  str_homestory_chat_12324003 = "アントンたちと話してました…\n一緒に話したいですか？",
  str_homestory_chat_12324004 = "僕はいいよ…",
  str_homestory_chat_12324005 = "アントンたちは…確かに、\n人を怖がらせてしまう時があります…",
  str_homestory_chat_12324006 = "でも、信じてください。みんな、いい子なんです！",
  str_homestory_chat_12324007 = "いいね！",
  str_homestory_chat_12324008 = "で、でしたら、アントンたちを呼びますね…",
  str_homestory_chat_12325001 = "何をしてるの？",
  str_homestory_chat_12325002 = "あ、PlayerNameさん…",
  str_homestory_chat_12325003 = "ここへ来てしばらくになりますが、\nたくさんの人に助けてもらいました…",
  str_homestory_chat_12325004 = "それで、皆さんに、コーヒーをいれて\n差し上げたいと思ったのですが…私…",
  str_homestory_chat_12325005 = "何か困ったことでも？",
  str_homestory_chat_12325006 = "私、皆さんがコーヒーを好きかどうか、\n分からないので…",
  str_homestory_chat_12325007 = "どうしたらいいか迷ってしまって…",
  str_homestory_chat_12325008 = "考えすぎる必要はないよ、クラリン！",
  str_homestory_chat_12325009 = "クラリンのコーヒーはいつだっておいしいし、\nそれに――",
  str_homestory_chat_12325010 = "コーヒーそのものより、\nクラリンの気持ちの方が大切だから。",
  str_homestory_chat_13699999 = "まったく…タイクツだ。\nやっと俺に用でもできたか？",
  str_homestory_chat_13601001 = "特に用はないんだ。\nあいさつしただけだよ。",
  str_homestory_chat_13601002 = "あいさつだけだと？",
  str_homestory_chat_13601003 = "…つまらんあいさつに、\nはりきって答えた俺がバカだった。",
  str_homestory_chat_13621001 = "最近、どう？",
  str_homestory_chat_13621002 = "ここの食べものは味が薄い。\n犬だって食べやしないな。",
  str_homestory_chat_13621003 = "じゃあ、何が食べたい？",
  str_homestory_chat_13621004 = "何でもいいさ。",
  str_homestory_chat_13621005 = "今、食べ物に文句言ったばっかりなのは誰？",
  str_homestory_chat_13621006 = "要はトウガラシと塩が多めに入ってりゃ、\nあとはどうでもいいのさ。",
  str_homestory_chat_13621007 = "それだけ？",
  str_homestory_chat_13621008 = "俺も、影狼も、うるさいことは言わん。",
  str_homestory_chat_13622001 = "何してるの？",
  str_homestory_chat_13622002 = "…静かにしろ…影どもが休んでるんだ。",
  str_homestory_chat_13622003 = "影って休む必要があるの？",
  str_homestory_chat_13622004 = "…ああ。",
  str_homestory_chat_13622005 = "それ以上は説明してくれないの？",
  str_homestory_chat_13622006 = "…ああ。",
  str_homestory_chat_13622007 = "おしゃべりしたくないってことだね。",
  str_homestory_chat_13622008 = "ひとまず、そう理解してくれればいいさ。",
  str_homestory_chat_13622009 = "影が休み終わった頃に、また訪ねてくりゃいい。",
  str_homestory_chat_13623001 = "こんにちは、ヒドライ。",
  str_homestory_chat_13623002 = "ここは犬を飼ってるヤツが多いな。",
  str_homestory_chat_13623003 = "何か問題でも？",
  str_homestory_chat_13623004 = "犬は噛みつくから？",
  str_homestory_chat_13623005 = "違う。",
  str_homestory_chat_13623006 = "犬は吠えるから？",
  str_homestory_chat_13623007 = "ノドがつぶれてなきゃ、\n犬は吠えるもんさ。",
  str_homestory_chat_13623008 = "だったら、何が問題なの？",
  str_homestory_chat_13623009 = "俺が文句なんていつ言った？",
  str_homestory_chat_13623010 = "…",
  str_homestory_chat_14999999 = "ボス、俺に何か用か？誰かをシバいて欲しいのか？",
  str_homestory_chat_14901001 = "ただのあいさつだよ。",
  str_homestory_chat_14901002 = "なんだ…それだけか。",
  str_homestory_chat_14901003 = "誰かをシバくって時にゃ、俺を忘れんじゃねえぞ！",
  str_homestory_chat_14921001 = "手伝おうか？",
  str_homestory_chat_14921002 = "ボス、俺の鎧にホコリでも付いてないか？",
  str_homestory_chat_14921003 = "いや、きれいだよ",
  str_homestory_chat_14921004 = "きれいだって？",
  str_homestory_chat_14921005 = "鎧を磨いて時間をつぶそうと思ったんだがな…",
  str_homestory_chat_14921006 = "タイクツなの？",
  str_homestory_chat_14921007 = "ここじゃあ、ケンカの相手になるヤツもいねえからな。",
  str_homestory_chat_14921008 = "当然、タイクツになるだろ。",
  str_homestory_chat_14921009 = "少し付いてるよ",
  str_homestory_chat_14921010 = "どれどれ…ありがとよ、ボス。",
  str_homestory_chat_14922001 = "顔色が良くないみたいだね…",
  str_homestory_chat_14922002 = "ボス、腹が減って仕方ねぇ…",
  str_homestory_chat_14922003 = "もう何日も野菜しか食ってねぇんだ…",
  str_homestory_chat_14922004 = "野菜は体にいいんだよ",
  str_homestory_chat_14922005 = "ボス、その言葉は、俺みてぇな\n肉なしで生きてけねぇヤツにとっちゃ…",
  str_homestory_chat_14922006 = "残酷な言葉だぜ！？",
  str_homestory_chat_14922007 = "僕も野菜は苦手…",
  str_homestory_chat_14922008 = "でも、ふところ具合が厳しいから、\nガマンして食べるしかない！",
  str_homestory_chat_14922009 = "ボスも大変な生活してんだなぁ…",
  str_homestory_chat_14951001 = "水の中に大きなエビが…",
  str_homestory_chat_14951002 = "おっ、天空ノ庭のボス、あんたも見たのか！",
  str_homestory_chat_14951003 = "その言い方はやめて…",
  str_homestory_chat_14951004 = "分かった分かった！\nそれはともかく、まさかこんなとこに大エビがいるなんて驚きだよなぁ。",
  str_homestory_chat_14951005 = "あのデカさ！影ノ街に売ったら、間違いなく大もうけできるぜ！",
  str_homestory_chat_14951006 = "え、そうなの？",
  str_homestory_chat_14951007 = "ああ。あの大エビ、闘争心が強そうだろ？\n観賞用にはもってこいだ。",
  str_homestory_chat_14951008 = "アイツらの殴り合ってる姿、\nなんだか段々俺の大剣に見えてきたな…",
  str_homestory_chat_14951009 = "腕がムズムズしてくるぜ。思わず手出ししたくなっちまうな…",
  str_homestory_chat_14951010 = "それは体格差ありすぎでしょ…",
  str_homestory_chat_14951011 = "ま、だから見てるしかねぇんだけどさ。\n影ノ街のヤツらも、きっと同じように思うはずだぜ。",
  str_homestory_chat_14951012 = "戦ってる姿を見ると、こっちまで胸が熱くなるってもんだ！",
  str_homestory_chat_14951013 = "その様子だと、きっと影ノ街でも大人気なんだろうね。",
  str_homestory_chat_14951014 = "（これは大もうけのチャンスかも…）",
  str_homestory_chat_14951015 = "君、大エビに詳しいみたいだね？",
  str_homestory_chat_14951016 = "当然だろ。まず、あの大エビの名前は「ロブ」ってんだ。",
  str_homestory_chat_14951017 = "アイツらの姿は、結構あちこちで見かけるぜ。",
  str_homestory_chat_14951018 = "へえ、結構いろんなところにいるんだね？",
  str_homestory_chat_14951019 = "おう。それだけじゃねぇぜ、種類が違うヤツもいるんだ。",
  str_homestory_chat_14951020 = "えっ、いろいろいるの？",
  str_homestory_chat_14951021 = "いや、2種類だけだ。わりとよく見るのはあの青いやつだな。",
