  str_homestory_chat_14951023 = "だろうな。青いのと茶色いのがいて、茶色い方がレアモノなんだ。",
  str_homestory_chat_14951024 = "つっても、あれを手に入れんのはそう簡単じゃないがな…",
  str_homestory_chat_14951025 = "じゃあ、どうやって捕まえればいいの？",
  str_homestory_chat_14951026 = "まず青いほうのロブ――学名「ロマンロブ」を手に入れるんだ。",
  str_homestory_chat_14951027 = "いま手元にあるんなら、\nそれと交換でデカくて茶色いロブの釣り場を教えてやるぜ。",
  str_homestory_chat_14951028 = "うーん…教えてくれるだけ？",
  str_homestory_chat_14951029 = "オッ、あんたも駆け引きってもんを覚えたのか？\nじゃあ、天空ノ庭のボスには特別サービスをつけてやるよ。",
  str_homestory_chat_14951030 = "とにかく、あんたに損はさせねぇ。",
