  str_homestory_chat_11922008 = "い、いや、やっぱり遠慮しとくよ…",
  str_homestory_chat_11922009 = "遠慮しとくよ…",
  str_homestory_chat_11922010 = "目に恐怖が浮かんでいるわ。",
  str_homestory_chat_11922011 = "何を恐れているのかしら？\n飲む物は、あなたが選ぶのよ。",
