  str_homestory_chat_11924004 = "今後、皆に食事を出すような時は…",
  str_homestory_chat_11924005 = "私のことを忘れておきなさい。",
  str_homestory_chat_11924006 = "どうして？",
  str_homestory_chat_11924007 = "知っているでしょう。\n私はそういう施しを受けたくないの。",
