  str_homestory_chat_10922004 = "また何か怪しいことを企んでない…？",
  str_homestory_chat_10922005 = "まったく根拠がない疑いだとは言えないね。",
  str_homestory_chat_10922006 = "真理を追い求める者として、\n僕のなすことにはすべて、何らかの意味がある。",
