  str_homestory_chat_10922008 = "や、やっぱりいいや…",
  str_homestory_chat_10922009 = "そうだなあ…",
  str_homestory_chat_10922010 = "どうやら、正確なことを思いだすには\n時間がかかりそうだね。",
