  str_homestory_chat_15821006 = "もし次があったら、無事で済まないかもよ？",
  str_homestory_chat_15821007 = "わ、私…わざとでは…",
  str_homestory_chat_15821008 = "どうしてそんなに力いっぱい旗槍を振るの？",
