  str_homestory_chat_17923008 = "日常的な積み重ねが、最終的に大きな穴を作るのです。",
  str_homestory_chat_17923009 = "十分お気を付けを。",
  str_homestory_chat_19199999 = "ごきげんよう…",
  str_homestory_chat_19101001 = "こんにちは、クロエ。",
  str_homestory_chat_19101002 = "ジャマしちゃったかな？",
  str_homestory_chat_19101003 = "そんなことはありません。\nむしろ…私を悲しみの中から救い出してくださいました。",
  str_homestory_chat_19121001 = "何してるの？",
  str_homestory_chat_19121002 = "…お祈りをしていたところです。\n何かお話になりたいのですか？",
  str_homestory_chat_19121003 = "ああ、心配しないでください。\nお祈りを中断したわけではありません。",
  str_homestory_chat_19121004 = "一人でいるよりも、\nあなたとお話ししたいと思っています。",
  str_homestory_chat_19121005 = "時間がある時はお祈りをしているの？",
  str_homestory_chat_19121006 = "ハープの練習もしています。",
  str_homestory_chat_19121007 = "お祈りは、ひとときの安寧を得るためです。",
  str_homestory_chat_19122001 = "パーティで演奏してもらえるかな？",
  str_homestory_chat_19122002 = "…私を招待してくださっているのですか？",
  str_homestory_chat_19122003 = "そうだよ",
  str_homestory_chat_19122004 = "皆にハープの音を聞いて、心を安らげてもらいたいんだ。",
