  str_homestory_chat_19122008 = "いいえ、ご安心ください。\nそういうことではありません。",
  str_homestory_chat_19122009 = "むしろ、喜んでお受けいたします。",
  str_homestory_chat_19122010 = "誰かのために演奏する機会は、とても大切です。",
  str_homestory_chat_18499999 = "今日も会ったな、PlayerName。",
  str_homestory_chat_18401001 = "こんにちは、イスタバンさん。",
  str_homestory_chat_18401002 = "何か言いたいことがあるなら、言うことだ。",
  str_homestory_chat_18401003 = "え？ええと…\nまずは考えさせてもらってもいいですか…？",
  str_homestory_chat_18421001 = "ここはどうですか？",
  str_homestory_chat_18421002 = "お前から招待されるとは、嬉しい限りだ。",
  str_homestory_chat_18421003 = "いろんな奴らの知られざる顔を\n見ることができたしな。",
  str_homestory_chat_18421004 = "…まさか、良くないことを考えてる人が？",
  str_homestory_chat_18421005 = "ハハハ、心配はいらん。",
  str_homestory_chat_18421006 = "俺はただ、皆が仮面の下に隠している自分をさらけ出し、\n気楽に過ごせる所だと言いたいだけだ。",
  str_homestory_chat_18421007 = "知られざる一面？",
  str_homestory_chat_18421008 = "注意深く観察すれば、分かるはずだ――",
  str_homestory_chat_18421009 = "一部の者は、普段と振る舞いが全く違う。",
