  str_homestory_chat_18423007 = "ずいぶんあっさり答えたな？",
  str_homestory_chat_18423008 = "報酬は聞かなくていいのか？",
  str_homestory_chat_18423009 = "大したことではないですし、報酬なんて要りません。",
  str_homestory_chat_18423010 = "ハハハ…お前の気前のよさは賞賛に値する。",
