  str_homestory_chat_17021004 = "あら、じゃあ何て呼んだらいいのかしら？\n坊や、自分で一つ選びなさい。",
  str_homestory_chat_17021005 = "考えてあげなくもないわ。",
  str_homestory_chat_17021006 = "それは、その…",
