  str_homestory_chat_19624005 = "でも、ここでは1回もサギに遭ってないの。",
  str_homestory_chat_19624006 = "…ほ、本当に？",
  str_homestory_chat_19624007 = "お金を取るだけが「サギ」じゃないよ？",
  str_homestory_chat_20399999 = "PlayerName、今日はどんな予定？",
  str_homestory_chat_20301001 = "予定はないよ",
  str_homestory_chat_20301002 = "そう？じゃ、尋問しなきゃいけない人は？",
  str_homestory_chat_20301003 = "そんな人、いたことある？",
  str_homestory_chat_20301004 = "いるの、いないの？",
  str_homestory_chat_20301005 = "いないよ！",
  str_homestory_chat_20321001 = "その眼帯…",
  str_homestory_chat_20321002 = "右目の眼帯ばっかり見ないでくれる？",
  str_homestory_chat_20321003 = "眼帯にも魔力があるの？",
  str_homestory_chat_20321004 = "そんなはずないでしょ？\nこれはビクトリア姐さんがくれた眼帯よ…",
  str_homestory_chat_20321005 = "万一なんて起こるはずもないわ！",
  str_homestory_chat_20321006 = "それなら…",
  str_homestory_chat_20321007 = "ああ、そういう話じゃないわ！",
  str_homestory_chat_20321008 = "「右目の眼帯を見ないで」って言ったのは――",
  str_homestory_chat_20321009 = "眼帯に問題があるからじゃなくて、\nそればっかり見てるあなたがおかしいからよ。",
  str_homestory_chat_20322001 = "何考えてるの？",
  str_homestory_chat_20322002 = "ここに来てから、\nずいぶん長いこと「あれ」を見てないわ…",
  str_homestory_chat_20322003 = "「あれ」？",
  str_homestory_chat_20322004 = "つまり…鮮血とか、苦痛で歪んだ顔とかよ。",
  str_homestory_chat_20322005 = "ちょっとタイクツだわ。",
  str_homestory_chat_20322006 = "…",
  str_homestory_chat_20323001 = "尋問室について聞きたいことがあるって？",
  str_homestory_chat_20323002 = "そうよ、いつ建てるの？",
  str_homestory_chat_20323003 = "尋問室なんて必要あるの？",
  str_homestory_chat_20323004 = "尋問室が無いと、あたしの仕事がやりづらいでしょ。",
  str_homestory_chat_20323005 = "ここに尋問室ができることはないよ",
  str_homestory_chat_20323006 = "そもそも、罪人なんていないし。",
  str_homestory_chat_20323007 = "今はいなくても、将来は？",
  str_homestory_chat_20323008 = "PlayerName、早く建てましょ。私も手伝うから。",
  str_homestory_chat_20323009 = "絶対にダメ！",
  str_homestory_chat_20324001 = "買いたい物があるの？",
  str_homestory_chat_20324002 = "そう、眼帯！",
  str_homestory_chat_20324003 = "眼帯？",
  str_homestory_chat_20324004 = "いつもこの眼帯をしてるから、ちょっと飽きてきたような気がして。",
  str_homestory_chat_20324005 = "ビクトリア姐さんが最近あまり話しかけてくれないのも、きっとこの眼帯を見すぎたせいよ。",
  str_homestory_chat_20324006 = "新しい眼帯はどんな色とデザインがいいと思う？",
  str_homestory_chat_20324007 = "白？赤？ハート形？それともレースのフリル付き？",
  str_homestory_chat_20324008 = "えっと…",
  str_homestory_chat_20324009 = "聞く相手を間違った気がする。バイスに聞いたほうがいいかもね？",
  str_homestory_chat_20324010 = "バイスは…",
  str_homestory_chat_20324011 = "何かバイスに文句があるみたいね。へっへーん、メモしておこう。",
  str_homestory_chat_20324012 = "やめて！",
  str_homestory_chat_20325001 = "訓練したいって？",
  str_homestory_chat_20325002 = "そう。ここに長くいすぎて、近ごろ尋問テクニックがおろそかになったような気がして。",
  str_homestory_chat_20325003 = "そんなの練習しなくてもいいんじゃない…？",
  str_homestory_chat_20325004 = "なんでよ！これはあたしの唯一の楽しみ――じゃなくて、特技なんだから。",
  str_homestory_chat_20325005 = "尋問したいなら正直にそう言えばいいのに。残念ながらここではダメだけど。",
  str_homestory_chat_20325006 = "えー？どうして！",
  str_homestory_chat_20325007 = "天空ノ庭に来たんなら、やっぱり生活を楽しもうよ…",
  str_homestory_chat_20325008 = "楽しむ…あたしにとっては尋問もひとつの楽しみなんだけど。",
  str_homestory_chat_20325009 = "なんなら…キューブたちを練習台にしようかな？見るからに四角張っててシロだけど。",
  str_homestory_chat_20325010 = "ダメ！ゼッタイ！",
  str_homestory_chat_20326001 = "宿舎…",
  str_homestory_chat_20326002 = "なんで分かったの？ひと言つぶやいただけなのに、もうあなたの耳まで届いたの？",
  str_homestory_chat_20326003 = "ま、聞きに来てくれて、探しに行く手間が省けたわ。宿舎を建てたいんだけど、どう思う？",
  str_homestory_chat_20326004 = "何のために？",
  str_homestory_chat_20326005 = "何のためかは聞かないで。いいかどうかだけ答えて。",
  str_homestory_chat_20326006 = "それはダメだよ！目的を先に言ってもらわなきゃ。",
  str_homestory_chat_20326007 = "ダメだよ…",
  str_homestory_chat_20326008 = "え？何のためかまだ聞いてもいないのに、どうしてダメなの？",
  str_homestory_chat_20326009 = "何か問題があるような気がするから。一体何のために建てるの？",
  str_homestory_chat_20326010 = "ええと…ビクトリア姐さんのために建てたいの。",
  str_homestory_chat_20326011 = "姐さんが他の人と同じ宿舎に住んでいるのを見るたびに、まずいなって思うんだ。",
  str_homestory_chat_20326012 = "だって、ビクトリア様なのよ！",
  str_homestory_chat_20326013 = "ちょ、ちょっと考えさせて。",
  str_homestory_chat_19399999 = "こんにちは、ボーヤ。",
  str_homestory_chat_19301001 = "こんにちは、ミジャード。",
  str_homestory_chat_19301002 = "今日こそ私に解剖される気になった？",
  str_homestory_chat_19301003 = "ち、違うよ！絶対に違う！",
  str_homestory_chat_19301004 = "それなら、あと少し考える時間をあげるわ。",
  str_homestory_chat_19321001 = "時間ある？",
  str_homestory_chat_19321002 = "何を話したいの？",
  str_homestory_chat_19321003 = "面白い話にしてね。\nつまらない事なんて、聞く気にならないわ。",
  str_homestory_chat_19321004 = "え…？じゃあ、僕はどうすれば？",
  str_homestory_chat_19321005 = "自分の頭の中で判断しなさい。\n話そうとしてることが面白いかどうか。",
  str_homestory_chat_19321006 = "…",
  str_homestory_chat_19321007 = "話すの、やめるよ…",
  str_homestory_chat_19321008 = "そう、分かったわ。",
  str_homestory_chat_19322001 = "ここでの暮らしには慣れた？",
  str_homestory_chat_19322002 = "気分良く過ごしてるわ。ただ、少し退屈な時もあるわね。",
  str_homestory_chat_19322003 = "お酒でもあればよかったんだけど。",
  str_homestory_chat_19322004 = "お酒ならここにもあるよ…",
  str_homestory_chat_19322005 = "残念だけど、どれも好きじゃないの。",
  str_homestory_chat_19322006 = "ここにお酒は無かったっけ？",
  str_homestory_chat_19322007 = "私、好ききらいは激しくない方だけど…",
  str_homestory_chat_19322008 = "ここのお酒はいいところが無さすぎるわ。",
  str_homestory_chat_19322009 = "私がリストを作ってあげるから、注文してくれない？",
  str_homestory_chat_19322010 = "いいよ。",
  str_homestory_chat_19323001 = "今日は何をするつもり？",
  str_homestory_chat_19323002 = "寝るのにいい日ね。そう思わない？",
  str_homestory_chat_19323003 = "思わないよ…",
  str_homestory_chat_19323004 = "まだたくさんやってないことがあると思うと、\n全然寝付けないんだ…",
  str_homestory_chat_19323005 = "なら、仕事してなさい。私は寝るわ。",
  str_homestory_chat_19323006 = "そうだね",
  str_homestory_chat_19323007 = "一年中、眠くない時なんてないよ。",
  str_homestory_chat_19323008 = "あら、気が合うわね。",
  str_homestory_chat_19323009 = "だったら、一緒に寝ましょうか…",
  str_homestory_chat_19323010 = "…い、いや、ちょっと待って…\nぼ、僕はまだやり終えてないことがあるから！",
  str_homestory_chat_19799999 = "よう、PlayerName。",
  str_homestory_chat_19701001 = "こんにちは。",
  str_homestory_chat_19701002 = "病気か？",
  str_homestory_chat_19701003 = "…病気じゃないよ、どうしてそんなこと聞くの？",
  str_homestory_chat_19701004 = "誰かが俺にそういうあいさつをしたら、\nおおかた、病気を診てほしくて来たヤツだ。",
  str_homestory_chat_19721001 = "きれい好きなんだね。",
  str_homestory_chat_19721002 = "必要なら、俺の手の洗い方を広めてやってもいいぞ。",
  str_homestory_chat_19721003 = "いいね！",
  str_homestory_chat_19721004 = "そうすれば、皆きっと病気にならなくなるね。",
  str_homestory_chat_19721005 = "当然だ。だが、俺の教えた方法を\n徹底してやることが前提だな――",
  str_homestory_chat_19721006 = "1回で5分はかけてな。",
  str_homestory_chat_19721007 = "…うーん、そこまでは…",
  str_homestory_chat_19721008 = "たぶん必要ないよ…",
  str_homestory_chat_19721009 = "みんながみんな、\n5分もかけて手を洗いたいわけじゃないだろうし…",
  str_homestory_chat_19721010 = "…俺が手を洗っているところを見たのか？",
  str_homestory_chat_19722001 = "日差しは好きじゃないの？",
  str_homestory_chat_19722002 = "少しまぶしいのは確かだな。",
  str_homestory_chat_19722003 = "正確には、日差しが嫌いなわけじゃない――",
  str_homestory_chat_19722004 = "明るすぎるのがきらいなだけさ。",
  str_homestory_chat_19722005 = "太陽が雲に覆われた程度の光なら、まだマシなんだが。",
  str_homestory_chat_19722006 = "なるほど。",
  str_homestory_chat_19723001 = "その服は…",
  str_homestory_chat_19723002 = "俺の服がみっともないって苦情が来てるらしいな？",
  str_homestory_chat_19723003 = "実はそうなんだ…",
  str_homestory_chat_19723004 = "…チッ、なんだって俺の服なんか気にするんだ。",
  str_homestory_chat_19723005 = "それとも、そいつらは俺みたいな格好になりたいのか？",
  str_homestory_chat_19723006 = "何するつもり？",
  str_homestory_chat_19723007 = "氷のメスは、布もよく切れるんだ…",
  str_homestory_chat_19723008 = "や、やめてよ！？",
  str_homestory_chat_12499999 = "あ、こんにちは。",
  str_homestory_chat_12401001 = "あ、クロ。",
  str_homestory_chat_12401002 = "ベニはどこに行ったの？",
  str_homestory_chat_12401003 = "こっちが聞きたいわ。",
  str_homestory_chat_12401004 = "そうなんだ…",
  str_homestory_chat_12421001 = "何を探してるの？",
  str_homestory_chat_12421002 = "ベニを見かけなかった？",
  str_homestory_chat_12421003 = "何か用でも？",
  str_homestory_chat_12421004 = "私にケンカで勝つつもりらしくて、挑戦してきたの。",
  str_homestory_chat_12421005 = "ここでケンカはやめて！？",
  str_homestory_chat_12421006 = "大丈夫よ。あなたは審判やってちょうだい。",
  str_homestory_chat_12421007 = "ダメだよ、殴り合いは禁止！",
  str_homestory_chat_12422001 = "僕に用？",
  str_homestory_chat_12422002 = "そうよ。もしベニを見かけたら、\nあのおバカを黙らせておいて。",
  str_homestory_chat_12422003 = "それは…ちょっと難しいかな…",
  str_homestory_chat_12422004 = "早口で、全然口をはさめないし…",
  str_homestory_chat_12422005 = "自分で黙らせないの？",
  str_homestory_chat_12422006 = "ツバの無駄づかいなんかしたくないわ。",
  str_homestory_chat_12422007 = "…そうなんだ。",
  str_homestory_chat_12423001 = "これから休憩？",
  str_homestory_chat_12423002 = "ベニはね。食べ過ぎたの。",
  str_homestory_chat_12423003 = "でも、私はもうちょっとここにいるわ。",
  str_homestory_chat_12423004 = "こんな早くから休むなんて、私らしくないもの。",
  str_homestory_chat_19899999 = "PlayerNameさん、\n今日はまた会ったね…",
  str_homestory_chat_19801001 = "こんにちは、クスッタ。",
  str_homestory_chat_19801002 = "ここには慣れた？",
  str_homestory_chat_19801003 = "たぶん。",
  str_homestory_chat_19801004 = "慣れてない時の気持ちも、\n私には想像できないの。",
  str_homestory_chat_19821001 = "何か話したいことはない？",
  str_homestory_chat_19821002 = "感情があって初めて、\n他人に何かを伝えることができるのかもしれないわ。",
  str_homestory_chat_19821003 = "でも、私には…それが難しい。",
  str_homestory_chat_19821004 = "私はいい聞き手になるって言った人がいた。",
  str_homestory_chat_19821005 = "いつでもいいから、何でも私に話して。\n話に文句をつけて、あなたを困らせることもないから。",
  str_homestory_chat_19821006 = "そうするよ…",
  str_homestory_chat_19822001 = "何を考えてるの？",
  str_homestory_chat_19822002 = "長いこと、新しい黒バラが咲いてない。",
  str_homestory_chat_19822003 = "いい事のように聞こえるけど？",
  str_homestory_chat_19822004 = "多くの人にとっては、そう。",
  str_homestory_chat_19822005 = "あれは屍に咲く花だから。",
  str_homestory_chat_19822006 = "悪い事なの？",
  str_homestory_chat_19822007 = "いいか悪いかは知らない。",
  str_homestory_chat_19822008 = "でも、黒いバラは屍に咲くの。",
  str_homestory_chat_19822009 = "興味があるなら、摘んであげる。",
  str_homestory_chat_19822010 = "ひ、必要ないよ…",
  str_homestory_chat_19823001 = "食べ物は何が好き？",
  str_homestory_chat_19823002 = "好きな食べ物はない。嫌いなものも。",
  str_homestory_chat_19823003 = "食べ物の味は分からない…",
  str_homestory_chat_19823004 = "あなたたちの口に合ってるどうかも、分からない。",
  str_homestory_chat_19823005 = "ううん、じゃあ、今度僕に何か食べさせてくれる？",
  str_homestory_chat_19823006 = "いいわ…でも、時どき塩と砂糖を間違えるの。\nそれでもいい？",
  str_homestory_chat_19823007 = "うーん…",
  str_homestory_chat_19999999 = "PlayerNameさん、こんにちは。",
  str_homestory_chat_19921001 = "今日の調子はどう？",
  str_homestory_chat_19921002 = "私のことは心配ありません。\n最近は体の黒いトゲも増えていませんし…",
  str_homestory_chat_19922001 = "何か考え事？",
  str_homestory_chat_19922002 = "ここの小さな動物たちは、\n私になついてくれるでしょうか…",
  str_homestory_chat_19922003 = "小動物が好きなの？",
  str_homestory_chat_19922004 = "はい…昔、私に寄り添ってくれていたので。",
  str_homestory_chat_19922005 = "今は…この黒いトゲのせいで、人だけではなく、\n小動物も逃げてしまいますが…",
  str_homestory_chat_19922006 = "なついてくれないの？",
  str_homestory_chat_19922007 = "昔はそうでもなかったんですが…\nでも、この体に黒いトゲが生えてからは…",
  str_homestory_chat_19922008 = "それに、私も動物たちを傷つけてしまうのが怖くて…",
  str_homestory_chat_19922009 = "なるほど…",
  str_homestory_chat_19923001 = "何か手助けは要る？",
  str_homestory_chat_19923002 = "PlayerNameさん、服を見てもらえますか？",
  str_homestory_chat_19923003 = "どうしたの？",
  str_homestory_chat_19923004 = "トゲが…また服を破いてしまった気がするんです。",
  str_homestory_chat_19923005 = "大丈夫だよ",
  str_homestory_chat_19923006 = "それなら、よかった…",
  str_homestory_chat_19923007 = "新しい服を注文しなくて済みます！",
  str_homestory_chat_19923008 = "本当だ…",
  str_homestory_chat_19923009 = "でも、小さい穴だし、\nじっと見てなきゃ分からないよ。",
  str_homestory_chat_19923010 = "そうですか…だったら、もうしばらくこの服を\n着ていられますね。",
  str_homestory_chat_19923011 = "ありがとうございます、PlayerNameさん。",
  str_homestory_chat_19924001 = "音楽に興味はある？",
  str_homestory_chat_19924002 = "ええと…はい。",
  str_homestory_chat_19924003 = "ここには歌を歌う方や楽器を演奏する方が多いですよね。",
  str_homestory_chat_19924004 = "お友だちになれたらと思いますが…",
  str_homestory_chat_19924005 = "じゃあ今度、音楽の出来る友だちを紹介するよ。",
  str_homestory_chat_19924006 = "ご親切に、ありがとうございます！",
  str_homestory_chat_20099999 = "私にあいさつしたのかしら？",
  str_homestory_chat_20001001 = "そうだよ、スカーレイ。",
  str_homestory_chat_20001002 = "何か僕に話したいことはある？",
  str_homestory_chat_20001003 = "今のところ、ないわ。",
  str_homestory_chat_20021001 = "誰かがうるさくしたりしてない？",
  str_homestory_chat_20021002 = "わざと音を出しているような人はいないようだけど…",
  str_homestory_chat_20021003 = "もっと静かな方が好みね。",
  str_homestory_chat_20021004 = "聞こえてくるのは風の音と鳥や虫の声だけ――\nここの夜も、そういう静けさがあるべきだと思わない？",
  str_homestory_chat_20022001 = "僕に用？",
  str_homestory_chat_20022002 = "ボーヤ、古書を探してきてもらえる？",
  str_homestory_chat_20022003 = "喜んで！",
  str_homestory_chat_20022004 = "いい快諾ぶりね。",
  str_homestory_chat_20022005 = "そういうことなら、私を見ていないで、さっさと行動しなさい。\n早く持ってきて。",
  str_homestory_chat_20022006 = "それ以上はないよ…",
  str_homestory_chat_20022007 = "…まさか、私に虫ケラどもの騒ぎでも\n聞いていろとでもいうつもり？",
  str_homestory_chat_20022008 = "…分かった、出来る限り探してくるよ…",
  str_homestory_chat_20022009 = "それでこそ、私のボーヤよ。",
  str_homestory_chat_20023001 = "そのベール…",
  str_homestory_chat_20023002 = "あまりじろじろ見ないでもらえる？",
  str_homestory_chat_20023003 = "外したりしないの？",
  str_homestory_chat_20023004 = "いつも黒いベールをかぶってるなんて、面倒でしょ。",
  str_homestory_chat_20023005 = "逆よ。私はこのベールが好きなの。",
  str_homestory_chat_20023006 = "私とうるさい虫ケラどもの間に\n仕切りを作ってくれるもの。",
  str_homestory_chat_20023007 = "でも、あなたにはベールを上げてあげる。",
  str_homestory_chat_20024001 = "何か聞きたいことがあるの？",
  str_homestory_chat_20024002 = "ええ…ひとつ聞きたいのだけれど、\nここにはどこか、秘密の場所はある？",
  str_homestory_chat_20024003 = "あるよ",
  str_homestory_chat_20024004 = "たとえば、川とか、木のうろとか、\n山のふもとの洞窟とか…？",
  str_homestory_chat_20024005 = "あまり安全とは言えないわね。\n誰かに見つかってしまいそうだもの。",
