  str_homestory_chat_20024007 = "人目につきにくい所は色々あるけど、\nキューブたちが探索してるよ。",
  str_homestory_chat_20024008 = "そう。",
  str_homestory_chat_20024009 = "ところで、秘密の場所って、何をしたいの？\n何かを隠すとか？",
  str_homestory_chat_20024010 = "そうよ。\n「ファリア」を失くさないように。",
  str_homestory_chat_20024011 = "ボーヤのところに置いておくのが、\n一番安全じゃないかしら？",
  str_homestory_chat_20024012 = "さすがにちょっと、責任持てないかな…",
  str_homestory_chat_20025001 = "何か考え事？",
  str_homestory_chat_20025002 = "あなたの使命について考えているの。",
  str_homestory_chat_20025003 = "使命？",
  str_homestory_chat_20025004 = "ボーヤ、一生ここで過ごすつもりはないでしょう？\nいつかは前に進む時が来るもの。",
  str_homestory_chat_20025005 = "僕はまだ、そんな先のことは考えたことないよ。",
  str_homestory_chat_20025006 = "時々考えておくといいわ。\nここだって、拠点の1つに過ぎない。",
  str_homestory_chat_20025007 = "私には分かるの。\nあなたの未来は遠く、そして大きく広がっている。",
  str_homestory_chat_20025008 = "…まじめな話みたいだね。",
  str_homestory_chat_20025009 = "そうよ。\nその時がきたら、私がここを守ってあげるわ…",
  str_homestory_chat_20025010 = "今まで墓所を守ってきたようにね。",
  str_homestory_chat_20025011 = "そ、それは…ありがとう。",
  str_homestory_chat_18799999 = "わたくしにあいさつは結構。\n用があるなら、直接言いなさい。",
  str_homestory_chat_18701001 = "うん、分かった…",
  str_homestory_chat_18701002 = "あいさつなど、時間の無駄だもの。",
  str_homestory_chat_18701003 = "待って…僕は何を言おうとしてたんだっけ？",
  str_homestory_chat_18721001 = "何を探してるの？",
  str_homestory_chat_18721002 = "ここで伝統的なお芝居はやっているの？",
  str_homestory_chat_18721003 = "ないよ…",
  str_homestory_chat_18721004 = "伝統的な演劇とかって、古臭いと思われがちでしょ。",
  str_homestory_chat_18721005 = "ここで公演しても、たぶん見る人がいないと思う。",
  str_homestory_chat_18721006 = "仕方がないわね。何か別のことをするとしましょう。",
  str_homestory_chat_18721007 = "いっそ主催しようかな",
  str_homestory_chat_18721008 = "貴方には驚かされるわ。",
  str_homestory_chat_18721009 = "けれど、会場を用意するにも、きちんとした役者に来てもらうにも、\n多額の費用が必要になるのよ。",
  str_homestory_chat_18721010 = "おそらく、観客も多くはないでしょうね。",
  str_homestory_chat_18721011 = "それでも、開催するつもり？",
  str_homestory_chat_18721012 = "もちろんだよ。",
  str_homestory_chat_18721013 = "それなら、楽しみにしておくわ。",
  str_homestory_chat_18722001 = "練習中？",
  str_homestory_chat_18722002 = "貴方、ダーツは出来て？",
  str_homestory_chat_18722003 = "出来るよ！",
  str_homestory_chat_18722004 = "あら？それは嬉しい限りだわ。",
