  str_homestory_chat_18722006 = "い、今から？",
  str_homestory_chat_18722007 = "他に用事があったかしら？\nでは、次の機会にいかが？",
  str_homestory_chat_18722008 = "いいよ！",
  str_homestory_chat_18722009 = "できない…",
  str_homestory_chat_18722010 = "出来なくても構わなくってよ。\nダーツボードを持って立っていただければ。",
  str_homestory_chat_18722011 = "…断ってもいい？",
  str_homestory_chat_18722012 = "どうして？わたくしが貴方に当てるとでも？",
  str_homestory_chat_18723001 = "気楽に過ごして",
  str_homestory_chat_18723002 = "ここは安全だし、いつも気を張り詰める必要はないよ。",
  str_homestory_chat_18723003 = "貴方の招待を受けて来たからには、\nこの地の平民はわたくしが守らせていただくわ。",
  str_homestory_chat_18723004 = "それは…どうもありがとう。",
