  str_homestory_chat_15601002 = "いい答えだ、気に入ったぜ。",
  str_homestory_chat_15621001 = "何を考えてるの？",
  str_homestory_chat_15621002 = "ここの夜は、一人で静かに座ってるのにいいな。",
  str_homestory_chat_15621003 = "おまえも試してみるか？",
  str_homestory_chat_15621004 = "いいね！",
  str_homestory_chat_15621005 = "静かな所を探しといてやるよ。",
  str_homestory_chat_15621006 = "約束を忘れんじゃねえぞ。",
  str_homestory_chat_15621007 = "遠慮しとくよ…",
  str_homestory_chat_15621008 = "怖いのか？",
  str_homestory_chat_15621009 = "心配することはねえ。おまえを傷つけるものは、ここにはねえよ。",
  str_homestory_chat_15622001 = "ここには慣れた？",
  str_homestory_chat_15622002 = "北境よりいいぐらいだ――",
  str_homestory_chat_15622003 = "こんな所で落ち着けるなんて、思わなかったぜ。",
