  str_homestory_chat_19522001 = "住み心地はどう？",
  str_homestory_chat_19522002 = "ここにゃあ居心地のいい洞窟がたくさんありやしたんで、\nもうたくさん中にものをいれたところでござんす。",
  str_homestory_chat_19522003 = "いつでも見学に来てくだせえ。",
