  str_homestory_chat_16222008 = "じゃあ、植木鉢なら、いいかな？",
  str_homestory_chat_16223001 = "何か言いたそうだけど？",
  str_homestory_chat_16223002 = "うん、ここに来るといつも、この場所の地の利に感嘆せずにいられないんだ。",
  str_homestory_chat_16223003 = "地の利？",
