  str_homestory_chat_19422002 = "こ、この道の…パトロール中だよ…必要なかったかな？",
  str_homestory_chat_19422003 = "パトロールは必要ないよ。",
  str_homestory_chat_19422004 = "そ、そうなの…？\nボク、毎日パトロールするのが習慣になってたみたい。",
  str_homestory_chat_19422005 = "そういうことなら、ボクはひと眠りするね…",
  str_homestory_chat_19422006 = "ありがとう！",
  str_homestory_chat_19422007 = "ど、どういたしまして…パトロールは、ボクの習慣なんだ。",
  str_homestory_chat_19422008 = "それに、キミのために何かしたくて…",
  str_homestory_chat_20799999 = "…ああ。",
  str_homestory_chat_20701001 = "こんにちは。",
  str_homestory_chat_20701002 = "今日の訓練を始めるの？",
  str_homestory_chat_20701003 = "そうだ、邪魔しないでもらいたい。",
  str_homestory_chat_20701004 = "うっ、うん。",
  str_homestory_chat_20721001 = "おしゃべりでもしない？",
  str_homestory_chat_20721002 = "…私にはやる事がある。",
  str_homestory_chat_20721003 = "…そ、そっか…",
  str_homestory_chat_20899999 = "…私に近づきすぎないで。",
  str_homestory_chat_20801001 = "ご、ごめん。",
  str_homestory_chat_20801002 = "ゆっくりと立ち去りなさい。",
  str_homestory_chat_20801003 = "わ、分かったよ。",
  str_homestory_chat_20821001 = "今日はどんな予定？",
  str_homestory_chat_20821002 = "…特にないわ。",
  str_homestory_chat_20821003 = "私には近寄らない方が身のためよ。危ないから。",
  str_homestory_chat_20821004 = "そ、そう…",
  str_homestory_chat_20999999 = "…",
  str_homestory_chat_20901001 = "こんにちは。",
  str_homestory_chat_20901002 = "こんにちは。",
  str_homestory_chat_20901003 = "答えてくれるとは思わなかったよ。",
  str_homestory_chat_20921001 = "昔のこと、話してくれない？",
  str_homestory_chat_20921002 = "…いいえ…今はそういう気分じゃないわね…",
  str_homestory_chat_20921003 = "そっか…",
  str_homestory_chat_21099999 = "こんにちは。",
  str_homestory_chat_21001001 = "こんにちは。",
  str_homestory_chat_21001002 = "今日は気分がいいの？",
  str_homestory_chat_21001003 = "たまにはね。",
  str_homestory_chat_21021001 = "ここには慣れた？",
  str_homestory_chat_21021002 = "…そうね、まあまあだわ。",
  str_homestory_chat_21021003 = "何かあれば、僕に言ってね。",
  str_homestory_chat_21021004 = "…ええ。",
  str_homestory_chat_16799999 = "PlayerName、こんにちは～！",
  str_homestory_chat_16701001 = "こんにちは、アリス。",
  str_homestory_chat_16701002 = "新しい童話の本は見つかった？",
  str_homestory_chat_16701003 = "ごめん、まだ見つかってないんだ。",
  str_homestory_chat_16701004 = "急がなくていいよ。\nそれより、まずは一緒に遊ぼ～！",
  str_homestory_chat_16721001 = "何を聞きたいの？",
  str_homestory_chat_16721002 = "ここに人に変身できるウサギって、いる？",
  str_homestory_chat_16721003 = "いないと思うよ…",
  str_homestory_chat_16721004 = "う～ん、いるって聞いた気がするんだけどな～…",
  str_homestory_chat_16721005 = "でも、いないなら、いいや…",
  str_homestory_chat_16721006 = "いた気がするけど…",
  str_homestory_chat_16721007 = "どこどこ？連れてってくれる？",
  str_homestory_chat_16721008 = "じっくり観察してれば、きっと見つかるよ。",
  str_homestory_chat_16722001 = "君の耳…",
  str_homestory_chat_16722002 = "ここって、あたしの耳が好きな人、たくさんいるんだね！",
  str_homestory_chat_16722003 = "迷惑かけられてない？",
  str_homestory_chat_16722004 = "メーワク？どうして？",
  str_homestory_chat_16722005 = "みんながあたしのことを好きなら、\nと～っても嬉しいことでしょ？",
  str_homestory_chat_16722006 = "それに、あたしの耳は触ってもいいんだよ～。",
  str_homestory_chat_16723001 = "何を探してるの？",
  str_homestory_chat_16723002 = "ここの芝生って、フェアリーが隠れてるのかな？",
  str_homestory_chat_16723003 = "隠れてるかもね…",
  str_homestory_chat_16723004 = "一緒に探して！",
  str_homestory_chat_16723005 = "あ…忙しいなら、また今度でもいいよ。",
  str_homestory_chat_16723006 = "たぶん、いないでしょ？",
  str_homestory_chat_16723007 = "フェアリーがいなくても、大地の精はいるんじゃないかな～。",
  str_homestory_chat_16723008 = "あたし、探してみる～。",
  str_homestory_chat_13099999 = "PlayerName、また会ったな！",
  str_homestory_chat_13001001 = "こんにちは、サメヤマ。",
  str_homestory_chat_13001002 = "お前、一日中うろついてんのか？",
  str_homestory_chat_13001003 = "…僕は忙しいの。分かった？",
  str_homestory_chat_13021001 = "何してるの？",
  str_homestory_chat_13021002 = "PlayerName、ここじゃ\n持って行っていいようなゴミは出ねぇのか？",
  str_homestory_chat_13021003 = "ゴミなんてどうするの？",
  str_homestory_chat_13021004 = "そりゃ、ゴミの中からいいモンを見つけて――",
  str_homestory_chat_13021005 = "カネにするんだ。決まってるだろ？",
  str_homestory_chat_13021006 = "そうなんだ？じゃあ、ゴミの山でも見つけたら、僕も呼んでよ。",
  str_homestory_chat_13021007 = "どんなゴミ？",
  str_homestory_chat_13021008 = "そりゃもちろん――いいモンが紛れてるのに決まってんだろ。",
  str_homestory_chat_13021009 = "例えば、この間俺が見つけた――",
  str_homestory_chat_13021010 = "爆発音を出す機械だとか、\n汚水をきれいにする装置とか…",
  str_homestory_chat_13021011 = "古代の遺産ってことだね…？",
  str_homestory_chat_13022001 = "僕に用？",
  str_homestory_chat_13022002 = "PlayerName、今度はいつクルマを飛ばすんだ？",
  str_homestory_chat_13022003 = "レースのこと？いいね！",
  str_homestory_chat_13022004 = "でも、空いてる時間があるか、見てみないと。",
  str_homestory_chat_13022005 = "よし！考えとけよ。",
  str_homestory_chat_13022006 = "人もできるだけ多く呼んどけよ――",
  str_homestory_chat_13022007 = "ここにいるヤツ全員でもいいぞ！",
  str_homestory_chat_13022008 = "やめとこうよ…",
  str_homestory_chat_13022009 = "車の運転はもうこりごりだよ…",
  str_homestory_chat_13022010 = "だったらなおさら、もう一回だ！\nクルマ嫌いを吹っ飛ばしてやらねぇと！",
  str_homestory_chat_13023001 = "ヒマそうだね…",
  str_homestory_chat_13023002 = "その通りだ！タイクツでタイクツで仕方ねえ！！\nもうずいぶん長いこと、何も略奪してねぇ！",
  str_homestory_chat_13023003 = "ここではやらないでね！？",
  str_homestory_chat_13023004 = "だからこれだけ溜まってんじゃねえか！！",
  str_homestory_chat_13023005 = "金目のモンを持ってんなら、\n俺の前でチラつかせるんじゃねえぞ…",
  str_homestory_chat_13023006 = "ガマンできなくなるかも知れねぇからな。",
  str_homestory_chat_20599999 = "PlayerName、こんにちは～！",
  str_homestory_chat_20501001 = "こんにちは、イブ。",
  str_homestory_chat_20501002 = "今日は何か面白いこと、あった？",
  str_homestory_chat_20501003 = "ううん…そうだなあ。",
  str_homestory_chat_20501004 = "思いついたら、話を聞かせてね！",
  str_homestory_chat_20521001 = "何を探してるの？",
  str_homestory_chat_20521002 = "PlayerName…お兄ちゃん見かけなかった？",
  str_homestory_chat_20521003 = "見かけなかったよ…",
  str_homestory_chat_20521004 = "どこ行っちゃったんだろう…",
  str_homestory_chat_20521005 = "もし見かけたら、絶対教えてね！",
  str_homestory_chat_20521006 = "分かったよ！",
  str_homestory_chat_20521007 = "あそこにいるよ",
  str_homestory_chat_20521008 = "あ、ありがとう、PlayerName！",
  str_homestory_chat_20521009 = "近くにいたんだ、安心したよ。",
  str_homestory_chat_20522001 = "居心地はどう？",
  str_homestory_chat_20522002 = "ずっとここにいたら、\nそのうち砂漠が恋しくなるんだろうなって思ってたけど…",
  str_homestory_chat_20522003 = "私、思ったよりここが気に入ってるみたい！",
  str_homestory_chat_20522004 = "それは良かった！",
  str_homestory_chat_20522005 = "たぶん…皆も一緒にいるからかな…",
  str_homestory_chat_20522006 = "それに、PlayerNameも一緒にいてくれるし。",
  str_homestory_chat_20522007 = "私、とっても満足だよ。",
  str_homestory_chat_20523001 = "何か考え事？",
  str_homestory_chat_20523002 = "新しい服が欲しいなって…",
  str_homestory_chat_20523003 = "PlayerName、どんな感じの服がいいと思う？",
  str_homestory_chat_20523004 = "ゴージャスな服とか？",
  str_homestory_chat_20523005 = "ゴージャス…？\nああいうのって重くないのかな？",
  str_homestory_chat_20523006 = "でも、PlayerNameの意見だし、考えてみるね！",
  str_homestory_chat_20523007 = "クールな感じの服は？",
  str_homestory_chat_20523008 = "私にそういうのが似合うと思ってるってこと？",
  str_homestory_chat_20523009 = "だったら、試してみるね！",
  str_homestory_chat_20523010 = "シンプルなのもいいよ",
  str_homestory_chat_20523011 = "シンプルで動きやすい服っていいよね！",
  str_homestory_chat_20523012 = "じゃあ、そういうのを何着か買ってみるね。",
  str_homestory_chat_20524001 = "何か聞きたいことがあるの？",
  str_homestory_chat_20524002 = "PlayerName、次のピクニックはいつ？",
  str_homestory_chat_20524003 = "近いうちに行こう！",
  str_homestory_chat_20524004 = "本当に！？",
  str_homestory_chat_20524005 = "今から楽しみにしておくね！",
  str_homestory_chat_20524006 = "日にちが決まったら、絶対に教えてね！",
  str_homestory_chat_20524007 = "何とも言えないなあ…",
  str_homestory_chat_20524008 = "最近、本当に忙しくて…",
  str_homestory_chat_20524009 = "そうなんだ…でも、私もPlayerNameのお手伝い、するよ。",
  str_homestory_chat_20524010 = "遠慮しないでね！",
  str_homestory_chat_20499999 = "PlayerName？",
  str_homestory_chat_20401001 = "そうだよ",
  str_homestory_chat_20401002 = "声で分かったわ。",
  str_homestory_chat_20401003 = "声だけで、人違いはしないの？",
  str_homestory_chat_20401004 = "一人一人声は違うものよ。\nよく聞いていれば、分かるわ。",
  str_homestory_chat_20421001 = "どうして天気がくもりだってわかるの？",
  str_homestory_chat_20421002 = "感覚よ――肌に射す日の光とか、\n髪の湿り具合とかで分かるの…",
  str_homestory_chat_20421003 = "でも…ここはいつも変わらず暖かいから…",
  str_homestory_chat_20421004 = "たまに、晴れかくもりか分かりづらい時があるわ。",
  str_homestory_chat_20421005 = "そういう時はどうするの？",
  str_homestory_chat_20421006 = "誰かに聞くのが、一番早いわね。",
  str_homestory_chat_20422001 = "君って、花の品種とかは区別できるの？",
  str_homestory_chat_20422002 = "香りか何かで分かるのかな…？",
  str_homestory_chat_20422003 = "もちろん、わかるわ。",
  str_homestory_chat_20422004 = "香り以外にも、手で触って――\n頭の中に花の形を思い描くの。",
  str_homestory_chat_20422005 = "それで品種が分かるわ。",
  str_homestory_chat_20422006 = "知りたければ、教えてあげる。",
  str_homestory_chat_20423001 = "何を探してるの？",
  str_homestory_chat_20423002 = "イブはどこ？",
  str_homestory_chat_20423003 = "ここにはいないよ…",
  str_homestory_chat_20423004 = "…もうずいぶん、イブの声を聞いてない気がするわ。",
  str_homestory_chat_20423005 = "ヨアケバナの世話、\nちゃんとしてるかしら…",
  str_homestory_chat_20423006 = "あそこにいるよ",
  str_homestory_chat_20423007 = "連れて行ってあげようか？",
  str_homestory_chat_20423008 = "大丈夫よ、声が聞こえたわ。",
  str_homestory_chat_20423009 = "ありがとう、PlayerName。",
  str_homestory_chat_17199999 = "よう、元気か、小僧。",
  str_homestory_chat_17101001 = "こんにちは、タキ",
  str_homestory_chat_17101002 = "依頼か？",
  str_homestory_chat_17101003 = "そうじゃないよ…",
  str_homestory_chat_17101004 = "そりゃ残念だな。\n依頼だったら割引してやろうと思ってたのによ。",
  str_homestory_chat_17121001 = "どうかした？",
  str_homestory_chat_17121002 = "お前、情報通だろ。教えてくれよ――",
  str_homestory_chat_17121003 = "最近、何か珍しい石ころを見なかったか？",
  str_homestory_chat_17121004 = "情報通？",
  str_homestory_chat_17121005 = "お前、友だちが信じられねえほどいるだろ。",
  str_homestory_chat_17121006 = "友だちが大勢いるんだ、情報だって色々入るだろ？",
  str_homestory_chat_17121007 = "そうとは限らないよ…",
  str_homestory_chat_17121008 = "珍しい石？",
  str_homestory_chat_17121009 = "宝石のことだよ。",
  str_homestory_chat_17121010 = "ううん…何か思い当たったら、教えるよ。",
  str_homestory_chat_17122001 = "僕に用？",
  str_homestory_chat_17122002 = "俺と一杯やらねえか？",
  str_homestory_chat_17122003 = "いいね！",
  str_homestory_chat_17122004 = "ノリがいいな？まあいい、行くぞ！",
  str_homestory_chat_17122005 = "ちょっと待って！今から？",
  str_homestory_chat_17122006 = "今はダメだよ。また今度、時間をとろう…",
  str_homestory_chat_17122007 = "いや、遠慮しとくよ…",
  str_homestory_chat_17122008 = "酒くらいなんてこたぁ…ああ、そうか。ソフトドリンクでいいぜ。",
  str_homestory_chat_17122009 = "それともなにか、他に用事でもあんのか？",
  str_homestory_chat_17122010 = "そんなに忙しいなら、それこそ俺に依頼しろよ――",
  str_homestory_chat_17122011 = "俺が片付けてやるからよ。",
  str_homestory_chat_17123001 = "君が見かけたって言うのは…",
  str_homestory_chat_17123002 = "そうさ、誰かが川で泳いでたな。",
  str_homestory_chat_17123003 = "まったく…「楽しみ方」ってモノを分かってねぇ\nヤツらばっかりだな。",
  str_homestory_chat_17123004 = "どういう意味？",
  str_homestory_chat_17123005 = "分かんねえのか？どうやら、お前も知らねぇらしいな。",
  str_homestory_chat_17123006 = "まあ、いい。今度温泉に連れてってやる――",
  str_homestory_chat_17123007 = "ゆっくり「楽しみ方」ってのを教えてやるよ。",
  str_homestory_chat_21199999 = "こんにちは、PlayerName。",
  str_homestory_chat_21101001 = "こんにちは、ベリエ。",
  str_homestory_chat_21101002 = "最近、あなたに会わないわね…",
  str_homestory_chat_21101003 = "僕の方は君をよく見かけてるよ？",
  str_homestory_chat_21101004 = "そう？たぶん、私がぼうっとしてるのね…",
  str_homestory_chat_21121001 = "その晶石…",
  str_homestory_chat_21121002 = "晶石は…重いの。",
  str_homestory_chat_21121003 = "何年経っても、慣れないわ…",
  str_homestory_chat_21121004 = "歩くだけでも疲れるでしょ？",
  str_homestory_chat_21121005 = "足にいくつかサンドバッグをくくりつけてみれば、\n感覚が分かるんじゃないかしら…",
  str_homestory_chat_21121006 = "何とか、この結晶から解放される方法を見つけないと…",
  str_homestory_chat_21122001 = "おしゃべりしない？",
  str_homestory_chat_21122002 = "他の人と楽しそうにしゃべっているのを、\nよく見かけるけど…",
  str_homestory_chat_21122003 = "そんなに、面白いもの？",
  str_homestory_chat_21122004 = "他人を知ることができるんだ",
  str_homestory_chat_21122005 = "だんだん皆のことを知っていく感覚は、\nいいものだよ。",
  str_homestory_chat_21122006 = "…そう？だったら、私とももっとおしゃべりしましょう…",
  str_homestory_chat_21122007 = "他人と話すのは楽しいよ",
  str_homestory_chat_21122008 = "喜びを分かち合えば、喜びは2人分になる。\n悩みを分かち合えば、悩みは半分になるんだ。",
  str_homestory_chat_21122009 = "…でも、人と話すのってわずらわしいわ…",
  str_homestory_chat_21122010 = "どうせ理解してもらえないし…",
  str_homestory_chat_21122011 = "でも、あなたなら…出来るかも…？",
  str_homestory_chat_21123001 = "ここにずいぶん慣れたみたいだね。",
  str_homestory_chat_21123002 = "そうね。ここは私でも気持ちよく住める、\n数少ない場所だわ…",
  str_homestory_chat_21123003 = "昔の辛いことを、かりそめでも…\n忘れられる気がする。",
  str_homestory_chat_21123004 = "それはよかった！",
  str_homestory_chat_21123005 = "PlayerName、ここに誘ってくれてありがとう。",
  str_homestory_chat_21123006 = "何か助けが必要なことがあれば、全力で手助けするわ。",
  str_homestory_chat_21299999 = "なんで最近、よくアンタに会うの？",
  str_homestory_chat_21221001 = "え？どうかした？",
  str_homestory_chat_21221002 = "アンタに文句があるワケじゃないんだけど、\nいっつも同じヤツに会うってさ…",
  str_homestory_chat_21221003 = "ちょっとタイクツっしょ？",
  str_homestory_chat_21222001 = "何してるの？",
  str_homestory_chat_21222002 = "別に。PlayerName、\nアンタは普段、楽しいコトって言ったら何するの？",
  str_homestory_chat_21222003 = "楽しいこと？",
  str_homestory_chat_21222004 = "目新しくって、刺激になることってイミ！",
  str_homestory_chat_21222005 = "そうだなあ…ゲームかな？",
  str_homestory_chat_21222006 = "んー…レースゲームとかなら、まあまあかな…\nボードゲームとかはダルそう。",
  str_homestory_chat_21222007 = "魚釣りかな？",
  str_homestory_chat_21222008 = "魚釣りって楽しみになんの？\n釣るなら暗鬼ぐらいやんないと…",
  str_homestory_chat_21222009 = "ジョギングかな？",
  str_homestory_chat_21222010 = "後ろから暗鬼に追われてる、みたいな？",
  str_homestory_chat_21222011 = "…",
  str_homestory_chat_21222012 = "ところで、そんなこと聞いてどうするの？",
  str_homestory_chat_21222013 = "いいアイデアが見つかんないから、\nアンタの意見でも参考にしようかなってハナシ。",
  str_homestory_chat_21223001 = "何してると思う？",
  str_homestory_chat_21223002 = "アンタ、なんで今日もまた、その服なの？",
  str_homestory_chat_21223003 = "似合ってないかな？",
  str_homestory_chat_21223004 = "まぁ、今日は水やりとか掃き掃除とか、\nレンガ運びとかやってるみたいだから、それでいいんじゃん？",
  str_homestory_chat_21223005 = "似合ってると思うよ。",
  str_homestory_chat_21223006 = "よくないかな？",
  str_homestory_chat_21223007 = "フツーっしょ？\n汚い見た目ってワケじゃないし。",
  str_homestory_chat_21223008 = "だったら、どうして「また」って言ったの？",
