  str_homestory_chat_22021006 = "ポンペイと一緒に散歩なんて、カッコいいなぁ！",
  str_homestory_chat_22021007 = "そうしたいところだけど…",
  str_homestory_chat_22021008 = "最近忙しくて。",
  str_homestory_chat_22021009 = "ご心配は無用です。今後いつでも、歓迎いたしますよ。",
  str_homestory_chat_22022001 = "近いうちにパーティをやるんだけど…",
  str_homestory_chat_22022002 = "参加してくれる？",
  str_homestory_chat_22022003 = "ご招待、感謝いたします。\nですが、大勢の人は苦手ですので…",
  str_homestory_chat_22022004 = "そっか…",
  str_homestory_chat_22022005 = "ですが、近くの高い場所から――",
  str_homestory_chat_22022006 = "パーティの様子を拝見していましょう。\nそれも参加と言えますね。",
  str_homestory_chat_22022007 = "えっ？",
  str_homestory_chat_22023001 = "僕に何か用？",
  str_homestory_chat_22023002 = "本を数冊、探して頂きたいのです。\nお願いできますか？",
  str_homestory_chat_22023003 = "いいよ。",
  str_homestory_chat_22023004 = "だけど、何日か前にも山ほど買ってなかった…？",
  str_homestory_chat_22023005 = "もう読み終わっちゃったの？",
  str_homestory_chat_22023006 = "ええ。時として、速く読みすぎるというのも困りものですね。",
  str_homestory_chat_22399999 = "こんにちは！",
  str_homestory_chat_22301001 = "こんにちは！カーティ！",
  str_homestory_chat_22301002 = "今日もちゃーんと、ここの治安を守ったよ！",
  str_homestory_chat_22301003 = "お、お疲れ様。",
  str_homestory_chat_22301004 = "みんなのための安全な環境が作れるなら、\nどんなことだって辛くないわ！",
  str_homestory_chat_22321001 = "え？もう行っちゃうの？",
  str_homestory_chat_22321002 = "うん、今日まだ自分の部屋を掃除してなかったの、\n思い出したから…",
  str_homestory_chat_22321003 = "まだ二言しか話してないよ。",
  str_homestory_chat_22321004 = "おしゃべりしてたいところだけど…",
  str_homestory_chat_22321005 = "部屋の掃除が終わってないと思うと、\nどうしても気になっちゃうの…",
  str_homestory_chat_22321006 = "あああ！もうガマンできない！！\n今すぐ戻らなきゃ、ごめんね！",
  str_homestory_chat_22322001 = "今日はきげんが良さそうだね",
  str_homestory_chat_22322002 = "そうよ！新しい制服が届いたの！",
  str_homestory_chat_22322003 = "新しい服が気に入った？",
  str_homestory_chat_22322004 = "新しければいいってワケじゃないわ…",
  str_homestory_chat_22322005 = "今度の新しい制服、まだのり付けもしてないから、\n触るととにかく柔らかいの。",
  str_homestory_chat_22322006 = "こんな柔らかい服を着られるって思ったら、\n思わず笑顔になっちゃうわ…",
  str_homestory_chat_22322007 = "…ちょっと、笑わないでよ！",
  str_homestory_chat_22323001 = "もしかして、泣いてた？",
  str_homestory_chat_22323002 = "何かあったの？",
  str_homestory_chat_22323003 = "な、なんでもない…",
  str_homestory_chat_22323004 = "話してくれていいんだよ",
  str_homestory_chat_22323005 = "べ、別に、悲しくて、な、泣いてるわけじゃ、ないの…",
  str_homestory_chat_22323006 = "私の仕事って、色んな事件に出くわすから…ビックリして…",
  str_homestory_chat_22323007 = "そうだったんだ。",
  str_homestory_chat_22323008 = "次に何かあったら、僕も手助けするよ。",
  str_homestory_chat_22323009 = "本当に大丈夫？",
  str_homestory_chat_22323010 = "だ、大丈夫よ…早く、自分のやる事に戻って。",
  str_homestory_chat_22323011 = "じゃあ…僕は行くよ？何かあったら、声をかけてね。",
  str_homestory_chat_11599999 = "よう、PlayerName。いい天気だなあ。",
  str_homestory_chat_11501001 = "こんにちは。",
  str_homestory_chat_11501002 = "絵でも買わねえか？",
  str_homestory_chat_11501003 = "天気がいいのと絵を買うのと、どんな関係があるの？",
  str_homestory_chat_11501004 = "PlayerName自身が関係あるって感じるなら、\nそれでいいんだよ。",
  str_homestory_chat_11501005 = "…にしても、あんたのしゃべり方、\nますますあいつに似て来たな…",
  str_homestory_chat_11521001 = "何か考え事？",
  str_homestory_chat_11521002 = "オレたちはいつになったら、\n飛空艇を買えるんだろうな…",
  str_homestory_chat_11521003 = "ギンの計算だと、\nあと大体1万枚は絵を売らなきゃいけねえんだ。",
