  str_homestory_chat_11521005 = "いい案だな。",
  str_homestory_chat_11521006 = "高利貸しには気を付けてね。\n怖いって聞くし…",
  str_homestory_chat_11521007 = "自分たちで造ればいい",
  str_homestory_chat_11521008 = "それもそうだな。",
  str_homestory_chat_11521009 = "で、あんた、造れんのか？",
  str_homestory_chat_11521010 = "ぼ、僕は、R・Wの「天才発明家」たちじゃないから…",
  str_homestory_chat_11522001 = "今日は少し暑いね。",
