  str_homestory_chat_11522003 = "…おかしいな…",
  str_homestory_chat_11522004 = "僕たちの感じ方、違ってるんだね。",
  str_homestory_chat_11522005 = "まあ、見た目からしてそもそも違うもんね…",
  str_homestory_chat_11522006 = "そうだな。じゃあオレは、\n帰ってコートを着るとするか！",
  str_homestory_chat_11523001 = "サロンを開くって聞いたよ？",
  str_homestory_chat_11523002 = "普通のパーティじゃなかったか？",
  str_homestory_chat_11523003 = "誰かが間違えて伝えたのかな…",
  str_homestory_chat_11523004 = "ギンだな。",
  str_homestory_chat_11523005 = "今すぐギンに聞いてくる。",
  str_homestory_chat_11523006 = "じゃあ…普通のパーティなんだね。",
  str_homestory_chat_23199999 = "何とも偶然ですね、PlayerName様。",
  str_homestory_chat_23101001 = "こんにちは、ノーヴィオ。",
  str_homestory_chat_23101002 = "あなたもここでお散歩ですか？",
  str_homestory_chat_23101003 = "そうだよ。",
