  str_homestory_chat_23122004 = "ウサギたちにまた新たな家族が増えたのです。",
  str_homestory_chat_23122005 = "今まででしたら3食分はあったニンジンを、\n2食で食べきってしまうので…",
  str_homestory_chat_23122006 = "ほとほと困っております…",
  str_homestory_chat_23122007 = "そうなんだ…僕が聞いておいてあげるよ。",
  str_homestory_chat_23123001 = "ベツレヘムさんを探してるの？",
  str_homestory_chat_23123002 = "そうです。どこにいらっしゃるか、ご存じですか？",
  str_homestory_chat_23123003 = "知ってるよ",
  str_homestory_chat_23123004 = "あそこだよ。",
  str_homestory_chat_23123005 = "助かりました。宝石のブローチを作ったのですが…",
  str_homestory_chat_23123006 = "女王陛下のお付けになった姿が実に楽しみです。",
  str_homestory_chat_23123007 = "知らないよ…",
  str_homestory_chat_23123008 = "宝石のブローチを作ったので、\n女王陛下に差し上げたいと思っていたのですが…",
  str_homestory_chat_23123009 = "そうとなれば、どなたに贈れば…",
  str_homestory_chat_23123010 = "…いえ、やはりしまっておきましょう。",
  str_homestory_chat_23124001 = "何か聞いてるの？",
  str_homestory_chat_23124002 = "ええ、自然の声を聞いておりました。\n時折、音楽よりも耳に心地よいと感じることがございます。",
  str_homestory_chat_23124003 = "それはそうと、音楽はお好きですか？",
  str_homestory_chat_23124004 = "好きだよ",
  str_homestory_chat_23124005 = "そんなに好きじゃないかな",
