  str_homestory_chat_23124007 = "もしかして、興味があるの？",
  str_homestory_chat_23124008 = "いえ、少々尋ねてみただけですよ。",
  str_homestory_chat_23125001 = "お散歩中？",
  str_homestory_chat_23125002 = "はい。最近、少し悩みがありまして…\nこの胸のわだかまりを和らげたいと、気分転換に出てきた次第です。",
  str_homestory_chat_23125003 = "こういう時、あなたならどうされますか？",
