  str_homestory_chat_23125007 = "特に影ノ街で連載中の三流義賊の小説とか、\n頭を使わない本を読んだりするかな…",
  str_homestory_chat_23125008 = "そうですか…気持ちをすっきりさせるために、\n色々努力をなさっているのですね。",
