  str_homestory_chat_23999999 = "…",
  str_homestory_chat_23901001 = "こんにちは、エリカ。",
  str_homestory_chat_23901002 = "…あ…あんた、あたしにあいさつしてるの？",
  str_homestory_chat_23901003 = "次は別の時間にしてね。\n今、居眠りしてるとこだから…",
