  str_homestory_chat_24022004 = "今になって、少し気分が悪くなってきたわ。",
  str_homestory_chat_24022005 = "辛いのは苦手？",
  str_homestory_chat_24022006 = "苦手ではないわ…ただ、好きじゃないだけ。とても。",
  str_homestory_chat_24022007 = "なんだか、身体に良くないものを食べた気がするから…",
  str_homestory_chat_24023001 = "僕に用？",
  str_homestory_chat_24023002 = "歩く時は気を付けてね。",
  str_homestory_chat_24023003 = "どうしたの？",
  str_homestory_chat_24023004 = "アルバが草むらに入っていっちゃったの。もし踏んだら…",
  str_homestory_chat_24023005 = "え、そんな…",
  str_homestory_chat_24023006 = "怖がることはないわ。すぐに見つけて連れ戻すから。",
  str_homestory_chat_24023007 = "十分気を付けるよ",
  str_homestory_chat_24023008 = "ヘビ、怖くないの？",
  str_homestory_chat_24199999 = "やっほ～、PlayerName。",
  str_homestory_chat_24101001 = "こんにちは、ルビー。",
  str_homestory_chat_24101002 = "私と一緒に探検しない？",
  str_homestory_chat_24101003 = "今から？",
  str_homestory_chat_24101004 = "そんなはずないでしょ？",
  str_homestory_chat_24101005 = "一人前の探検家は、出発前に十分な準備をしておくものだよ！",
  str_homestory_chat_24121001 = "そのハムスターたちって…",
  str_homestory_chat_24121002 = "ポンタとロンタ？\nまたいい物見つけたよ！",
  str_homestory_chat_24121003 = "見つけた物に持ち主はいないの？",
  str_homestory_chat_24121004 = "う、確かに…",
  str_homestory_chat_24121005 = "じゃあ、落とし物の張り紙を貼っとこ！",
