  str_homestory_chat_24122001 = "どうしたの？",
  str_homestory_chat_24122002 = "「イテ！」って声、聞こえなかった？",
  str_homestory_chat_24122003 = "聞こえた気がする…",
  str_homestory_chat_24122004 = "わあ、やっちゃった…たぶん人に当たったんだ！",
  str_homestory_chat_24122005 = "聞こえなかった",
  str_homestory_chat_24122006 = "ふぅ――なら、良かった…",
  str_homestory_chat_24122007 = "何をしたの？",
  str_homestory_chat_24122008 = "バットで缶を吹っ飛ばしただけだよ…",
  str_homestory_chat_24123001 = "何してるの？",
  str_homestory_chat_24123002 = "新しい探検ルートが完成したの！",
  str_homestory_chat_24123003 = "見てみたい？",
  str_homestory_chat_24123004 = "見てみたい！",
  str_homestory_chat_24123005 = "いいよ、じゃあ見に行こう…",
  str_homestory_chat_24123006 = "…",
  str_homestory_chat_24123007 = "どうして見つからないんだろう…\nまさか、ポンタとロンタが持って行っちゃった？",
