  str_homestory_chat_24222005 = "あ、見えた！ありがとう、PlayerName！",
  str_homestory_chat_24222006 = "ルビー姉のとこに行くから、話はまた今度ね！",
  str_homestory_chat_24222007 = "僕も最近見かけてない",
  str_homestory_chat_24222008 = "そんな、どうして…",
  str_homestory_chat_24222009 = "でも、ポンタとロンタに発信器を付けておいたから――",
