  str_homestory_chat_24223001 = "何の音？",
  str_homestory_chat_24223002 = "うう、お腹が鳴ってる…",
  str_homestory_chat_24223003 = "ちょっと、あんた、いつからいたの！？",
  str_homestory_chat_24223004 = "お腹空いてるの？",
  str_homestory_chat_24223005 = "少しね…",
  str_homestory_chat_24223006 = "…バーベキューでもやりたいわ……",
