  str_homestory_chat_24224004 = "よかった！",
  str_homestory_chat_24224005 = "そう言えば、ここの食事は悪くないわね！",
  str_homestory_chat_24224006 = "朝ご飯を食べ終わったら、\n昼ご飯が楽しみになるわ。",
  str_homestory_chat_24224007 = "まだ大分あるよ",
  str_homestory_chat_24224008 = "どうして、そんな…",
