  str_homestory_chat_24301002 = "本日はお祓いの必要はございますか？",
  str_homestory_chat_24301003 = "ひ、必要ないよ…",
  str_homestory_chat_24321001 = "ここの感想は？",
  str_homestory_chat_24321002 = "この地は異常なまでに清らかです。",
