  str_homestory_chat_24321007 = "分かりました。\nではわたくし、リンネとしてここに留まるといたしましょう。",
  str_homestory_chat_24322001 = "僕に何か用？",
  str_homestory_chat_24322002 = "ナビゲーター様、「お清めの日」を設けてはいかがですか。",
  str_homestory_chat_24322003 = "いいね！",
  str_homestory_chat_24322004 = "あら、そのように快諾いただけるとは…",
  str_homestory_chat_24322005 = "説得の言葉も考えていたのですが、\nお話しする機会がなくなってしまいましたね。",
  str_homestory_chat_24322006 = "えっ、どうして？",
  str_homestory_chat_24322007 = "定期的にけがれを祓い、人々の不幸を追い払うのです。\nそうすれば、健康と良好な精神を保つことができます――",
  str_homestory_chat_24322008 = "このような理由では、いかがでしょう？",
  str_homestory_chat_24323001 = "何か変わったことはあった？",
  str_homestory_chat_24323002 = "ナビゲーター様、よい修行場所を見つけました。",
  str_homestory_chat_24323003 = "どこ？",
  str_homestory_chat_24323004 = "具体的な場所はうまく説明できませんが、\nお教えして差し上げましょう――",
  str_homestory_chat_24323005 = "河から遠くなく…",
  str_homestory_chat_24323006 = "その場所を見つけるには、\nよく耳を澄ませる必要がございます。",
  str_homestory_chat_24323007 = "そして夕暮れ時には決まって時間通り、\n美しい音楽が流れてくるのです…",
  str_homestory_chat_24323008 = "音楽好きの誰かの秘密基地を発見したみたいだね。",
  str_homestory_chat_24499999 = "あ…",
  str_homestory_chat_24401001 = "こんにちは、カヤノ。",
  str_homestory_chat_24401002 = "わ、私にあいさつしたんですか？\nあ、ありがとうございます…",
  str_homestory_chat_24401003 = "元気そうだね。",
  str_homestory_chat_24401004 = "そ、それは…今日は「もののけ」が静かなので…",
  str_homestory_chat_24421001 = "あんまり見かけないね…",
  str_homestory_chat_24421002 = "君がここに来てからも…",
  str_homestory_chat_24421003 = "そ、そうですか…\nたぶん、私がいつも、つい隠れてしまうからだと思います…",
  str_homestory_chat_24421004 = "どうして？",
  str_homestory_chat_24421005 = "ここには、光霊がたくさんいらっしゃるので…",
