  str_homestory_chat_24422004 = "うう…な、何も言ってませんよ、\n今のは、わ、私が言ったんじゃありません…",
  str_homestory_chat_24422005 = "緊張しないで",
  str_homestory_chat_24422006 = "君に来てもらえて、僕は嬉しいんだ。",
