  str_homestory_chat_24423001 = "背が高いね",
  str_homestory_chat_24423002 = "ええ…でも…いえ、何でもありません。",
  str_homestory_chat_24423003 = "身長でお悩みですか？",
  str_homestory_chat_24423004 = "少しね…",
