  str_homestory_chat_24522001 = "何を見てるの？",
  str_homestory_chat_24522002 = "朝、ここで目覚めるたびに、\n一瞬ぼんやりとしてしまう…",
  str_homestory_chat_24522003 = "幼い頃に戻った気分になる。",
  str_homestory_chat_24522004 = "ここは君の故郷に似てるの？",
  str_homestory_chat_24522005 = "いや…むしろ、かなり異なる。",
  str_homestory_chat_24522006 = "しかし、そういう感覚が生じるのは、大方ここでは、\nしばらく味わっていなかった安寧を、拙者も感じられているからだろう。",
