  str_homestory_chat_26323002 = "数日前、完璧と言える作品に出会ったのです！",
  str_homestory_chat_26323003 = "まるで動いているかのような、美しい線！\n大胆ながら、調和のとれた色使い！",
  str_homestory_chat_26323004 = "あの作品は――まるで宇宙の神秘を包み込んでいるかのようでした！",
  str_homestory_chat_26323005 = "私はその作品のために、全財産はたいて、生活費も捧げました！",
  str_homestory_chat_26323006 = "それって…",
  str_homestory_chat_26323007 = "そういうわけでダンナ、ふところが寂しいもので…\nダンナの家に食事を頂きにいってもいいですか？",
  str_homestory_chat_24899999 = "あら、空の末裔クン？",
  str_homestory_chat_24801001 = "こんにちは、アズール。",
  str_homestory_chat_24801002 = "お姉さんと遊びたいの？",
  str_homestory_chat_24801003 = "た、ただのあいさつだよ…",
  str_homestory_chat_24801004 = "ただのあいさつ？\n本当に？他のことはしないのかしら？",
  str_homestory_chat_24821001 = "何する予定？",
  str_homestory_chat_24821002 = "洗車よ。一緒に来る？",
  str_homestory_chat_24821003 = "どこへ？",
  str_homestory_chat_24821004 = "洗車場なんてないはずだけど…",
  str_homestory_chat_24821005 = "洗車っていうのはね、\nきれいな水さえあれば、できるのよ。",
  str_homestory_chat_24821006 = "どこに洗車しに行くか、当ててみて？",
  str_homestory_chat_24821007 = "どうやって洗うの？",
  str_homestory_chat_24821008 = "ウフフ…おかしな質問するわね？",
  str_homestory_chat_24821009 = "もちろん、水で洗うに決まってるじゃない。",
  str_homestory_chat_24821010 = "ぼうっとしないで。\nお姉さんがどうやって「クルマを洗う」か、教えてあげましょうか？",
  str_homestory_chat_24822001 = "何か聞きたいことでもあるの？",
  str_homestory_chat_24822002 = "ここに射撃場はあるかしら？",
  str_homestory_chat_24822003 = "ないよ…",
  str_homestory_chat_24822004 = "あら、それはタイクツね…",
  str_homestory_chat_24822005 = "だったら、植木鉢でも狙うしかないわね。",
  str_homestory_chat_24822006 = "むやみに物を壊さないで…",
  str_homestory_chat_24822007 = "あたしは「狙う」と言ったの。\n「撃つ」とは言ってないわよ。",
  str_homestory_chat_24822008 = "あるよ",
  str_homestory_chat_24822009 = "あたしにウソをついたら、\n高い代償を払うことになるわよ。",
  str_homestory_chat_24822010 = "もし、射撃場が見つからなかったら…\nどんなオシオキをされると思う？",
  str_homestory_chat_24823001 = "誰かを探してるの？",
  str_homestory_chat_24823002 = "影ノ街のあいつら…一体どこに隠れたのかしら？",
  str_homestory_chat_24823003 = "僕も見てない…",
  str_homestory_chat_24823004 = "そういえば…ボーヤは付き合いがいい方かしら？",
  str_homestory_chat_24823005 = "見つからなかったら、\nあなたと何か飲みにいくのも悪くないわね。",
  str_homestory_chat_24823006 = "あっちにいるみたいだよ",
  str_homestory_chat_24823007 = "…まぁ…あたしの飲み友達にする資格はまだないわね。",
  str_homestory_chat_24823008 = "さて、誰に声をかけようかしら…",
  str_homestory_chat_24824001 = "住み心地はどう？",
  str_homestory_chat_24824002 = "少しタイクツね…",
  str_homestory_chat_24824003 = "唯一の楽しみは、\n可愛い男の子を鑑賞できるってことくらいかしら？",
  str_homestory_chat_24824004 = "PlayerName、ここで一番かわいいのは、誰だと思う？",
  str_homestory_chat_24824005 = "比べられない…",
  str_homestory_chat_24824006 = "僕からすれば、皆かわいい！",
  str_homestory_chat_24824007 = "あたしも、「可愛い」に入るのかしら？",
  str_homestory_chat_24824008 = "そ…それは…",
  str_homestory_chat_24824009 = "僕",
  str_homestory_chat_24824010 = "…自分で自分が可愛いっていうコが本当にいるとはねぇ…",
  str_homestory_chat_24999999 = "なんだって急にオッさんなんかに\nあいさつすンのかねぇ？",
  str_homestory_chat_24901001 = "会ったから",
  str_homestory_chat_24901002 = "ついでにあいさつしようと思って…",
  str_homestory_chat_24901003 = "お前、正直すぎやしねえか。",
  str_homestory_chat_24901004 = "それともなにか、\nオッさんにはお世辞のひとつも言いたくねえってか？",
  str_homestory_chat_24921001 = "ぬいぐるみが好きなの？",
  str_homestory_chat_24921002 = "そうさ！若いの、お前はどうだ？",
  str_homestory_chat_24921003 = "好きだよ！",
  str_homestory_chat_24921004 = "この間のラリーで賞品のぬいぐるみがいくつか余ったんだ。\n引き取ってくんねえか？",
  str_homestory_chat_24921005 = "いいよ！",
  str_homestory_chat_24921006 = "よし、じゃあ後で持ってくるとするか。",
  str_homestory_chat_24921007 = "ぬいぐるみは好きじゃない…",
  str_homestory_chat_24921008 = "そうか…うちの若いモンには、\n結構ウケてンだがな…",
  str_homestory_chat_24921009 = "お前もてっきり好きだと思ってたンだが。",
  str_homestory_chat_24921010 = "そういうことなら、あのウサギたちも部屋に置いとくしかねェな。",
  str_homestory_chat_24922001 = "少しタイクツそうだね。",
  str_homestory_chat_24922002 = "そうなんだ…ここ数日、うちの若いモンが\n揃って山登りに行っちまってな…",
  str_homestory_chat_24922003 = "オッさん独りになっちまったってわけさ。寂しいねェ。",
  str_homestory_chat_24922004 = "どうして行かなかったの？",
  str_homestory_chat_24922005 = "この足を見てみろよ――",
  str_homestory_chat_24922006 = "長く歩いてると、\nガチガチ鳴るンだよ。",
  str_homestory_chat_24922007 = "だから、山登りみてェな運動は、できねえんだ。",
  str_homestory_chat_24923001 = "ここはどう？",
  str_homestory_chat_24923002 = "…いい所だな。",
  str_homestory_chat_24923003 = "あいつがまだ生きてたら、\nきっとここを気に入ってただろう…",
  str_homestory_chat_24923004 = "…おっと、今のは独り言だ。聞いてなかったよな…",
  str_homestory_chat_24923005 = "聞こえたよ…",
  str_homestory_chat_24923006 = "…まあ、いいさ。\n別に誰かの悪口じゃねェしな。",
  str_homestory_chat_24923007 = "今度から俺に近づく時は、先に声掛けろよ！",
  str_homestory_chat_24923008 = "聞こえなかった",
  str_homestory_chat_24923009 = "はあ、お前はウソが下手だねェ…",
  str_homestory_chat_24923010 = "まあ、いい。\n聞こえたってなんてこたぁない。",
  str_homestory_chat_25299999 = "…",
  str_homestory_chat_25201001 = "こんにちは、メイ。",
  str_homestory_chat_25201002 = "あ、あんた、あたしにあいさつしたの？",
  str_homestory_chat_25201003 = "ど…どうしよう、どう返せば…？",
  str_homestory_chat_25201004 = "…わ、わざと答えなかったわけじゃないの…\nあたしのこと、嫌いにならないよね？",
  str_homestory_chat_25201005 = "ただのあいさつだよ。そんなに深刻なことじゃない。",
  str_homestory_chat_25221001 = "何してるの？",
  str_homestory_chat_25221002 = "よしよし、おりこうさんね、ママはここよ…",
  str_homestory_chat_25221003 = "何って、もちろん、ベビーちゃんのお世話。",
  str_homestory_chat_25221004 = "ベビーちゃんの毛、からまりやすいの！\nほんと、イヤになっちゃう…",
  str_homestory_chat_25221005 = "ああ、ダメダメ！ママは辛抱強くなくっちゃ！",
  str_homestory_chat_25221006 = "（ジャマしないほうがいいのかな…）",
  str_homestory_chat_25222001 = "何を考えてるの？",
  str_homestory_chat_25222002 = "お花は好き？",
  str_homestory_chat_25222003 = "好きだよ",
  str_homestory_chat_25222004 = "なら、お花を摘んで、\nあんたの服に縫い付けるのはどう？",
  str_homestory_chat_25222005 = "あたしが…あんたの好きなものを、プレゼントしたら…",
  str_homestory_chat_25222006 = "あたしのこと、もっと好きになってくれる？",
  str_homestory_chat_25222007 = "いいや",
  str_homestory_chat_25222008 = "お花は好きじゃないの？なら…何が好きなの？",
  str_homestory_chat_25222009 = "なんで突然、そんなことを聞くの？",
  str_homestory_chat_25222010 = "あ、あたしはただ…言いたくないなら、いいよ。",
  str_homestory_chat_25223001 = "今、指を噛んでた？",
  str_homestory_chat_25223002 = "うん…",
  str_homestory_chat_25223003 = "噛んじゃダメだよ！",
  str_homestory_chat_25223004 = "不衛生だよ！",
  str_homestory_chat_25223005 = "え…PlayerName、あたしのこと、\nきらいになってないよね？",
  str_homestory_chat_25223006 = "そ、そんなことはないよ…",
  str_homestory_chat_25223007 = "自分では意識してないの？",
  str_homestory_chat_25223008 = "指に歯形がついてないか…見てみる…",
  str_homestory_chat_25099999 = "PlayerName、ようやく任務をレノーアにくれますか？",
  str_homestory_chat_25001001 = "違う、違う",
  str_homestory_chat_25001002 = "ただのあいさつだよ。",
  str_homestory_chat_25001003 = "では…レノーアは、何をすればいいですか？",
  str_homestory_chat_25001004 = "ひとまず、そのままでいて…",
  str_homestory_chat_25021001 = "何の音？",
  str_homestory_chat_25021002 = "お腹がまたレノーアに話しかけています。",
  str_homestory_chat_25021003 = "えっ？",
  str_homestory_chat_25021004 = "聞いてください――「グゥ」という音がします。",
  str_homestory_chat_25021005 = "お腹空いたの？",
  str_homestory_chat_25021006 = "何か食べる？",
  str_homestory_chat_25021007 = "それはPlayerNameの命令ですか？",
  str_homestory_chat_25021008 = "それで君がお腹を空かせずに済むなら…\n「命令」と思ってくれていいよ。",
  str_homestory_chat_25022001 = "何かつぶやいてる？",
  str_homestory_chat_25022002 = "今日、忘れずに…ゼンマイを巻いてください…",
  str_homestory_chat_25022003 = "ゼンマイ？",
  str_homestory_chat_25022004 = "あ…忘れていました。レノーアは、もうゼンマイを巻く必要ありません。",
  str_homestory_chat_25022005 = "光霊になった後も、くせが抜けません…",
  str_homestory_chat_25022006 = "構わないよ。時間はたっぷりあるんだ、ゆっくり慣れればいい。",
  str_homestory_chat_25023001 = "僕を見てるの？",
  str_homestory_chat_25023002 = "PlayerName、他の人が喜ぶのを見ると、自分も嬉しくなりますか？",
  str_homestory_chat_25023003 = "なるよ",
  str_homestory_chat_25023004 = "喜びは伝染していくんだよ！",
  str_homestory_chat_25023005 = "レノーアの予想は当たっていました。",
  str_homestory_chat_25023006 = "皆さんを見ていて、レノーアが感じたのは喜びですね。",
  str_homestory_chat_25023007 = "今日もまた、新しいことを学びました。",
  str_homestory_chat_25023008 = "ならないよ",
  str_homestory_chat_25023009 = "レノーアは、今日皆さんが笑っているのを見て…笑いたくなりました――",
  str_homestory_chat_25023010 = "これはどういう気持ちですか？",
  str_homestory_chat_25024001 = "たくさん歩いたみたいだね？",
  str_homestory_chat_25024002 = "レノーアは今日、たくさん歩きました。",
  str_homestory_chat_25024003 = "今まで、歩いている時、レノーアはただ、歩いているだけでした…",
  str_homestory_chat_25024004 = "今はレノーアも、風や花の香り、靴底の下に転がっている石を感じます…",
  str_homestory_chat_25024005 = "けっこう感受性が豊かなんだね…",
  str_homestory_chat_25024006 = "PlayerNameもレノーアと一緒に歩きましょう。",
  str_homestory_chat_25199999 = "おや？PlayerName…",
  str_homestory_chat_25101001 = "こんにちは、ギルス。",
  str_homestory_chat_25101002 = "きっと僕が新しい童謡を創ったことを知って、\n聞きに来たんだね！",
  str_homestory_chat_25101003 = "聞いていくだろう？",
  str_homestory_chat_25101004 = "そ…それは…",
  str_homestory_chat_25121001 = "何かいい香りがしない？",
  str_homestory_chat_25121002 = "いい香りかい？もちろん、するさ――",
  str_homestory_chat_25121003 = "でも、香りの元は、もう僕が食べてしまったよ。",
  str_homestory_chat_25121004 = "な、何を食べたの？",
  str_homestory_chat_25121005 = "アハハ！君のその表情は…「怖い」のかい？",
  str_homestory_chat_25121006 = "僕が食べたのは、もちろん――",
  str_homestory_chat_25121007 = "お肉だよ！",
  str_homestory_chat_25122001 = "どうしたの？",
  str_homestory_chat_25122002 = "…さっき、また…夢を見たんだ。",
  str_homestory_chat_25122003 = "僕、寝言いってた？",
  str_homestory_chat_25122004 = "聞こえなかった…",
  str_homestory_chat_25122005 = "よかった、聞こえてなくて。\nでなかったら、君まで悪夢を見るところだったよ。",
  str_homestory_chat_25122006 = "聞こえた気がする…",
  str_homestory_chat_25122007 = "はっきりとは聞こえてないだろうね…？",
  str_homestory_chat_25122008 = "もし、聞こえていたら…そんな顔はしないはずだ。",
  str_homestory_chat_25123001 = "何か言ってた？",
  str_homestory_chat_25123002 = "もう長いこと、新しい童謡を創れてないんだ…",
  str_homestory_chat_25123003 = "PlayerName、君はどんな童謡が聞きたい？",
  str_homestory_chat_25123004 = "光霊の話？",
  str_homestory_chat_25123005 = "「愚かで賢い、騒がしくて静かにできない…」",
  str_homestory_chat_25123006 = "「さあナビゲーター、当ててみて。光霊って何？」",
  str_homestory_chat_25123007 = "暗鬼のこと？",
  str_homestory_chat_25123008 = "いいね！",
  str_homestory_chat_25123009 = "PlayerNameが悪夢を見るのがきらいじゃなければね。",
  str_homestory_chat_25123010 = "故郷の話？",
  str_homestory_chat_25123011 = "故郷と言えば…ふわあ～、また眠くなってきた…",
  str_homestory_chat_25123012 = "目覚める頃には、故郷についての童謡が出来てるかもしれないよ。",
  str_homestory_chat_25399999 = "調子はどうだ。",
  str_homestory_chat_25301001 = "は、はい！",
  str_homestory_chat_25301002 = "あっ、思わず起立しちゃった…",
  str_homestory_chat_25321001 = "僕を見て、何してるんですか？",
  str_homestory_chat_25321002 = "腹は減っているか？",
  str_homestory_chat_25321003 = "少し…",
  str_homestory_chat_25321004 = "今日は、大鍋で炊いた飯でもどうだ？",
  str_homestory_chat_25321005 = "全員呼んでくるがいい、\n私が腕をふるってやろう。",
  str_homestory_chat_25321006 = "空いてません",
  str_homestory_chat_25321007 = "それでも構わん。",
  str_homestory_chat_25321008 = "ここにいる全員に、\n大鍋で炊き出しでもしてやろうと思ってな。",
  str_homestory_chat_25321009 = "自分で作るんですか？",
  str_homestory_chat_25321010 = "意外か？",
  str_homestory_chat_25321011 = "私が何をしても、意外だと思うようなことはない。",
  str_homestory_chat_25322001 = "ここの感想はどうですか？",
  str_homestory_chat_25322002 = "静かでゆったりしているな。",
  str_homestory_chat_25322003 = "ここに長く留まりすぎれば、戦争がどんなものかも、\nいずれ思い出せなくなるだろう。",
  str_homestory_chat_25322004 = "それはいいことじゃないんですか？",
  str_homestory_chat_25322005 = "私が良くないことだと言ったか？",
  str_homestory_chat_25322006 = "啓光を…あるいは、大陸全土を――",
  str_homestory_chat_25322007 = "このように変えていくことが、\n私の生涯の夢だ。",
  str_homestory_chat_25323001 = "こんにちは…今日の調子はどうですか？",
  str_homestory_chat_25323002 = "…疲れているようだな。",
  str_homestory_chat_25323003 = "そうですか？",
  str_homestory_chat_25323004 = "昨日の夜、徹夜でゲームしてたからかな…",
  str_homestory_chat_25323005 = "ジョギングを２周ほどして風に当たるがいい。\nそうすれば気分も良くなる。",
  str_homestory_chat_25323006 = "あなたが言うと何だか不思議ですね。",
  str_homestory_chat_25323007 = "私がいつも「気合を入れろ」と言うからか？",
  str_homestory_chat_25323008 = "たぶん、そうだと思います…",
  str_homestory_chat_25323009 = "ここでは、お前が主で、私が客だ。",
  str_homestory_chat_25323010 = "そうした礼節は、私もわきまえている。",
  str_homestory_chat_25324001 = "僕に用ですか？",
  str_homestory_chat_25324002 = "バイスと話した。\n最近はまじめに訓練に取り組んでいるそうだな。",
  str_homestory_chat_25324003 = "え…聞いたんですか？",
  str_homestory_chat_25324004 = "お前のすることに干渉するつもりはない――",
  str_homestory_chat_25324005 = "ただ、頼りになる仲間がいることは\n素晴らしいと心から思っただけだ。",
  str_homestory_chat_25324006 = "訓練で何か困ったことがあれば、\n私を訪ねるがいい。",
  str_homestory_chat_25324007 = "いつでも助けになってやる。",
  str_homestory_chat_25499999 = "あっ、PlayerName。今日は天気がいいわね。",
  str_homestory_chat_25401001 = "やあ、バイス。",
  str_homestory_chat_25401002 = "今日の君の格好…",
  str_homestory_chat_25401003 = "たまには服を換えてみようと思って。どう？",
  str_homestory_chat_25401004 = "うん、似合ってるよ！",
  str_homestory_chat_25421001 = "今日はどんな感じだった？",
  str_homestory_chat_25421002 = "ちょうど射撃の練習をしてきたところよ。",
  str_homestory_chat_25421003 = "ボウガンの方？",
  str_homestory_chat_25421004 = "そうよ、高速で射撃する方法を思いついたの。",
  str_homestory_chat_25421005 = "ポイントは、どうしたら素早く矢をかけられるか…",
  str_homestory_chat_25421006 = "きっと何か、啓光の技術を使うんだね。",
  str_homestory_chat_25421007 = "それぐらいは予想が付くみたいね。",
  str_homestory_chat_25421008 = "でも、欠点も多いの。\nちょっと矢をつがえると、弦がすぐに切れてしまって…",
  str_homestory_chat_25421009 = "改良が必要みたい。",
  str_homestory_chat_25422001 = "最近、何か新しい計画はあるの？",
  str_homestory_chat_25422002 = "ええ、射撃場をきれいにしたいと思ってるの。",
  str_homestory_chat_25422003 = "射撃場…そんな所あったっけ？",
  str_homestory_chat_25422004 = "え？あの辺りの並んだ木…",
  str_homestory_chat_25422005 = "私はずっと的だと思ってたけど…",
  str_homestory_chat_25422006 = "それは…まあ、いいや。\nあの木は皮が厚いから。",
  str_homestory_chat_25422007 = "でも、的にするなら石の方がいいんじゃない？",
  str_homestory_chat_25422008 = "石の的は…ちょっと低すぎるわね。",
  str_homestory_chat_25422009 = "それに矢じりがダメになっちゃうわ。",
  str_homestory_chat_25422010 = "ううん…やっぱり専用の射撃場が必要そうだなぁ。",
