  str_homestory_chat_26503012 = "睡眠環境に関わる数値を測ってたんだよ。\n昼寝するなら、天気の良い日がいいでしょ？",
  str_homestory_chat_26503013 = "外で昼寝するなんて、気持ちよさそうだね。",
  str_homestory_chat_26503014 = "うん！PlayerNameも今度試してみるといいよ。",
  str_homestory_chat_26504001 = "僕に用？",
  str_homestory_chat_26504002 = "宿舎を改造したいんだけど、いい？",
  str_homestory_chat_26504003 = "ちょっと難しいな",
  str_homestory_chat_26504004 = "工事に関する問題なら、心配ないよ！",
  str_homestory_chat_26504005 = "皆に迷惑かけたくないんだ。\n改造中住めない人が出てくるでしょ？",
  str_homestory_chat_26504006 = "確かに。考えてもみなかった…",
  str_homestory_chat_26504007 = "皆にいったん天空ノ庭を出てもらうのは？",
  str_homestory_chat_26504008 = "たぶん、無理だよ…",
  str_homestory_chat_26504009 = "どう改造したいの？",
  str_homestory_chat_26504010 = "両側に耐力壁と構造壁を追加して、部屋を2つ作るの。\n真ん中の部屋は休憩用のホールにするんだ。",
  str_homestory_chat_26504011 = "そうすれば、休憩所も住居もできるでしょ。\n採光もちゃんと考えてあるんだよ。",
  str_homestory_chat_26504012 = "でも、改造するとなると時間もかかるし、\nそもそも、人手がないんだ…",
  str_homestory_chat_26504013 = "力仕事は全部あたしに任せて！",
  str_homestory_chat_26504014 = "このパワードスーツがあれば、\n基礎作りも梁を渡すのも、壁を作るのも…",
  str_homestory_chat_26504015 = "それどころか、大型遺跡の発掘やトンネル掘削だって、\nできちゃうんだから！",
  str_homestory_chat_26504016 = "すごい！",
  str_homestory_chat_26504017 = "でも、もっと他の場所で使うべきだと思うな。\n例えば、啓光の地下鉄道の建設とか。",
  str_homestory_chat_26504018 = "それこそ君の本職だよね。\n天空ノ庭では、ゆっくりしてくれていいんだよ。",
  str_homestory_chat_26504019 = "確かに…それも一理あるね。",
  str_homestory_chat_26699999 = "ねえ！PlayerName！",
  str_homestory_chat_26601001 = "ねえ！フィア！",
  str_homestory_chat_26601002 = "ど、どうしてあたしのマネするの？",
