  str_homestory_chat_26602001 = "動物を探してるの？",
  str_homestory_chat_26602002 = "うん、天空ノ庭ってたくさんいると思ってたのに…\n全然いないね！",
  str_homestory_chat_26602003 = "PlayerNameは見てない？\n絶対見たでしょ～？",
