  str_homestory_chat_26603002 = "キラキラ光るものを見なかった？\nたとえば…",
  str_homestory_chat_26603003 = "鉱石とか？",
  str_homestory_chat_26603004 = "魚とか？",
  str_homestory_chat_26603005 = "そうじゃないよ！もう！",
  str_homestory_chat_26603006 = "あたしが言ってるのは、\n小さくて、キラキラしたヤツ！",
  str_homestory_chat_26603007 = "バッグとか服とかにつけられそうなの！",
  str_homestory_chat_26603008 = "真珠のこと？",
  str_homestory_chat_26603009 = "そんな感じ！どこで見つかるの？",
  str_homestory_chat_26603010 = "川じゃないかな？\n貝がらも釣れるみたいだし。",
  str_homestory_chat_26603011 = "でも、穴のあいた靴とか、\n水草なんかが釣れることもあるね…",
