  str_homestory_chat_26604001 = "キャロは最近どう？",
  str_homestory_chat_26604002 = "最近太ったみたい！",
  str_homestory_chat_26604003 = "太った？",
  str_homestory_chat_26604004 = "最近あまり運動したがらないの！\nいつもあたしのそばにいるんだよ。",
  str_homestory_chat_26604005 = "エサを減らしたら？",
  str_homestory_chat_26604006 = "でも、キャロって実は\n何も食べなくていいんだって…",
  str_homestory_chat_26604007 = "じゃあ、キャロをもっと運動させないとね。",
  str_homestory_chat_26605001 = "木を探してるの？",
  str_homestory_chat_26605002 = "そうだよ！天空ノ庭って\n不思議な見た目の木がたくさんあるでしょ？",
  str_homestory_chat_26605003 = "珍獣がいてもおかしくないと思わない？",
