  str_homestory_chat_26605009 = "そうなの？\nああいう木っておもしろいと思うけどな～。",
  str_homestory_chat_26605010 = "だからって、動物たちが好きとは限らないよ。",
  str_homestory_chat_26799999 = "ああ、今日は身近に奇跡を見つけましたか？",
  str_homestory_chat_26701001 = "何してるの？",
