  str_homestory_chat_26802001 = "泳ぎたい？",
  str_homestory_chat_26802002 = "そうだよ。川があるでしょ？",
  str_homestory_chat_26802003 = "水の流れも速くないし、\n深さもちょうどよさそう！",
