  str_homestory_chat_26802010 = "エヘヘ。いいよいいよ。\nそれより、今度一緒に泳ぎに行こう！",
  str_homestory_chat_26803001 = "何しようとしてるの？",
  str_homestory_chat_26803002 = "目の力と手のスピードを\n鍛えようとしてるんだよ。",
