  str_homestory_chat_27021003 = "滑り台にメリーゴーランド…シーソーもいいわね。\n子どもたちが1日中遊んでも\n飽きないような場所にしたいわ。",
  str_homestory_chat_27021004 = "どうして急にそんなことを？",
  str_homestory_chat_27021005 = "そういうものが好きなのは、\n子どもだけじゃないのよ。",
  str_homestory_chat_27021006 = "特にここにいる人たち、\nまだ童心を持ち続けてる人が多いでしょう？",
  str_homestory_chat_27021007 = "そう言われてみれば…\n確かに一理あるね。考えてみるよ。",
  str_homestory_chat_27022001 = "何を聞きたいの？",
  str_homestory_chat_27022002 = "ここに銃に詳しい整備士はいないかしら？",
  str_homestory_chat_27022003 = "いないよ",
  str_homestory_chat_27022004 = "いるよ",
  str_homestory_chat_27022005 = "ただ、探さないと分からないかな。",
  str_homestory_chat_27022006 = "もしかして、銃が壊れちゃったの？",
  str_homestory_chat_27022007 = "銃の「校正」が必要なの。\n人と同じで、時どき調子が悪くなるのよ。",
  str_homestory_chat_27022008 = "そういう時に、\n銃の医者が必要になるってこと。",
  str_homestory_chat_27022009 = "影ノ街で探さないの？",
  str_homestory_chat_27022010 = "ここからじゃ遠いでしょう？\nそれに、天空ノ庭に\n常駐のガンスミスがいるのも悪くないわ。",
  str_homestory_chat_27022011 = "あなたの仲間にも需要はあるでしょ？\n1人ぐらい招待してみたらどう？",
  str_homestory_chat_27022012 = "私が紹介してあげてもいいわ。\nお値段もお手頃よ。",
  str_homestory_chat_27022013 = "いつの間にそんな話になったの…？",
  str_homestory_chat_27023001 = "何を見てるの？",
  str_homestory_chat_27023002 = "天空ノ庭は何もかもが素晴らしいわ。\nただ…ちょっと町から遠いわね。",
  str_homestory_chat_27023003 = "影ノ街の流行を知りたいと思っても、\nここじゃ無理な話だわ。",
