  str_homestory_chat_27121005 = "あれじゃダメ。まだまだ低いよ。\nそうだ…風の塔はいいね。",
  str_homestory_chat_27121006 = "たぶんないよ",
  str_homestory_chat_27121007 = "そう？そんなはずないでしょ。\n風の塔なんていい感じだよ。",
  str_homestory_chat_27121008 = "キューブたちが許してくれるかな…",
  str_homestory_chat_27121009 = "何かするつもり？",
  str_homestory_chat_27121010 = "高い所を見張り台にするんだよ。\n狙撃もできるようになるし…",
  str_homestory_chat_27121011 = "それって、防衛の基本でしょ？",
  str_homestory_chat_27121012 = "ここには…必要ないんじゃないかな。",
  str_homestory_chat_27122001 = "コーヒーが好きなんだってね。",
  str_homestory_chat_27122002 = "そうだね。\n特に砂糖もミルクも入れないブラックコーヒー。\nあんたは？",
  str_homestory_chat_27122003 = "好きだよ",
  str_homestory_chat_27122004 = "やっぱり。\nあんたもあの味に魅了されたんだね。",
  str_homestory_chat_27122005 = "ブラックコーヒーには、\nいろんなことを考えさせられるよね…",
  str_homestory_chat_27122006 = "僕は…単純に好きなだけだよ。",
  str_homestory_chat_27122007 = "そう？残念だよ。\nでも、そのうち少しずつ、\nあの味が分かるようになるよ。",
  str_homestory_chat_27122008 = "好きじゃないかな",
  str_homestory_chat_27122009 = "何も入れないと苦いから、\n僕は少し何か入れるかな。",
  str_homestory_chat_27122010 = "大体の人はそんな感じの好みだよね。\nわたしってやっぱり、はぐれ者なんだな。",
  str_homestory_chat_27122011 = "そんなことないよ。\n味の好みは人それぞれってよく言うでしょ。",
  str_homestory_chat_27123001 = "悩み事があるの？",
  str_homestory_chat_27123002 = "わたしの物言いが率直過ぎて、\n他人がイヤな気分になるって言われたの。\nほんとにそう？",
  str_homestory_chat_27123003 = "そんなことないよ",
  str_homestory_chat_27123004 = "そう…だったら安心した。",
  str_homestory_chat_27123005 = "少しそういうところもあるかな",
  str_homestory_chat_27123006 = "でも、僕は構わないと思うよ。",
  str_homestory_chat_27123007 = "だって、そういう性格なんだし、\n君が君らしい理由でしょ。",
  str_homestory_chat_27123008 = "だから、今のままでいいと思う。",
  str_homestory_chat_23099999 = "今日は何か、違法な出来事はあったかね？",
  str_homestory_chat_23001001 = "ええっと…",
  str_homestory_chat_23001002 = "あったようだな。\nでは、開廷としよう。",
  str_homestory_chat_23001003 = "まず裁判官だが、当然吾輩が担当しよう。\n法廷の警備は…",
  str_homestory_chat_23001004 = "待って、僕は「ある」なんて言ってないよ。\nどう答えようか迷ってただけなんだ。",
  str_homestory_chat_23001005 = "何？つまらんな。",
  str_homestory_chat_23021001 = "最近何してるの？",
  str_homestory_chat_23021002 = "そうだ、お主に相談があってな。\nキューブをいくらか貸してはもらえんか？",
  str_homestory_chat_23021003 = "何をするの？",
  str_homestory_chat_23021004 = "キューブは美しい直方体をしているだろう？\n実にすばらしい材料だ。",
  str_homestory_chat_23021005 = "…キューブに何かするつもりみたいだけど、\nキューブを傷つけないで。",
  str_homestory_chat_23021006 = "いかんのか？\nキューブを彫像に仕立てようと思ったのだが。",
  str_homestory_chat_23021007 = "そうすれば、この地で\n動き回る彫像が鑑賞できるであろう？",
  str_homestory_chat_23021008 = "もう一度言うよ、\nキューブたちを傷つけないで！",
  str_homestory_chat_23021009 = "む、怒ったか？\nまあ、いい。承知した。",
  str_homestory_chat_23022001 = "何か手助けが必要？",
  str_homestory_chat_23022002 = "ふむ…そうだ、近いうちに影ノ街に\n行く機会はあるかな？\n読みたい雑誌があるのだ。",
  str_homestory_chat_23022003 = "そんな時間はないよ",
  str_homestory_chat_23022004 = "お主、本当に忙しいのか？\n毎日ブラブラしているようにしか見えんが…",
  str_homestory_chat_23022005 = "吾輩を助けると思って、\n遊びに行ってくるがよかろう。",
  str_homestory_chat_23022006 = "やることがたくさんあるし、\n影ノ街だって近くはないでしょ。",
  str_homestory_chat_23022007 = "やむを得んな。\nまったく、これだからなまけ者というやつは…",
  str_homestory_chat_23022008 = "どんな雑誌？",
  str_homestory_chat_23022009 = "表紙が美しく、内容も興味深い。\n精巧な印刷で仕上げられた…",
  str_homestory_chat_23022010 = "面白そうだね。",
  str_homestory_chat_23022011 = "そうであろう？\nお主には分かるか、ふははっ。",
  str_homestory_chat_23022012 = "『彫刻芸術大全』だよね！\n僕も見たことあるよ。",
  str_homestory_chat_23022013 = "む！それは…！はぁ…",
  str_homestory_chat_23023001 = "何を探してるの？",
  str_homestory_chat_23023002 = "紙を購入したいと思ってな。\n大量の紙と、それからインクだ…",
  str_homestory_chat_23023003 = "何に使うの？本でも書くの？",
  str_homestory_chat_23023004 = "その通り、法を守る者として、\nこの地に法がないことに心を痛めておるのだ。",
  str_homestory_chat_23023005 = "ここには法律なんて必要ないと思うけど…",
  str_homestory_chat_23023006 = "紙の記録は口約束に勝るのだ！",
  str_homestory_chat_23023007 = "そんなこと言って、君が法律を作りたいだけだよね。\nどうせ自分に有利な法律なんでしょ？",
  str_homestory_chat_23023008 = "そ、そんなはずがなかろう！\n吾輩が制定する法は全て、公正なものだ！",
  str_homestory_chat_23023009 = "たとえば、白夜城裁判官の命令には\nどんなことでも必ず従うこと、といった…",
  str_homestory_chat_23023010 = "その時点でおかしいでしょ！",
  str_homestory_chat_27299999 = "PlayerName、何か撮りたいんだけど、\nいい題材はない？",
  str_homestory_chat_27221001 = "ないよ",
  str_homestory_chat_27221002 = "いつも撮影のことばかり考えてるね…",
  str_homestory_chat_27221003 = "だって…こんなに素敵な景色なのに、\nいいストーリーが浮かばないんだもん。",
