  str_homestory_chat_27221006 = "本当にないよ…",
  str_homestory_chat_27222001 = "何か買うものはある？",
  str_homestory_chat_27222002 = "車輪付きのカメラスタンドはない？\n転がして動かせるような…",
  str_homestory_chat_27222003 = "何に使うつもり？",
  str_homestory_chat_27222004 = "撮影よ。いつもセロロに持たせっぱなしじゃ、\n疲れちゃうでしょ。",
  str_homestory_chat_27222005 = "今はまだ、プロのカメラマンを雇うお金もないし…",
  str_homestory_chat_27222006 = "なるほど…でも、影ノ街に売ってないの？",
  str_homestory_chat_27222007 = "あそこは何でも高いのよ。",
  str_homestory_chat_27223001 = "ヒマそうだね？",
  str_homestory_chat_27223002 = "そうよ。いいストーリーが全然見つからないの。\nあなたは何か好きなお話、ある？",
  str_homestory_chat_27223003 = "特にないよ。",
  str_homestory_chat_27223004 = "あるかなぁ…",
  str_homestory_chat_27223005 = "バイスが送ってくれる本を読んだりするよ。",
  str_homestory_chat_27223006 = "はぁ…あなたからヒントを得るのは無理みたいね。",
