  str_homestory_chat_27223008 = "そういうのが好きなんだね。怖くないの？",
  str_homestory_chat_27223009 = "お金がないことより怖いものなんて無いわ！",
  str_homestory_chat_27223010 = "それにあたし、\nそういうストーリーのヒロインに向いてると思うの。",
