  str_homestory_chat_27224001 = "ファン？",
  str_homestory_chat_27224002 = "あなたもちょっと有名人らしいけど、\nファンはいるの？",
  str_homestory_chat_27224003 = "いると思う",
  str_homestory_chat_27224004 = "え？どんな人！？",
  str_homestory_chat_27224005 = "実は…よく知らないんだ。",
  str_homestory_chat_27224006 = "いないよ。",
  str_homestory_chat_27224007 = "それは残念ね。",
  str_homestory_chat_27224008 = "ま、ファンがいてもいなくても、\n自分なりに努力しないとね！",
  str_homestory_chat_27224009 = "その通りだね。",
  str_homestory_chat_27224010 = "だから、たまには自分を応援してあげなきゃ。\nでしょ？",
  str_homestory_chat_27224011 = "そのとおりだけど、急にそんなことを言うなんて…何かあった？",
  str_homestory_chat_27224012 = "別に…たまに疲れちゃう時もあるってだけ。",
  str_homestory_chat_27225001 = "何か欲しいものはある？",
  str_homestory_chat_27225002 = "魚が食べたいな…",
  str_homestory_chat_27225003 = "川にいるんじゃない？\nセロロならとれるでしょ。",
  str_homestory_chat_27225004 = "川魚じゃなくて、\nシーフードが食べたいの。",
  str_homestory_chat_27225005 = "カキのスープとか、シーフードリゾットとか…",
  str_homestory_chat_27225006 = "川の魚でも作れそうだけど？",
  str_homestory_chat_27225007 = "ぜんっぜん違うの！！",
  str_homestory_chat_27225008 = "シーフードにしかない味わいがあるのよ。\n口に入れると漂う、海の香り、みたいな…",
  str_homestory_chat_27225009 = "それがあると、自分にできないことはない、\n夢は実現できるって気がしてくるの！",
  str_homestory_chat_27225010 = "ただの食事でそこまで…？",
  str_homestory_chat_27399999 = "PlayerName様、\nいつでもお役に立つ用意はできております。",
  str_homestory_chat_27301001 = "こんにちは、ミノス。",
  str_homestory_chat_27301002 = "いつも礼儀正しいね。でも、天空ノ庭ではリラックスしててよ。",
