  str_homestory_chat_27301004 = "主人がここにいなくても？",
  str_homestory_chat_27301005 = "ご主人様がいつ来られてもいいよう、\n備えることも必要かと。",
  str_homestory_chat_27321001 = "君の武器って…",
  str_homestory_chat_27321002 = "ちょうど貴方を探しておりました。\n天空ノ庭には武器を修理できる方が\nいらっしゃいますか？",
  str_homestory_chat_27321003 = "いるよ。",
  str_homestory_chat_27321004 = "どちらのキューブでしょうか？",
  str_homestory_chat_27321005 = "ああ、いや…誰かできる人がいるんじゃないかな。",
