  str_homestory_chat_27321008 = "銃が壊れたの？",
  str_homestory_chat_27321009 = "まさか。執事たるもの、\n武器の手入れも仕事のうちです。",
  str_homestory_chat_27321010 = "ご主人様がいつ危険な目に遭うか分かりませんので。",
