  str_homestory_chat_27322001 = "僕に何か用？",
  str_homestory_chat_27322002 = "PlayerName様、\n正確な時間は分かりますでしょうか？",
  str_homestory_chat_27322003 = "時計に問題でもあったの？",
  str_homestory_chat_27322004 = "どれだけ精密な機械でも、誤りは出るものです。\n今朝は…",
  str_homestory_chat_27322005 = "昨日よりやや遅れているように感じまして。",
  str_homestory_chat_27322006 = "そんなことも分かるの！？",
  str_homestory_chat_27322007 = "執事としてのこだわりです。\n時間には正確でなければなりませんから。",
  str_homestory_chat_27322008 = "もしご主人様と時間がずれていたら、\nご予定を乱してしまいます。",
