  str_homestory_chat_27322010 = "僕にも君みたいな執事がいてくれたら、\nどんなに心強いか…",
  str_homestory_chat_27323001 = "何か考えてるみたいだね。",
  str_homestory_chat_27323002 = "ええ…執事はどのように\n主人と接するべきだと思われますか？",
  str_homestory_chat_27323003 = "服従する",
  str_homestory_chat_27323004 = "完全に従う、ですか…",
