  str_homestory_chat_27323009 = "つまるところ、執事は主人と\n対等の立場でいなければなりません。",
  str_homestory_chat_27323010 = "確かに、そうあるべきだね。",
  str_homestory_chat_27324001 = "ここの感想は？",
