  str_homestory_chat_28023006 = "そんなのダメです！\nおいしいネタを逃してしまいます！",
  str_homestory_chat_28023007 = "でもここの生活は平穏そのものだよ。\n他にやることを探してみたら？",
  str_homestory_chat_28023008 = "他にやることなんて…あっ、ありました！",
  str_homestory_chat_28023009 = "キューブたちを訓練して、\nいろんなニュースを\n聞いて回ってもらえるようにしましょう！",
  str_homestory_chat_28023010 = "そうすれば…ふふふ…",
  str_homestory_chat_28023011 = "それはやめて！？",
  str_homestory_chat_28199999 = "息災か？",
  str_homestory_chat_28121001 = "ところで、シュウさんって趣味はありますか？",
  str_homestory_chat_28121002 = "それがしが最も入れ込んでいるのは、木彫りだな。",
  str_homestory_chat_28121003 = "木彫り？",
  str_homestory_chat_28121004 = "いかにも。何の変哲もない木を鋭い刃で削り…",
  str_homestory_chat_28121005 = "形を彫り出していくことで、手の中で作品が生まれるのだ。",
  str_homestory_chat_28121006 = "その感覚は時折、戦よりも胸が熱くなる。",
  str_homestory_chat_28121007 = "本当に木彫りが好きなんですね…",
  str_homestory_chat_28122001 = "不思議なツリー？",
  str_homestory_chat_28122002 = "さよう。ここで変わった木を見かけた折に、\n新しい考えが浮かんでな。",
  str_homestory_chat_28122003 = "その木を彫刻に使いたい…っていうことですか？",
  str_homestory_chat_28122004 = "いかにも。承諾願えるかな？",
  str_homestory_chat_28122005 = "それはだめです",
  str_homestory_chat_28122006 = "その毅然とした口振りを見るに、\nあの木を心底大事にしているようだな。",
  str_homestory_chat_28122007 = "その…あれは育てるのが難しいので…",
  str_homestory_chat_28122008 = "うーん…",
  str_homestory_chat_28122009 = "木彫りには材料が沢山必要なんですか？",
  str_homestory_chat_28122010 = "ああ。\n特に、初めて彫る時は無駄が多く出やすい。",
  str_homestory_chat_28122011 = "不思議なツリーとやらは、木目の表情が特別だからな。",
  str_homestory_chat_28122012 = "ううん…すみません、ちょっと難しいかもしれません。",
  str_homestory_chat_28122013 = "そうか。ならば…\nここで上質な木材を手に入れるのは、諦めるより他ないな。",
  str_homestory_chat_28122014 = "そうですね…他から仕入れる方がいいかもしれません。",
  str_homestory_chat_28123001 = "猫が好きなんですか？",
  str_homestory_chat_28123002 = "ああ。ゆえに、3匹ほど飼っている。",
  str_homestory_chat_28123003 = "3匹もいるんですね！？",
  str_homestory_chat_28123004 = "でも、普段は1匹しか見かけませんよ。",
  str_homestory_chat_28123005 = "あやつらにも役割分担というものがあるのだ。",
  str_homestory_chat_28123006 = "役割分担までしてるんですね…すごいですね。",
  str_homestory_chat_28123007 = "シンは戦闘を、メンはそれがしの随伴を、そしてダクは…",
  str_homestory_chat_28123008 = "…神出鬼没だな。\nむしろ、それがしもあやつの行方は知らぬと言うべきか。",
  str_homestory_chat_28123009 = "…それって、飼ってるって言うんでしょうか…？",
  str_homestory_chat_28124001 = "何か買いたいものでもあるんですか？",
  str_homestory_chat_28124002 = "うむ、美術品を探している。部屋に飾れば、\nまるで双閣港にいるかのような雰囲気になるのではと。",
  str_homestory_chat_28124003 = "美術品って…骨董のことですか？\n龍州の骨董品は中々手に入らないかなと…",
  str_homestory_chat_28124004 = "龍州でなくともよい。\n実のところ、アストラ大陸の骨董品にも興味があってな。",
  str_homestory_chat_28124005 = "白夜城の宝剣、影ノ街の名酒、北境の骨彫刻…",
  str_homestory_chat_28124006 = "ずいぶん博識なんですね。",
  str_homestory_chat_28124007 = "それほどのことでもない。縁あってこの大陸に来たのだ、\nせっかくならば様々な骨董に触れたいと思ってな。",
  str_homestory_chat_28124008 = "これも、アストラ大陸を知る良い機会だ。",
  str_homestory_chat_28124009 = "分かりました、僕の方でも気にかけておきますね。",
  str_homestory_chat_28125001 = "いろんな彫刻？",
  str_homestory_chat_28125002 = "そうだ。\n貴公は、彫刻には詳しいのか？",
  str_homestory_chat_28125003 = "それなりに",
  str_homestory_chat_28125004 = "ほお？\nでは、この大陸にはどのような彫刻があるのだ？",
  str_homestory_chat_28125005 = "石の彫刻がほとんどですね。\n北境には骨の彫刻もあるし、木彫りが盛んな地域も多いですよ。",
  str_homestory_chat_28125006 = "啓光やR・Wには、希少な鉄の彫刻もあるそうです。",
  str_homestory_chat_28125007 = "ふむ、随分と種類が豊富なのだな…\nだが、そうか…木の根の彫刻はないのか。",
  str_homestory_chat_28125008 = "それって、何ですか？",
  str_homestory_chat_28125009 = "龍州特有の彫刻だ。\nまた折を見て、詳しく話してやろう。",
  str_homestory_chat_28125010 = "へええ…すごく気になりますね…",
  str_homestory_chat_28125011 = "全く分かりません…",
  str_homestory_chat_28125012 = "そうか。それは残念だが、諦めるとしよう。",
  str_homestory_chat_28125013 = "ええっ、なんだかまだ話し足りない気が…",
  str_homestory_chat_28299999 = "どうかしたの？",
  str_homestory_chat_28221001 = "もしかして、泳げる場所を探してたりする？",
  str_homestory_chat_28221002 = "ええ、実はそうなの。\nずっと陸にいたから、泳ぎが下手になった気がするわ。",
  str_homestory_chat_28221003 = "川で泳ぐのは？",
  str_homestory_chat_28221004 = "少し浅いわね。\nもっと深くて、波の荒いところがいいわ。",
  str_homestory_chat_28221005 = "海みたいに、波が荒いところのほうが、ね。",
  str_homestory_chat_28221006 = "それなら直接、海で練習すればいいじゃないかな…",
  str_homestory_chat_28222001 = "どんな食べ物が好き？",
  str_homestory_chat_28222002 = "私の好物は、あなたには受け入れがたいでしょうね。\n例えばタニシ麺とか…",
  str_homestory_chat_28222003 = "それならいけるかも…",
  str_homestory_chat_28222004 = "まさか、あなたも好きなの？驚いたわ。",
  str_homestory_chat_28222005 = "いや…まぁ食べられなくはないかなって。\nでも、他の人がいるところでは遠慮したいな。",
  str_homestory_chat_28222006 = "ああ、そういうことね。",
  str_homestory_chat_28222007 = "けど、食べられるというだけで十分すごいと思うわ。\nアストラ大陸の勇者と言ってもいいくらいね。",
  str_homestory_chat_28222008 = "い、いや、それほどでも。",
  str_homestory_chat_28222009 = "確かに厳しいかも…",
  str_homestory_chat_28222010 = "やっぱり、あの臭いは強烈すぎるわよね。",
  str_homestory_chat_28222011 = "私も、人のいないところで食べるようにするわ。",
  str_homestory_chat_28222012 = "それは助かるよ！",
  str_homestory_chat_28223001 = "薬を探してるの？",
  str_homestory_chat_28223002 = "ええ。船酔いの薬なのだけど、持ってるかしら？",
  str_homestory_chat_28223003 = "ううん",
  str_homestory_chat_28223004 = "多分あったはず…",
  str_homestory_chat_28223005 = "でも、ちょっと待って。\nその薬でどうするつもり？",
  str_homestory_chat_28223006 = "君はベテランの船長でしょ！",
  str_homestory_chat_28223007 = "人に渡すために決まっているでしょ。\n船酔いする人は多いもの。",
  str_homestory_chat_28223008 = "熟練の船員でも、時々なるものなのよ。",
  str_homestory_chat_28223009 = "そうなんだね…じゃあ、探してみるよ。",
  str_homestory_chat_28224001 = "船を探してるんだって？",
  str_homestory_chat_28224002 = "ええ。\n川の流れを見ていたら、ふと頭に浮かんだの。",
  str_homestory_chat_28224003 = "天空ノ庭は門戸を閉ざしているし、山道も通れない。\nでも、この川だけは順調に流れているようね。",
  str_homestory_chat_28224004 = "だから、この川を使って貿易ができないかと思ったの。",
  str_homestory_chat_28224005 = "それはちょっと…",
  str_homestory_chat_28224006 = "なぜ？",
  str_homestory_chat_28224007 = "川の流れは確かにスムーズだけど、\nキューブたちが言うには逆流が多いらしいんだ。",
  str_homestory_chat_28224008 = "しかも、暗礁がやたら多くて水深も浅いから、\n船が転覆しやすいし。",
  str_homestory_chat_28224009 = "考えてみるよ",
  str_homestory_chat_28224010 = "…そう？特に問題はないのかしら？",
  str_homestory_chat_28224011 = "キューブが言うには、川の流れはかなり複雑みたいだけど…",
  str_homestory_chat_28224012 = "でも、具体的にどんな感じかは、僕もよく知らないんだ。",
  str_homestory_chat_28224013 = "川の流れが複雑なの？\nそれなら、まずは調査してみないとね。",
  str_homestory_chat_28224014 = "どうやら少し、先走りしすぎたみたいね。",
  str_homestory_chat_28225001 = "その刀のことなんだけど…",
  str_homestory_chat_28225002 = "これがどうかしたの？",
  str_homestory_chat_28225003 = "その、苦情が届いたんだ…",
  str_homestory_chat_28225004 = "…え？誰から？どうして苦情が？",
  str_homestory_chat_28225005 = "キューブからだよ。\nしょっちゅうその刀をいじってることについて苦情が届いたんだ。",
  str_homestory_chat_28225006 = "いつも攻撃されそうな気がしてヒヤヒヤしてるみたい。",
  str_homestory_chat_28225007 = "その通りよ…",
  str_homestory_chat_28225008 = "私が天空ノ庭に来た目的はまさにそのため。\nキューブを狩るために来たの。",
  str_homestory_chat_28225009 = "えっ！？",
  str_homestory_chat_28225010 = "あら、信じたの？",
  str_homestory_chat_28225011 = "いや、本気にはしてないけれど…",
  str_homestory_chat_28225012 = "それで、何が心配なの？\n帰ってキューブたちにこう伝えてもらえるかしら。",
  str_homestory_chat_28225013 = "あなたたちの心配は取り越し苦労だ、って。\n刀をいじるのは、ただの癖みたいなものよ。",
  str_homestory_chat_28225014 = "そ、そっか…分かった。",
  str_homestory_chat_28399999 = "やあ、PlayerName。\nこの薬草、試してみない？",
  str_homestory_chat_28301001 = "わぁ、いっぱい採れたんだね！",
  str_homestory_chat_28301002 = "うん！ここの気候、薬草に合うみたいなんだよね。",
  str_homestory_chat_28301003 = "野生の植物にも、色んな薬効があるんだよ。",
  str_homestory_chat_28301004 = "特にあの変な木なんかは…",
  str_homestory_chat_28301005 = "まさか、不思議なツリーを狙ってるの？",
  str_homestory_chat_28301006 = "ううん、今のところはまだだよ。\nだって、キューブたちが目を光らせてるみたいだからさ。",
  str_homestory_chat_28301007 = "だから最近は、ここに龍州の薬草でも植えようかな～って\n思ってるんだ。",
  str_homestory_chat_28301008 = "うん、そっちの方がいいかも…",
  str_homestory_chat_28321001 = "お菓子？",
  str_homestory_chat_28321002 = "そ、ここってお菓子はないの？\n最近、お粥ばっかり食べてるからさ…",
  str_homestory_chat_28321003 = "キューブの商人に聞いたら、1つもないって言われたんだよ！",
  str_homestory_chat_28321004 = "アストラ大陸には、おいしいお菓子もないわけ？",
  str_homestory_chat_28321005 = "いや、あるよ！",
  str_homestory_chat_28321006 = "じゃあ言ってみてよ！",
  str_homestory_chat_28321007 = "北境のグミ",
  str_homestory_chat_28321008 = "ふわふわで甘すぎず、歯にもくっつかない。\n飲みこんだ瞬間、甘さがふんわり口に広がるんだ。",
  str_homestory_chat_28321009 = "影ノ街のチョコレート",
  str_homestory_chat_28321010 = "カカオだけだと苦いから、ミルクや砂糖を混ぜるお店も多いんだ。\nナッツが入ってるものもあるよ。",
  str_homestory_chat_28321011 = "たとえばヘーゼルナッツに松の実、椎の実…",
  str_homestory_chat_28321012 = "も、もう言わないで…",
  str_homestory_chat_28321013 = "リンセイ…そのよだれ…",
  str_homestory_chat_28321014 = "あ～！いつか絶対そのお菓子を食べに行くからね！\nとりあえずしばらくは…",
  str_homestory_chat_28321015 = "頭の中で想像しながら過ごすよ…",
  str_homestory_chat_28321016 = "君って、ある意味すごいよね…",
  str_homestory_chat_28322001 = "はかり？",
  str_homestory_chat_28322002 = "そう。ほらこれ、ボクの持ってるやつのことだよ。",
  str_homestory_chat_28322003 = "アストラ大陸に来てから気づいたんだけど、\n重さをはかる道具がボクのとことは違うみたいなんだよね。",
  str_homestory_chat_28322004 = "アストラ大陸のって全部地面に置いて使うタイプで、\n両端にお皿がついてるんだ。",
  str_homestory_chat_28322005 = "つまり、天秤のことだね。",
  str_homestory_chat_28322006 = "そうそれ。\nでも、持ち運びには不便そうだし、平らな地面でしか使えない。",
  str_homestory_chat_28322007 = "ボクの秤はもっと使いやすいんだよ！\nアストラ大陸の人ってあんまり物を知らないの？",
  str_homestory_chat_28322008 = "うーん…影ノ街でも秤（はかり）を使うことはあるよ。",
  str_homestory_chat_28322009 = "えっ、そうなの？",
  str_homestory_chat_28322010 = "少なくとも、リン家商会ではそうだよ。\nそれに、天秤は精度が高いんだ。",
  str_homestory_chat_28322011 = "秤は…扱う人の影響を受けやすいかも。",
  str_homestory_chat_28322012 = "そっか。\n昔から「適地適作」っていうもんね！",
  str_homestory_chat_28322013 = "つまり、それぞれに長所があるってことか！",
  str_homestory_chat_28323001 = "猫を探してるの？",
  str_homestory_chat_28323002 = "うん。\n正確には、ボクの兄さんが仲間を探してるんだ。",
  str_homestory_chat_28323003 = "リンセイのお兄さん？",
  str_homestory_chat_28323004 = "チビシッポのことだよ。それで、猫はいるの？",
  str_homestory_chat_28323005 = "ここにはいないかな…\nでも、宿泊者が何匹か連れて来るかもしれない。",
  str_homestory_chat_28323006 = "その人たちに直接聞いてみたらどうかな？",
  str_homestory_chat_28323007 = "うーん…でもみんな、アストラ大陸の人なんでしょ？\nちょっと近寄りがたいかも。",
  str_homestory_chat_28323008 = "みんな同じここの住人なんだから、大丈夫だよ！",
  str_homestory_chat_28323009 = "そ、そうかな？",
  str_homestory_chat_28323010 = "君は明るくてハツラツとしてるし、きっと大丈夫。",
  str_homestory_chat_28323011 = "ふ、ふふん！やっぱりボクが代わりに探して正解だったね！\n近いうちに聞きに行ってみよっと。",
  str_homestory_chat_28499999 = "空の末裔くん、今日はものすごく暇そうね～？",
  str_homestory_chat_28421001 = "そういうそっちも？",
  str_homestory_chat_28421002 = "アタシはちょっと散歩してただけよぉ。",
  str_homestory_chat_28421003 = "散歩？",
  str_homestory_chat_28421004 = "そ、特にやることもないし。\n天空ノ庭って、元々仕事が少ないでしょ？",
  str_homestory_chat_28421005 = "特に面白いこともないから、こうしてぶらぶらしてたの。",
  str_homestory_chat_28421006 = "そっか。",
  str_homestory_chat_28422001 = "食べ物について話す？",
  str_homestory_chat_28422002 = "ふふ、いいわよぉ。\n空の末裔くんはどんな食べ物が好きなの？",
  str_homestory_chat_28422003 = "スイーツかな。",
  str_homestory_chat_28422004 = "甘いものが好きなの…？なんだか普通ねぇ。",
  str_homestory_chat_28422005 = "でも、皆好きでしょ？チョコとかさ。",
  str_homestory_chat_28422006 = "でも、チョコって本当は苦いのよねぇ。\n甘く感じるのは、お砂糖が入ってるからだもの。",
  str_homestory_chat_28422007 = "つまり…実のところ、苦いのが好きなのかしら？",
  str_homestory_chat_28422008 = "いや、そうじゃなくて…",
  str_homestory_chat_28422009 = "肉が好き。",
  str_homestory_chat_28422010 = "あら、いいわね。じゃあ、レバーは好きかしら？\nレバーのスナックなんかどう？",
  str_homestory_chat_28422011 = "それはちょっと…無理かも。",
  str_homestory_chat_28422012 = "そう、それは残念ね～。",
  str_homestory_chat_28423001 = "木材が欲しいの？",
  str_homestory_chat_28423002 = "ええ、自分の部屋に小屋を作りたいの。いいでしょ？",
  str_homestory_chat_28423003 = "うん、もちろん。",
  str_homestory_chat_28423004 = "それはやめて。",
  str_homestory_chat_28423005 = "でも、小屋を作ってどうするつもりなの？",
  str_homestory_chat_28423006 = "あの子の家にするのよ。\n最近、なんだか寝つきが悪いみたいだから…",
  str_homestory_chat_28423007 = "あの子って？",
  str_homestory_chat_28423008 = "パイソンのことよぉ。\nずっと他の人のベッドに寝かせるわけにもいかないでしょ？",
  str_homestory_chat_28423009 = "そ、それはそうだよ！\nそんなことしたら、皆びっくりしちゃうから…",
  str_homestory_chat_28423010 = "つまり、作ってもいいってことかしら？",
  str_homestory_chat_28423011 = "うーん…君のベッドの下になら、いいよ。",
  str_homestory_chat_28424001 = "本？",
  str_homestory_chat_28424002 = "そうよ。空の末裔くんはどんな本が好きかしら？",
  str_homestory_chat_28424003 = "小説かな。",
  str_homestory_chat_28424004 = "ふぅん、なんだか普通ねぇ…",
  str_homestory_chat_28424005 = "でも、小説って傑作が多いんだよ。\n特に影ノ街の推理小説なんかは…",
  str_homestory_chat_28424006 = "まあ、確かに一般受けはするかもしれないわねぇ…",
  str_homestory_chat_28424007 = "伝記が好きかな。",
  str_homestory_chat_28424008 = "あら、そうなの？歴史に興味があるのかしら？",
  str_homestory_chat_28424009 = "うん、アストラ大陸の歴史が知りたくて。",
  str_homestory_chat_28424010 = "そういえば、イェリアはどんな本が好きなの？",
  str_homestory_chat_28424011 = "哲学関係ね。",
  str_homestory_chat_28424012 = "そうなんだ！？",
  str_homestory_chat_28424013 = "驚いてるみたいだけど、哲学って面白いのよ～？\nもし暇なら、おススメの本を教えてあげるわ。",
  str_homestory_chat_28424014 = "じゃ、じゃあ教えてもらおうかな…",
  str_homestory_chat_28425001 = "キューブ？",
  str_homestory_chat_28425002 = "そうよ、キューブって本当に賢いのねぇ。",
  str_homestory_chat_28425003 = "キューブって、どのキューブのこと？",
  str_homestory_chat_28425004 = "風の塔の広場にいる、ヒゲを生やしたキューブのことよ。",
  str_homestory_chat_28425005 = "キューブ長老？",
  str_homestory_chat_28425006 = "そうそう、「長老」と呼ばれるだけあって、\n頭脳の方もなかなかのものねぇ。",
  str_homestory_chat_28425007 = "いや、それについてはその…",
  str_homestory_chat_28425008 = "「長老」っていうのはただのニックネームで、あのヒゲも…",
  str_homestory_chat_28425009 = "あのヒゲも？",
  str_homestory_chat_28425010 = "その、付けヒゲらしいんだよね…",
  str_homestory_chat_28425011 = "あらぁ…そうだったのね。",
  str_homestory_chat_28425012 = "うう、なんだか気まずい…",
  str_homestory_chat_28425013 = "じゃ、じゃあ僕はこのへんで…またね！",
  str_homestory_chat_28599999 = "PlayerNameさん、こんにちは。今日はどんなご用ですか？",
  str_homestory_chat_28501001 = "いや、特に用事はないんだけど…\nそういう君は？",
  str_homestory_chat_28501002 = "私ですか？\nちょうど天空ノ庭でアルバイトでも探そうと思っていまして。",
  str_homestory_chat_28501003 = "アルバイト？",
  str_homestory_chat_28501004 = "はい。キューブの長老やキューブの商人にも聞いたのですが、\n仕事はないと言われました。",
  str_homestory_chat_28501005 = "そうだね…ここは元々仕事が少ないし、\nあってもみんな自分で片づけちゃうから。",
  str_homestory_chat_28501006 = "何か配達の仕事はありませんか？\n伝言を届けるのでも構いませんよ。",
  str_homestory_chat_28501007 = "うーん…ここはそんなに広い場所じゃないから、需要がないと思う。\nそれに、皆ここに休みに来てるわけだし。",
  str_homestory_chat_28501008 = "ふぅ…そうですか。",
  str_homestory_chat_28521001 = "嫌いなもの？",
