  str_homestory_chat_28521009 = "そう言うキアは、嫌いなものってある？",
  str_homestory_chat_28521010 = "もちろん遅刻魔です！",
  str_homestory_chat_28521011 = "なぜ時間を守れないのでしょう…\nしかも、ちゃんと約束だってしているのに…",
  str_homestory_chat_28521012 = "ちょっとくらい遅刻してもいいなんて言う人は…\nよぉく懲らしめてやるべきです！",
