  str_homestory_chat_29022013 = "待って！まだいいって言ってないよ！",
  str_homestory_chat_29023001 = "召使いを雇う？",
  str_homestory_chat_29023002 = "そうだ、手厚い待遇をしてやるぞ。",
  str_homestory_chat_29023003 = "聞きたいんだけど、なぜ召使いを雇おうと思ったの？",
  str_homestory_chat_29023004 = "ここには召使いなんていないよ。",
  str_homestory_chat_29023005 = "なぜ急にそうしようと思ったの？",
  str_homestory_chat_29023006 = "雑用は召使いに任せるべきだからだ。",
  str_homestory_chat_29023007 = "貴族として、私はもっと重要なことに時間を使わねば。",
  str_homestory_chat_29023008 = "例えば、天空ノ庭の建設について考えたり、付近で宝石の鉱脈を探したり。",
  str_homestory_chat_29023009 = "ここに来たなら、普通の人の生活を体験してよ…",
  str_homestory_chat_29023010 = "もしかしたら…あの四角い頭のやつらが適任かもしれん。",
  str_homestory_chat_29023011 = "キューブのこと？",
  str_homestory_chat_29023012 = "ずばりその通り。",
  str_homestory_chat_29023013 = "ダメだよ！",
  str_homestory_chat_29199999 = "天空ノ庭を巡回しているの？それとも散歩？",
  str_homestory_chat_29101001 = "何をしてるの？",
  str_homestory_chat_29101002 = "やることがないからボンヤリしてるんだよ。",
  str_homestory_chat_29101003 = "すごく正直な答えだね…",
  str_homestory_chat_29101004 = "だって本当に何もすることがないからね。\nここで自分のことを考えていたんだよ。",
  str_homestory_chat_29101005 = "うん、ちょうどリラックスできるね。",
  str_homestory_chat_29121001 = "子ども？",
  str_homestory_chat_29121002 = "ああ。子どもがいないから、少し…\n静かすぎる気がする。",
  str_homestory_chat_29121003 = "いるよ",
  str_homestory_chat_29121004 = "どこに？",
  str_homestory_chat_29121005 = "たとえば、白夜城やR・Wの仲間たちとか…",
  str_homestory_chat_29121006 = "数日したら、\nしばらく天空ノ庭に泊まりに来るはずだよ。",
  str_homestory_chat_29121007 = "あいつらのことか…はぁ。",
  str_homestory_chat_29121008 = "どうしてため息をつくの？",
  str_homestory_chat_29121009 = "あいつらはもう子どもじゃないよ。\n独り立ちして暮らせるからね。",
  str_homestory_chat_29121010 = "それもそうだね。",
  str_homestory_chat_29121011 = "確かにね。",
  str_homestory_chat_29121012 = "はぁ…キューブを見つけて\n気晴らしするしかないみたいだね。",
  str_homestory_chat_29121013 = "気晴らし？何するつもり？",
  str_homestory_chat_29121014 = "心配いらないよ。遠くからキューブたちを見守って、\n何かあったら助けてあげるだけだから。",
  str_homestory_chat_29121015 = "たとえば、転んだ時に起き上がらせてあげるとか。",
  str_homestory_chat_29121016 = "えっ…そんな親切だったの？",
  str_homestory_chat_29121017 = "なんだって？",
  str_homestory_chat_29121018 = "なんでもない！ありがとう！",
  str_homestory_chat_29122001 = "なぞなぞ？",
  str_homestory_chat_29122002 = "なぞなぞは好き？",
  str_homestory_chat_29122003 = "好きだよ",
  str_homestory_chat_29122004 = "あまり好きじゃない",
  str_homestory_chat_29122005 = "どうして急にそんなことを聞くの？",
  str_homestory_chat_29122006 = "すごく退屈だし、新聞のクロスワードパズルもなくて、\n気晴らしできないから。",
  str_homestory_chat_29122007 = "あの眼鏡をかけたキューブなら好きだと思ったら、\n頭の中は帳簿の勘定でいっぱいだった。",
  str_homestory_chat_29122008 = "あの長いひげのキューブは、\nアンタみたいに一日中ブラブラしているけど…",
  str_homestory_chat_29122009 = "オホン。僕は天空ノ庭の巡回をしているんであって、\nブラブラしているわけじゃないよ。",
  str_homestory_chat_29122010 = "でも、ハーティ、\nなぞなぞ以外に気晴らしする方法を思いつかないの？",
  str_homestory_chat_29122011 = "だって、なぞなぞはすごく面白いでしょ。\n特に難しいなぞなぞが解けたときは…",
  str_homestory_chat_29122012 = "あの爽快感は言葉にできないよ！",
  str_homestory_chat_29122013 = "やっぱり頭を休めようよ…",
  str_homestory_chat_29123001 = "何を買うの？",
  str_homestory_chat_29123002 = "針と糸だよ。",
  str_homestory_chat_29123003 = "何かを縫おうとしているみたいだけど、\n服が破けたの？",
  str_homestory_chat_29123004 = "アンタの感知能力はすごいけど、\n目は悪いみたいだね。",
  str_homestory_chat_29123005 = "えっ？",
  str_homestory_chat_29123006 = "あの人形が壊れちゃったから、\n縫ってあげるんだよ。",
  str_homestory_chat_29123007 = "君ってこんなものも縫えるんだ…",
  str_homestory_chat_29123008 = "おかしい？人形も作れるよ。\n生地の切れ端、針、糸があればね。",
  str_homestory_chat_29123009 = "人は見かけによらないね…",
  str_homestory_chat_29123010 = "じゃあ、PlayerNameから見て、\nボクはこういうことができない人に見えるってこと？",
  str_homestory_chat_29123011 = "だって、ハーティはいつもカッコいいし、\n話し方や行動もテキパキしているから。",
  str_homestory_chat_29123012 = "それはアンタの固定観念だね。",
  str_homestory_chat_29123013 = "行動がテキパキしているのと、\n人形を縫うことの間に必然的な関係はないよ。",
  str_homestory_chat_29123014 = "その通りだね。",
  str_homestory_chat_29124001 = "スパイス？",
  str_homestory_chat_29124002 = "スパイスがほしいんだ。味付けに使うから。",
  str_homestory_chat_29124003 = "何かおいしいものを作ろうとしているみたいだね。",
  str_homestory_chat_29124004 = "そう！シチューだよ！",
  str_homestory_chat_29124005 = "シチュー！",
  str_homestory_chat_29124006 = "じゃあ、わざわざいい肉を持ってきたの？",
  str_homestory_chat_29124007 = "いい肉？持ってきてないよ。",
  str_homestory_chat_29124008 = "えっ？",
  str_homestory_chat_29124009 = "持ってくるのは面倒だし、傷んじゃうでしょ。\nここには売ってないの？",
  str_homestory_chat_29124010 = "それは…売ってないよ…",
  str_homestory_chat_29124011 = "それはさすがに厄介な問題だね。\n狩りの獲物もいなさそうだし。",
  str_homestory_chat_29124012 = "まさか釣りをして、\n魚で肉の代わりにするしかないとか？",
  str_homestory_chat_29124013 = "それじゃあ魚スープになっちゃうんじゃ…",
  str_homestory_chat_29124014 = "魚のシチューでもいいよ。\n時にはとてもおいしく作れるし、\n特に調味料はいらないからね。",
  str_homestory_chat_29124015 = "もう肉のことを考えてないみたいだね。",
  str_homestory_chat_29399999 = "何かご用でしょうか？",
  str_homestory_chat_29321001 = "槍術訓練？",
  str_homestory_chat_29321002 = "おうかがいしたいのですが、\n天空ノ庭に槍術の教官はいらっしゃいますか？",
  str_homestory_chat_29321003 = "ここは…平和な場所だから。",
  str_homestory_chat_29321004 = "自分の状態を維持するための、ただの通常訓練です。\n訓練しないとランスの感覚も鈍ってしまいますから。",
  str_homestory_chat_29321005 = "そこまでにはならないでしょ。\nここに数日滞在するだけなのに、そんなに頑張るの？",
  str_homestory_chat_29321006 = "手を抜いていいはずがありません！\n白夜城の貴族たる者、\nこれは守り続けなければならない習慣なのです。",
  str_homestory_chat_29321007 = "じゃあ…まずは1人で練習してみなよ。",
  str_homestory_chat_29322001 = "君について苦情を言った人がいるらしいよ。",
  str_homestory_chat_29322002 = "えっ？どなたでしょうか？",
  str_homestory_chat_29322003 = "君のルームメイトだよ。",
  str_homestory_chat_29322004 = "まさか毎日ランスの練習をしているせいで、\n皆さんを怖がらせてしまったのでしょうか？",
  str_homestory_chat_29322005 = "そうなんだよ。",
  str_homestory_chat_29322006 = "それから…他にもあって。",
  str_homestory_chat_29322007 = "それでは…朝起きるのが早すぎて、\n彼女たちを起こしてしまうとか？",
  str_homestory_chat_29322008 = "それもあるけど…",
  str_homestory_chat_29322009 = "ということは…他にもあるのでしょうか？",
  str_homestory_chat_29322010 = "うん。君がいつも布団を四角く折りたたむことに\n不満があるみたいなんだよ。",
  str_homestory_chat_29322011 = "そうすべきではありませんか？\nベッドの上で乱れたままにしておくなんて\n気持ち悪いです！",
  str_homestory_chat_29322012 = "要するにね…\n他の人にもそうするよう強制はできないよ。",
  str_homestory_chat_29322013 = "ですが…",
  str_homestory_chat_29322014 = "とにかく、他の人に対する基準は緩めた方がいいよ。",
  str_homestory_chat_29323001 = "キューブに何を聞きたいの？",
  str_homestory_chat_29323002 = "彼らを私の従者にできるか聞きたいのです。",
  str_homestory_chat_29323003 = "天空ノ庭にはそんな前例はないよ。\nそれに白夜城がそんなこと許さないんじゃないの？",
  str_homestory_chat_29323004 = "私は騎士です。当然、従者を募集する権利があります。\n天空ノ庭の主、お願いできませんか？",
  str_homestory_chat_29323005 = "いいよ",
  str_homestory_chat_29323006 = "考えてみるよ",
  str_homestory_chat_29323007 = "待って！どうして急にキューブたちを\n君の従者にしたくなったの？",
  str_homestory_chat_29323008 = "彼らがとても適していると思うからです！",
  str_homestory_chat_29323009 = "真四角の頭、真四角の体…",
  str_homestory_chat_29323010 = "きっと騎士の美徳を守る、\n素晴らしい従者になるはずです！",
  str_homestory_chat_29323011 = "君は完全に誤解していると思うよ…",
  str_homestory_chat_29323012 = "そんなことありません！\n「心は外見に宿る」とも言います。\nきっと大丈夫です！",
  str_homestory_chat_29323013 = "悪いけど応じられないよ…\nだって、本当にダメだから。",
  str_homestory_chat_29324001 = "オペラ？",
  str_homestory_chat_29324002 = "オペラにどのような印象をお持ちですか？",
  str_homestory_chat_29324003 = "悪くないよ",
  str_homestory_chat_29324004 = "それならよかったです！",
  str_homestory_chat_29324005 = "特に何も…",
  str_homestory_chat_29324006 = "はぁ…うまく進まないかもしれませんね。",
  str_homestory_chat_29324007 = "何をするの？",
  str_homestory_chat_29324008 = "天空ノ庭にステージを作りたいのです。\nそうすれば、歌劇団を呼んで公演してもらえますから。",
  str_homestory_chat_29324009 = "余力があれば…劇場を作るのも悪くないですね。\nそれからお抱えの劇団も。",
  str_homestory_chat_29324010 = "そうすれば、\nいつでも最新のオペラを楽しめます。",
  str_homestory_chat_29324011 = "それは…やっぱり無理なんじゃないかな。",
  str_homestory_chat_29999999 = "こんにちは、最近どうです？",
  str_homestory_chat_29901001 = "いい感じだよ、君は？",
  str_homestory_chat_29901002 = "天空ノ庭での生活にも慣れました。ちょっとペースがゆっくりに感じますけど。",
  str_homestory_chat_29901003 = "ゆっくり？",
  str_homestory_chat_29901004 = "たまには何か歯ごたえのあるイベントがあるといいんですけど。例えば木を切る大会とか？",
  str_homestory_chat_29901005 = "ゆったりとした時間を楽しんだ方がいいよ。",
  str_homestory_chat_29921001 = "飲み物？",
  str_homestory_chat_29921002 = "飲み物は何が好きですか？",
  str_homestory_chat_29921003 = "コーヒー",
  str_homestory_chat_29921004 = "一般受けする味ですね。仲間の影響を受けたのかしら？",
  str_homestory_chat_29921005 = "うん、それに一種のリラックス方法であることも多いよ、自分でコーヒーを淹れたり……",
  str_homestory_chat_29921006 = "カフェに行けば、コーヒーを飲みながら友達とおしゃべりもできるしね。",
  str_homestory_chat_29921007 = "なるほど。",
  str_homestory_chat_29921008 = "お茶",
  str_homestory_chat_29921009 = "お茶のどこが好きですか？苦いお茶もあると聞きましたが。",
  str_homestory_chat_29921010 = "適当な調味料を加えれば美味しく飲めるよ。それに茶葉だけ入れたとしても……",
  str_homestory_chat_29921011 = "口に含むと苦いけど、飲んだ後に喉に何とも言えない甘い香りが広がるんだ。",
  str_homestory_chat_29921012 = "眠気覚ましにもなると聞きました。",
  str_homestory_chat_29921013 = "その通り、飲んでみるといいよ。",
  str_homestory_chat_29921014 = "ジュース",
  str_homestory_chat_29921015 = "ナチュラルテイストがお好みですか……やっぱり空の末裔ですね。",
  str_homestory_chat_29921016 = "ミックスジュースもいいんだ……たぶんフレッシュな感じが好きなんだと思う。",
  str_homestory_chat_29921017 = "それに、色々な栄養が摂れて体にもいいですね、私も後で検討してみます。",
  str_homestory_chat_29921018 = "そうだね、素晴らしい！",
  str_homestory_chat_29921019 = "ソーダ水",
  str_homestory_chat_29921020 = "飲むとゲップが出るような飲み物が好きだなんて！信じられません！",
  str_homestory_chat_29921021 = "そんなに激しくリアクションしなくても……",
  str_homestory_chat_29922001 = "何かを植えるの？",
  str_homestory_chat_29922002 = "天空ノ庭に、豆を植えるための畑を作りたいんです。",
  str_homestory_chat_29922003 = "いいよ",
  str_homestory_chat_29922004 = "ここには空き地がたくさんあるはずだから……でもまずキューブたちに聞いてね。",
  str_homestory_chat_29922005 = "だめだよ",
  str_homestory_chat_29922006 = "待って、どうして豆なの？",
  str_homestory_chat_29922007 = "啓光の研究によると、この豆は大規模栽培に最も適した作物であり、栄養価も高めなんです。",
  str_homestory_chat_29922008 = "味は？",
  str_homestory_chat_29922009 = "まるで千変万化ですよ！とくに色々な豆製品！",
  str_homestory_chat_29922010 = "影ノ街にもたくさんあったような……あと「豆腐」なんてのもあったような気がする。",
  str_homestory_chat_29922011 = "それなら知ってます！東方から来た食べ物で、まるで摩訶不思議な傑作だと聞いたことがあります！",
  str_homestory_chat_29922012 = "口当たりが柔らかく、調味料を加えないと豆の風味が感じられて……",
  str_homestory_chat_29922013 = "なのに何にでも合うんです！甘いもの、しょっぱいもの、酸っぱいもの、辛いもの、豆腐はどんな調味料にも合うんです！",
  str_homestory_chat_29922014 = "確かにすごいな……",
  str_homestory_chat_29923001 = "影ノ街に行きたいの？",
  str_homestory_chat_29923002 = "長いこと天空ノ庭にいて、ここは影ノ街との交流があまり頻繁ではないとふと気付いたんです。",
  str_homestory_chat_29923003 = "うん、天空ノ庭は一般的にはまだやや辺鄙な場所だからね。",
  str_homestory_chat_29923004 = "それがここの特長と言うべきですよ。不便さと引き換えに邪魔されない安らぎがあるのですから。",
  str_homestory_chat_29923005 = "でもここから影ノ街に行くのは、それほど大変じゃないはずだよ……",
  str_homestory_chat_29923006 = "主に、影ノ街で定期的に牛乳を買いたいんです。",
  str_homestory_chat_29923007 = "牛乳？",
  str_homestory_chat_29923008 = "啓光には配給の牛乳がありましたが、天空ノ庭にはなさそうですし、お店もありません。",
  str_homestory_chat_29923009 = "確かに。飲みたくなったら外から買うしかない。",
  str_homestory_chat_29923010 = "もし飲みたいなら、今度僕が影ノ街に行く時に言ってくれれば、何ケースか買ってくるよ。",
  str_homestory_chat_29923011 = "でも影ノ街までは距離があるでしょう、おそらく新鮮な牛乳は期待できませんね……",
  str_homestory_chat_29923012 = "じゃあ……ヨーグルト？",
  str_homestory_chat_29923013 = "ヨーグルトもいいですね、問題ありません！",
  str_homestory_chat_29923014 = "それなら良かった。",
  str_homestory_chat_29924001 = "バードハウス？",
  str_homestory_chat_29924002 = "ええ、窓にぶら下げたり、屋根の上に置いたりするあれです。",
  str_homestory_chat_29924003 = "そうじゃなくて……どうしてバードハウスを作りたいのかってこと。",
  str_homestory_chat_29924004 = "アオハのためですよ。いつも私の指先にとまらせるわけにもいかないでしょう。",
  str_homestory_chat_29924005 = "特に私が寝ている時は……行き場がない感じなんです。",
  str_homestory_chat_29924006 = "確かにそれはかわいそうだね。",
  str_homestory_chat_29924007 = "だから、大きくなくていいので、小屋を作ってあげたいんです。",
  str_homestory_chat_29924008 = "影ノ街でも見かけたな。そういう小屋は確かにシンプルだ。でも木材が……",
  str_homestory_chat_29924009 = "もうキューブに買いに行くよう頼みました。",
  str_homestory_chat_29924010 = "さすがインゲル、本当に効率的だね。",
  str_homestory_chat_29924011 = "同意してくれたようですね？",
  str_homestory_chat_29924012 = "反対する理由はなさそうだし……他人のスペースを占領しなければいいよ。",
  str_homestory_chat_29924013 = "次は大工を探さないと……",
  str_homestory_chat_29924014 = "出来上がるまではまだまだかかりそうだね……。",
  str_homestory_chat_29299999 = "会えて嬉しい。",
  str_homestory_chat_29201001 = "調子はどう？",
  str_homestory_chat_29201002 = "平和で豊かな天空ノ庭はまさに楽園だ、ここで休めて光栄だ。",
  str_homestory_chat_29201003 = "気に入ってもらえてよかった、リラックスしていって。",
  str_homestory_chat_29201004 = "だから、この楽園を守るために、私ももっと努力しなくてはといつも思う。",
  str_homestory_chat_29201005 = "特に、腐敗した汚泥がここを汚すことで、外から邪気が入るようなことがあってはならない。",
  str_homestory_chat_29201006 = "ありがとう、お疲れ様。",
  str_homestory_chat_29221001 = "果物は何が好き？",
  str_homestory_chat_29221002 = "どうして突然そんなことを聞くんだ？",
  str_homestory_chat_29221003 = "たまたま思いついただけだよ。",
  str_homestory_chat_29221004 = "私は南方の果物が好きだ。ジューシーで栄養価が高く、多彩な味があるからな。",
  str_homestory_chat_29221005 = "お前は？",
  str_homestory_chat_29221006 = "リンゴ。",
  str_homestory_chat_29221007 = "ありふれた果物だな。どこが好きなんだ？",
  str_homestory_chat_29221008 = "ありきたりだからかも。それ以外にもリンゴは甘くて歯ごたえがあるし。",
  str_homestory_chat_29221009 = "確かにな。一般的だからこそ、作り方も色々ある。",
  str_homestory_chat_29221010 = "味付けもできると聞いている。その点では、本当に皆に恩恵がある果物だな。",
  str_homestory_chat_29221011 = "確かに。",
  str_homestory_chat_29221012 = "ブドウ。",
  str_homestory_chat_29221013 = "ブドウもありきたりだな。それに多くの飲み物の元にもなっている。",
  str_homestory_chat_29221014 = "たとえば？",
  str_homestory_chat_29221015 = "白夜城の食事に添えられるワイン、啓光連邦のソーダもブドウジュースで味付けされているものがある。",
  str_homestory_chat_29221016 = "R・W砂漠では、ブドウを日干ししておやつにする人もいると聞いたことがある。",
  str_homestory_chat_29221017 = "それはもう飲み物じゃないでしょ？",
