  str_homestory_chat_29222003 = "何それ？",
  str_homestory_chat_29222004 = "簡単に言うとシンプルに煮込んだ肉だな。そして好きな調味料を合わせるんだ。",
  str_homestory_chat_29222005 = "とても便利な食べ物みたいだね。",
  str_homestory_chat_29222006 = "兵士にとって、こういう食べ物は便利なだけでなく、とても美味いしすぐにエネルギー補給ができるんだ。",
  str_homestory_chat_29222007 = "だから肉の供給には常に気を配り、戦地でも温かい食事を保証することがとても大切なことなんだ。",
  str_homestory_chat_29222008 = "それも複雑な事情だがな……",
  str_homestory_chat_29222009 = "複雑？",
  str_homestory_chat_29222010 = "考えなきゃいけないことがたくさんあるんだ。まず、温かい食事を作るための燃料が問題だ。",
  str_homestory_chat_29222011 = "それから、肉の鮮度を保つことから、兵士全員の味覚のニーズに応えることまで。",
  str_homestory_chat_29222012 = "どれもリーダーが考えるべきことであり、一歩間違えれば士気の低下につながる。",
  str_homestory_chat_29222013 = "本当に……大変だね。",
  str_homestory_chat_29223001 = "地図を描いているの？",
