  str_homestory_chat_29223005 = "よく知らない",
  str_homestory_chat_29223006 = "何のための地図？",
  str_homestory_chat_29223007 = "ここに来て何日も経つが、いつも落ち着かない気持ちだったんだ。",
  str_homestory_chat_29223008 = "どうしてそう感じるの？",
  str_homestory_chat_29223009 = "よくよく考えて見ると、天空ノ庭に慣れていないせいだとわかった。",
  str_homestory_chat_29223010 = "言い換えれば、土地勘がなく、慣れない場所にいつも不安を感じてるってことだ。",
  str_homestory_chat_29223011 = "部外者が駆け込んでくることはないから、安心していいよ。",
  str_homestory_chat_29223012 = "そうは言っても……測量し地図を作って地形を把握しないと、安心できないんだ。",
  str_homestory_chat_29223013 = "そっか……じゃあ頑張って。",
  str_homestory_chat_29224001 = "武器を買いたいって？",
