  str_homestory_chat_29224003 = "博物館？",
  str_homestory_chat_29224004 = "白夜城の長槍や、啓光のサーベルなど、色々な武器に関しての……",
  str_homestory_chat_29224005 = "博物館を建てる必要ある？武器の種類はそれほど多くないみたいだから、コレクションルームを作ればいいよね？",
  str_homestory_chat_29224006 = "そんなことないさ！啓光連邦のように武器を量産するのが好きな場所でも、いろいろな種類があるんだ！",
  str_homestory_chat_29224007 = "長銃や短銃、ブレードに短剣、近接に遠距離、冷兵器に火器など色々だ、数十種類はあるだろうな。",
  str_homestory_chat_29224008 = "まして、白夜城の貴族たちが自分で使う武器は、デザインや紋章がすべて違うんだ。",
  str_homestory_chat_29224009 = "細かく話していたら三日三晩では足りない。だからコレクションルームでは絶対に不十分なんだ。",
  str_homestory_chat_29224010 = "そんなにたくさんあるんだ……待って！もしかして君はそれらの武器を全部持ってるの？",
  str_homestory_chat_29224011 = "ほんの一部だが、今すぐコレクションを始めてもかまわない。",
  str_homestory_chat_29224012 = "それほど多くは持ってないんだね……安心したよ。",
