  str_homestory_chat_30125003 = "昼間の外出？",
  str_homestory_chat_30125004 = "ええ。だって私は…その…",
  str_homestory_chat_30125005 = "分かったよ",
  str_homestory_chat_30125006 = "でもここは影ノ街みたいな場所とは少し違うでしょう？",
  str_homestory_chat_30125007 = "そうね…街並みも商店もないわ。",
  str_homestory_chat_30125008 = "もしかして…退屈？",
  str_homestory_chat_30125009 = "そ、そんなことない。",
  str_homestory_chat_30125010 = "派手さはないけれど、自然の風景もとても素敵よ。",
  str_homestory_chat_30125011 = "鳥や虫のさえずりに耳を傾けたり、陽光を浴びてきらきらと輝く小川を眺めたり…",
  str_homestory_chat_30125012 = "ちょっと無理してる気も…今度はキューブたちに商品を買わせておくよ。",
  str_homestory_chat_30125013 = "願いの泉、風の塔、ミュージアムもとても楽しい…",
  str_homestory_chat_30125014 = "そ、そうだね…",
  str_homestory_chat_30399999 = "占いですか！",
  str_homestory_chat_30321001 = "聞きたいことがあるんだ…",
  str_homestory_chat_30321002 = "おお、ついに仕事の依頼が来ました。それで何を占いますか？",
  str_homestory_chat_30321003 = "仕事",
  str_homestory_chat_30321004 = "金運",
  str_homestory_chat_30321005 = "恋愛",
  str_homestory_chat_30321006 = "選びましたか？では始めましょう！",
  str_homestory_chat_30321007 = "待って。聞きたいのは占いじゃなくて…",
  str_homestory_chat_30321008 = "では何ですか？もう準備を始めてますけど。",
  str_homestory_chat_30321009 = "聞きたいのはね、君の占いって本当に役立つの？",
  str_homestory_chat_30321010 = "何ですって？子供の頃からずっと修行してますよ！",
  str_homestory_chat_30321011 = "じゃあ、未来も予測できる？何もかも占えば分かるの？",
  str_homestory_chat_30321012 = "一概には言えませんよ。まず占いには良い環境とタイミングが必要ですし、さらには霊感も必要で…",
  str_homestory_chat_30321013 = "一番大事なのは運です！うまくいかない時もありますから！",
  str_homestory_chat_30321014 = "つまり、占いには失敗もあるのです！",
  str_homestory_chat_30321015 = "なるほど。",
  str_homestory_chat_30323001 = "今は必要ないかな…",
  str_homestory_chat_30323002 = "むぅ、今霊感が降りてきたのに、あなたの言葉で消えてしまいました。",
  str_homestory_chat_30323003 = "あっ…ごめんね。",
  str_homestory_chat_30323004 = "新しい「ペアルック」を考えるしかありませんね。",
  str_homestory_chat_30323005 = "「ペアルック」？",
  str_homestory_chat_30323006 = "蛇のウィスパーにあげるんですよ。私たちはお揃いの服を着るほうがいいんです。",
  str_homestory_chat_30323007 = "ウィ、ウィスパーも服を着るの？",
  str_homestory_chat_30323008 = "そうですよ。ウィスパーが寒いと可哀想じゃないですか。",
  str_homestory_chat_30323009 = "服を着れば防寒できるし、ペアでコーデもできますよ。",
  str_homestory_chat_30323010 = "すごいね！でもウィスパーが着る服って…",
  str_homestory_chat_30323011 = "私がデザインして作ります！",
  str_homestory_chat_30322001 = "物語を聞かせるのが好きなんだって？",
  str_homestory_chat_30322002 = "そうですよ！特に占い中ですね。",
  str_homestory_chat_30322003 = "占い中に物語を聞かせるの？",
  str_homestory_chat_30322004 = "相手の注意力を引き付けるためです。そうすれば相手は私の占い結果に全集中してくれます。",
  str_homestory_chat_30322005 = "しかも万が一占いに失敗しても、相手も損をしたとは思いません。",
  str_homestory_chat_30322006 = "そ、それって、ごまかしでは…",
  str_homestory_chat_30322007 = "全然違います！素晴らしい物語はプライスレスです！",
  str_homestory_chat_30322008 = "そのために私は常にルイスに連絡して、あちらこちらを連れ回しているんです！",
  str_homestory_chat_30322009 = "ルイス？",
  str_homestory_chat_30322010 = "はい。彼女も北境人ですし、物語を話すのがとても上手なんです。",
  str_homestory_chat_30322011 = "君たちは影ノ街で小説家になれそうだね…",
  str_homestory_chat_30324001 = "石を探しているの？",
  str_homestory_chat_30324002 = "はい。素敵な石がある場所を知りませんか？",
  str_homestory_chat_30324003 = "川岸",
  str_homestory_chat_30324004 = "森の中",
  str_homestory_chat_30324005 = "ありがとうございます！",
  str_homestory_chat_30324006 = "石を探しているのは占いに使うため？",
  str_homestory_chat_30324007 = "いいえ、おしゃれのためです。",
  str_homestory_chat_30324008 = "白い服を着て毎日ぶらぶらしてるキューブたちを見て、シンプルすぎると思ったんですよ。",
  str_homestory_chat_30324009 = "だからキューブたちが色とりどりの石のネックレスをつければ素敵になると思いませんか？",
  str_homestory_chat_30324010 = "待て待て！キューブには聞いてないよね！？",
  str_homestory_chat_30324011 = "大丈夫。きっと喜んでくれます！",
  str_homestory_chat_30324012 = "そ、そこは慎重に行こうね…",
  str_homestory_chat_30499999 = "また会ったわね。あなた、本当に真面目ね。",
  str_homestory_chat_30421001 = "ちょうど巡回してたところです。",
  str_homestory_chat_30421002 = "あなたは色々な所へ行ったことがあると聞いたけど、\n隠居生活にふさわしいのはどこだと思う？",
  str_homestory_chat_30421003 = "隠居ですか？\nだったら、一人でも生活できるような場所がいいのでは？",
  str_homestory_chat_30421004 = "少し違うわね。他人の注意を引くことなく、\nけれど周りにはご近所さんもいるような所が一番いいわ。",
  str_homestory_chat_30421005 = "ううん…そうですねぇ…",
  str_homestory_chat_30421006 = "影ノ街",
  str_homestory_chat_30421007 = "「人混みに紛れると、かえって人目を引かない」って、\nよく言いますよね。",
  str_homestory_chat_30421008 = "賑やかな所に行けば、人の数だけじゃなく、\n色々なタイプの人がいるので、注目されることはないと思いますよ。",
  str_homestory_chat_30421009 = "候補の一つね。",
  str_homestory_chat_30421010 = "北境",
  str_homestory_chat_30421011 = "世界の尾根のふもとね…",
  str_homestory_chat_30421012 = "静かで、人里離れた寒冷地…確かにいい所だわ。",
  str_homestory_chat_30421013 = "人は少ないとは思いますけど…\n広大な土地に少数の住民が暮らしていて、しかも閉鎖的だと聞きました。",
  str_homestory_chat_30421014 = "安全と静けさの代償ね…",
  str_homestory_chat_30421015 = "R・W",
  str_homestory_chat_30421016 = "あら？R・Wは確かあちこち駆け回っている方たちの\n集まりではなかったかしら？",
  str_homestory_chat_30421017 = "それはそうなんですが、\nあそこには他の組織から来た人たちがたくさんいるみたいなんです。",
  str_homestory_chat_30421018 = "それに仲間になって、雰囲気に慣れると、\n皆いい人たちだって感じるはずです。",
  str_homestory_chat_30421019 = "何だか素敵ね。",
  str_homestory_chat_30421020 = "小さな村",
  str_homestory_chat_30421021 = "小さな村ならどこにでもありそうね。\n最後の選択肢として考えておきましょう。",
  str_homestory_chat_30421022 = "確かにその通りですね。",
  str_homestory_chat_30422001 = "夫人はよく笑うんですね。",
  str_homestory_chat_30422002 = "それはここが好きだからよ。",
  str_homestory_chat_30422003 = "ありがとうございます。",
  str_homestory_chat_30422004 = "よくある風景かもしれないけれど…とても安心するわ。",
  str_homestory_chat_30422005 = "他の所では感じることのできない心地良さね。",
  str_homestory_chat_30422006 = "たぶん、へんぴな場所だからじゃないですか？",
  str_homestory_chat_30422007 = "いいえ、この土地の空気感と関係があるのだと思うわ。\n特にここにいる人たちのね。",
  str_homestory_chat_30422008 = "みなさんの笑顔とのんびり暮らすキューブたち…",
  str_homestory_chat_30422009 = "のんびり、ですか…またサボってましたか？",
  str_homestory_chat_30422010 = "そういう意味じゃないわ。",
  str_homestory_chat_30423001 = "早起きですね。",
  str_homestory_chat_30423002 = "ベッドを整えなければいけないでしょう？",
  str_homestory_chat_30423003 = "ベッドを整えるんですか？夫人が自分で？",
  str_homestory_chat_30423004 = "そうよ。",
  str_homestory_chat_30423005 = "夫人が自分で家事をするとは思いませんでした。",
  str_homestory_chat_30423006 = "かつてのわたくしの身分なら、考えられないことだから？",
  str_homestory_chat_30423007 = "それは……",
  str_homestory_chat_30423008 = "気にしなくていいのよ。\nわたくしはただ子どもたちのベッドを整えるのが好きなの。",
  str_homestory_chat_30423009 = "朝起きて、あの子たちがまだ寝ている姿を見ると、\nつい整えたくなってしまって。",
  str_homestory_chat_30423010 = "それで、あの子たちも嫌々起きるしかなくなって、\n恨み言を言われたわ。",
  str_homestory_chat_30423011 = "分かる気がします。",
  str_homestory_chat_30423012 = "ただ、早起きは子どもの教育には必要なことなの。\nあなたもお寝坊さんはダメよ。",
  str_homestory_chat_30423013 = "え？あ、は、はい…",
  str_homestory_chat_30424001 = "音楽ですか？",
  str_homestory_chat_30424002 = "ええ。あなたはどんな音楽が好みなのかしら？",
  str_homestory_chat_30424003 = "軽快で優しい音楽",
  str_homestory_chat_30424004 = "この前白夜城で聞いた音楽、とても素晴らしかったです。",
  str_homestory_chat_30424005 = "穏やかで、優雅でした。",
  str_homestory_chat_30424006 = "確かに素晴しい音楽だったわね。",
  str_homestory_chat_30424007 = "激しい音楽",
  str_homestory_chat_30424008 = "まるで騒音のような音楽のことね…",
  str_homestory_chat_30424009 = "そうとも言えませんよ。\nきちんと旋律があるんですから。",
  str_homestory_chat_30424010 = "そう…",
  str_homestory_chat_30424011 = "でも、ここでは音楽鑑賞は難しそうね。\nさみしくはない？",
  str_homestory_chat_30424012 = "自然の中の音を聞いていればいいので。\n自然の音も一種の音楽だと思ってるんです。",
  str_homestory_chat_30424013 = "今言ったような音楽を聴くには、\nちゃんとした会場に行かなきゃいけないですし。",
  str_homestory_chat_30424014 = "それもそうね。\nここでは天空ノ庭の音楽を楽しみましょう。",
  str_homestory_chat_30425001 = "僕の嫌いなものですか？",
  str_homestory_chat_30425002 = "すぐには思いつかないんですけど…\nどうして急にそんなことを？",
  str_homestory_chat_30425003 = "数日前雨がふったでしょう？\nそうしたら今日、宿舎が少しじめじめしていて…",
  str_homestory_chat_30425004 = "それで、影ノ街にいた時のことを思い出したの。",
  str_homestory_chat_30425005 = "影ノ街…その時も雨が降ってたんですか？",
  str_homestory_chat_30425006 = "ええ。あの時は雨が続いて、\nベッドをいくらきれいにしても、気持ち悪いままだったわ…",
  str_homestory_chat_30425007 = "影ノ街は雨が降ると湿気がすごいと聞いたことあります。\n特に雨の多い季節の数か月間は…",
  str_homestory_chat_30425008 = "でも、天空ノ庭のじめじめはそう長く続きません。",
  str_homestory_chat_30425009 = "ええ。ここは気持ちいいわ。",
  str_homestory_chat_30599999 = "何をしているのですか？",
  str_homestory_chat_30521001 = "香水を買いたいんですよね？",
  str_homestory_chat_30521002 = "そうなんです。ここは十分空気がきれいですが、\n香水で少し華やかさを足してもいいと思います。",
  str_homestory_chat_30521003 = "でも、どうして香水なんですか？",
  str_homestory_chat_30521004 = "実はキューブたちのために用意したのです。\n彼らはガイド助手の有力候補ですから。",
  str_homestory_chat_30521005 = "ただキューブたちは見分けるのが難しいでしょう？\n香水があれば大丈夫です。",
  str_homestory_chat_30521006 = "た、ただ見分けるためだけに？\nそんなことに香水を使うなんて、もったいなくありませんか？",
  str_homestory_chat_30521007 = "確かにそうですね…では印をつけるのはどうでしょう？\n「1号」、「2号」といったように。",
  str_homestory_chat_30521008 = "それも…やめましょう。",
  str_homestory_chat_30522001 = "飲み物のお店ですか？",
  str_homestory_chat_30522002 = "ここにはないですね。",
  str_homestory_chat_30522003 = "いいえ、そうではなく、私が飲み物のお店を開きたいのです。\nそれで今色々と調査をしています。",
  str_homestory_chat_30522004 = "調査？",
  str_homestory_chat_30522005 = "皆さんの好みを調べています。\nたとえば、あなたの好きな飲み物は？",
  str_homestory_chat_30522006 = "牛乳",
  str_homestory_chat_30522007 = "そうですか…健康的でいいですね。",
  str_homestory_chat_30522008 = "炭酸飲料",
  str_homestory_chat_30522009 = "あら、変わった好みですね。",
  str_homestory_chat_30522010 = "コーヒー",
  str_homestory_chat_30522011 = "よい好みです。",
  str_homestory_chat_30522012 = "紅茶",
  str_homestory_chat_30522013 = "素晴らしい好みですね！",
  str_homestory_chat_30522014 = "それはそうと、僕以外の皆の意見も集めたんですよね？",
  str_homestory_chat_30522015 = "何人くらいに聞いたんですか？",
  str_homestory_chat_30522016 = "現在はアンケートの実施中です。\n朝昼夜と時間帯を分け、質問も更新しながら調査をしています。",
  str_homestory_chat_30522017 = "そんなに手間が掛かるんですか…",
  str_homestory_chat_30522018 = "しっかりとした調査によってのみ詳細なデータが得られ、\n看板となる商品を生み出せるのですよ。",
  str_homestory_chat_30522019 = "お店…いつになったら開けられるようになるだろう…",
  str_homestory_chat_30523001 = "ダンスパーティーですか？",
  str_homestory_chat_30523002 = "ええ。ここのところ急にやる気が落ちたように感じていました。",
  str_homestory_chat_30523003 = "よく考えてみたら、しばらくダンスパーティーに行っていません。",
  str_homestory_chat_30523004 = "でも…ここではダンスパーティーはやってませんよ。",
  str_homestory_chat_30523005 = "では、やりましょう。\n会場は簡単なセッティングで構いません。",
  str_homestory_chat_30523006 = "広場を会場にして、椅子やテーブル、\nリボンを飾りつけるくらいで十分です。",
  str_homestory_chat_30523007 = "ただ楽隊は少し面倒そうですね。\n助っ人を頼んだ方がいいかもしれません。",
  str_homestory_chat_30523008 = "たとえば…キューブはどうでしょう？",
  str_homestory_chat_30523009 = "ちょっと待ってください。\nキューブは楽器を弾けません。",
  str_homestory_chat_30523010 = "では…今から練習すればいいのです。",
  str_homestory_chat_30523011 = "しかも特別練習ですよ。10日で習得させてみせます。",
  str_homestory_chat_30523012 = "10、10日ですか！？",
  str_homestory_chat_30523013 = "待てませんか？では3日にしましょう。",
  str_homestory_chat_30523014 = "白夜城のダンスパーティーに行った方が早いと思いますよ…",
  str_homestory_chat_30524001 = "ガイドですか？",
  str_homestory_chat_30524002 = "そうです。来た時から思っていたのですが、\nここはとても広いですよね。",
  str_homestory_chat_30524003 = "新しく来た仲間が道に迷わないためにも、\nガイドを置く必要があるでしょう。",
  str_homestory_chat_30524004 = "うーん…",
  str_homestory_chat_30524005 = "同意してくださるのですか？",
  str_homestory_chat_30524006 = "確かに一理あると思います",
  str_homestory_chat_30524007 = "ここはすごく広いし、\nガイドがいてくれたらとても助かります。",
  str_homestory_chat_30524008 = "ちょっと考えさせてください",
  str_homestory_chat_30524009 = "ただ、ガイドなんて誰にやってもらえばいいんですか？",
  str_homestory_chat_30524010 = "キューブです。",
  str_homestory_chat_30524011 = "え？キューブですか？",
  str_homestory_chat_30524012 = "キューブたちはずっとここにいるのでしょう？\n地理に明るく、この地を愛しています。適任だと思いますよ。",
  str_homestory_chat_30524013 = "それは…もう少し考えてみます。",
  str_homestory_chat_30699999 = "いいプロジェクトは思いついた？",
  str_homestory_chat_30621001 = "遊園地を造るとか？",
  str_homestory_chat_30621002 = "アイデアはいいわ。でもここはへんぴだし、どうやってお客様を呼び込むの？\nそれともターゲットを地元住民にしぼる？",
  str_homestory_chat_30621003 = "キューブ？",
  str_homestory_chat_30621004 = "いいわね！数はあまり多くないけど、将来性を考えたら…",
  str_homestory_chat_30621005 = "キューブの出生率は？繁殖速度はいいのかしら？\nどうやって子どもを産むの？",
  str_homestory_chat_30621006 = "光霊…とか？",
  str_homestory_chat_30621007 = "その口ぶりからすると、確信はないようね。",
  str_homestory_chat_30621008 = "繁殖はできないみたい。",
  str_homestory_chat_30621009 = "そうなの？",
  str_homestory_chat_30621010 = "うん。キューブが生まれるところを見たことがないんだ。\nまるで石から生まれて来たんじゃないかって思うほどなんだ。",
  str_homestory_chat_30621011 = "面白い種のようだけど、お金儲けにはつながりそうもないわね。",
  str_homestory_chat_30621012 = "待って！少し見方を変えたら…新しいアイデアが浮かんだわ！",
  str_homestory_chat_30621013 = "どんなアイデア？",
  str_homestory_chat_30621014 = "少ないってことは希少価値があるってことよね。\n希少価値は人を引き付ける、つまりお金儲けができるってこと！",
  str_homestory_chat_30621015 = "それって、まさか…",
  str_homestory_chat_30621016 = "キューブたちをスターに育て上げるのよ！\nそしてアストラ大陸のあちこちで公演活動を展開するの！",
  str_homestory_chat_30621017 = "タイトルは『復活！神秘の生物種世界の旅！』でどう？",
  str_homestory_chat_30621018 = "早いうちにあきらめて。",
  str_homestory_chat_30621019 = "どうして？",
  str_homestory_chat_30621020 = "それってキューブを見世物にするってことでしょ…",
  str_homestory_chat_30621021 = "考えてみるよ",
  str_homestory_chat_30621022 = "「大スターキューブ」なんて面白いアイデアだね。\nでも、まずは本人たちの意見を聞かないと。",
  str_homestory_chat_30621023 = "分かったわ！いい知らせを待ってて。",
  str_homestory_chat_30622001 = "それより天空ノ庭のことを話そうよ。",
  str_homestory_chat_30622002 = "天空ノ庭について、私もちょうど話したかったの。",
  str_homestory_chat_30622003 = "何に関すること？",
  str_homestory_chat_30622004 = "土地開発よ。ここは自然が多すぎて、\nちょっと不便よね。",
  str_homestory_chat_30622005 = "美食街や商店街、娯楽施設もないし、\nこれじゃお客様はこないわ。",
  str_homestory_chat_30622006 = "お客さんに来てほしいとは思ってないよ…\n僕は仲間の皆に気持ちよく過ごしてほしいんだ。",
  str_homestory_chat_30622007 = "それは間違ってるわ！考えたことはないの？\n今は何とかやっていけても、将来はどうなるか分からないって。",
  str_homestory_chat_30622008 = "あなたの収入がなくなっても、維持できるの？",
  str_homestory_chat_30622009 = "将来を心配するくらいなら、今をしっかり見なきゃ！\n私に天空ノ庭の経営を任せてみない？",
  str_homestory_chat_30622010 = "何をするつもり？",
  str_homestory_chat_30622011 = "私に売ってちょうだい。\nこの天空ノ庭を必ず大陸一の商業区にしてみせるわ！",
  str_homestory_chat_30622012 = "今の状態を維持できればいいよ。",
  str_homestory_chat_30623001 = "それよりも君の髪型について話そう。",
  str_homestory_chat_30623002 = "私の髪型？話題にするようなことはないわ。\nごくごく普通よ。",
  str_homestory_chat_30623003 = "その髪型だと手入れが大変でしょ？",
  str_homestory_chat_30623004 = "美容室に行けばいいだけのことよ。\n1回数千白夜コインくらいしかかからないし。",
  str_homestory_chat_30623005 = "数千！？いったい何をすればそんな値段になるの！？",
  str_homestory_chat_30623006 = "カットにトリートメント、それからセットの類よ。\n今の話で急にある計画を思いついたわ。",
  str_homestory_chat_30623007 = "どんな？",
  str_homestory_chat_30623008 = "ここに美容室を開いたらどう？\n髪の手入れの必要な仲間もたくさんいるんじゃない？",
  str_homestory_chat_30623009 = "設備が整っていれば、スタッフは少なくて店は小さくても構わないわ。\n必要な物は影ノ街から仕入れればいい。",
  str_homestory_chat_30623010 = "知り合いの美容室の店長がちょうど\nそういったチャネルには詳しいの…",
  str_homestory_chat_30623011 = "ただ自分がここで髪をセットしたいからじゃないの？",
  str_homestory_chat_30623012 = "その通りよ！自分で開いた店なら当然無料だもの！\nあなたたちには20%オフでサービスしてあげる！",
  str_homestory_chat_30623013 = "たった20%オフなの…",
  str_homestory_chat_30623014 = "ということは、いいのね？\n明日にでもすぐ連絡を取ってみるわ！",
  str_homestory_chat_30623015 = "待ってよ！ただ想像で話してただけだって！",
  str_homestory_chat_30624001 = "キューブを気に入ってるって聞いたよ？",
  str_homestory_chat_30624002 = "そうなの。私にキューブを譲る気はない？",
  str_homestory_chat_30624003 = "キューブは物じゃないんだ！",
  str_homestory_chat_30624004 = "ダメだよ！",
  str_homestory_chat_30624005 = "そう、分かったわ。キューブはあなたと契約してるのね？\nだったら、おいくら？",
  str_homestory_chat_30624006 = "補償金と譲渡金、契約費などもろもろ含めて、\n交渉に乗るわ。",
  str_homestory_chat_30624007 = "いったい何の話をしてるの…？\nどうして急にキューブの手伝いが必要になったの？",
  str_homestory_chat_30624008 = "最近ある大きなプロジェクトを手掛けてるから、\n頼れるスタッフが必要なのよ。",
  str_homestory_chat_30624009 = "頼れる？キューブたちがその条件に合ってるっていうの？",
  str_homestory_chat_30624010 = "そうよ！学者キューブとキューブ商人なんてピッタリだわ！",
  str_homestory_chat_30624011 = "計算ができて、物知りだし、それでいて食べる量が少なくて、睡眠も必要ないみたいじゃない。",
  str_homestory_chat_30624012 = "まさに理想のスタッフだわ！\n安心して、ちゃんと残業代は払うわ！",
  str_homestory_chat_30624013 = "平日の残業代は2倍、祝休日は3倍よ！",
  str_homestory_chat_30624014 = "ちょっと待ってよ。\nまだ決まったわけじゃないよ！",
  str_homestory_chat_30625001 = "プロジェクトのことはいいから、飲み物でも飲もうよ。",
  str_homestory_chat_30625002 = "でも天空ノ庭には飲み物なんてないでしょ。\n見渡す限り、冷たい水しかないわ。",
  str_homestory_chat_30625003 = "コーヒーや紅茶の類を飲みたくなったら、\n影ノ街から持ってこなきゃいけないなんて面倒だわ。",
  str_homestory_chat_30625004 = "ここには地元ならではの飲み物はないの？",
  str_homestory_chat_30625005 = "不思議なツリーの中には葉に特殊な香りがあるものがあるって聞いたから、\nお茶にしてみたらいいかも。",
  str_homestory_chat_30625006 = "不思議なツリー…方向性はなかなかね。",
  str_homestory_chat_30625007 = "まさか、また新しい事業でも思いついたの？",
  str_homestory_chat_30625008 = "まずは味を見てからね。\nそれからでないと可能性があるかどうか判断できないわ。",
  str_homestory_chat_30625009 = "あなたのオススメだもの。時間のある時に調べてみましょ。",
  str_homestory_chat_30799999 = "何してんだ？",
  str_homestory_chat_30721001 = "天空ノ庭の見回りだよ。",
  str_homestory_chat_30721002 = "おいおい、ちっとは面白いことできないのか？",
  str_homestory_chat_30721003 = "僕は楽しく見回ってるよ。\n君の方こそやることなくて時間持て余してるんでしょ？",
  str_homestory_chat_30721004 = "まあな…天空ノ庭で何かオススメの遊びはないのか？",
  str_homestory_chat_30721005 = "魚釣りかな？",
  str_homestory_chat_30721006 = "大人しすぎるな。\nそれに釣れなかった時にはメンツ丸つぶれだ。",
  str_homestory_chat_30721007 = "草花の世話？",
  str_homestory_chat_30721008 = "ここにはヘンな木しかないだろ？\nおかしな格好でオレは好きじゃないな。",
  str_homestory_chat_30721009 = "ミュージアムに行ってみたら？",
  str_homestory_chat_30721010 = "観るものないだろ…",
  str_homestory_chat_30721011 = "あれもダメ、これもダメ…気に入るもの一つもないの？\nだったらもう宿舎で寝てなよ。",
  str_homestory_chat_30721012 = "おいおい、そう怒るなって。\n今の会話はなぁ、お前を休ませてやりたかっただけさ。",
  str_homestory_chat_30721013 = "お前はいつだって天空ノ庭の見回りしてるか、\n仕事の手配してるかで、心配になってな…",
  str_homestory_chat_30721014 = "人生ってのは何も「天空ノ庭の建設」だけじゃないんだぞ。",
  str_homestory_chat_30721015 = "大丈夫だよ。見回りも休憩みたいなものだから。\n散歩してるとでも思ってよ。",
  str_homestory_chat_30721016 = "そうか、分かった。だったら続けてくれ。",
  str_homestory_chat_30722001 = "ちょうどブラブラしてるところだけど、君は？",
  str_homestory_chat_30722002 = "ちょうど探してたとこなんだ。\n一緒に影ノ街に行かないか？",
  str_homestory_chat_30722003 = "影ノ街？今から？",
  str_homestory_chat_30722004 = "ああ。高級レストランのVIP券を2枚もらってな。\n友人も連れて行けるんだ。",
  str_homestory_chat_30722005 = "見返りを求めない施しはないって言うけど…",
  str_homestory_chat_30722006 = "もしかして何か頼み事？",
  str_homestory_chat_30722007 = "他の人は誘ってないの？",
  str_homestory_chat_30722008 = "それとも…他に誘える人がいないの？",
  str_homestory_chat_30722009 = "ただ食事するだけがあり得ないなんて、\nオレとお前の友情をそんな風に見てたのか！",
  str_homestory_chat_30722010 = "考えてみるよ。",
  str_homestory_chat_30723001 = "ちょうど不思議なツリーを見に行くところだよ。",
  str_homestory_chat_30723002 = "不思議なツリーか…\n魅惑的な香りを放つもんがあるって聞いたんだが――",
  str_homestory_chat_30723003 = "香水にできないか考えてたんだ。",
  str_homestory_chat_30723004 = "苦労して育てた不思議なツリーなんだ。\nむやみにいじらないで。",
  str_homestory_chat_30723005 = "僕だけじゃなく、キューブたちも怒っちゃうから。",
  str_homestory_chat_30723006 = "そりゃ困ったな。デートがあるんだが…",
  str_homestory_chat_30723007 = "デート？",
  str_homestory_chat_30723008 = "「不思議な香りの特別な香水」を持ってくって、\n約束しちまったんだが。",
  str_homestory_chat_30723009 = "それ、何…？",
  str_homestory_chat_30723010 = "不思議なツリーの花粉と夜露で調合した、\n彼女だけのための香水だ。大陸でたった一つしかないんだぞ。",
  str_homestory_chat_30723011 = "本当にいい匂いなの？",
  str_homestory_chat_30723012 = "そうとも限らないぞ。特別感が重要だからな。",
  str_homestory_chat_30723013 = "それがいわゆる「デートテクニック」なのかな…\nとにかく、不思議なツリーをいじるのはダメだよ。",
  str_homestory_chat_30723014 = "そうか、分かったよ。\nじゃ、別の「テクニック」を考えるとするか。",
  str_homestory_chat_30724001 = "キューブたちに用があるの？",
  str_homestory_chat_30724002 = "ああ。管理について話をしたくてな。",
  str_homestory_chat_30724003 = "何があったの？",
  str_homestory_chat_30724004 = "天空ノ庭の管理者だっていうのに、\nあいつらには個としての魅力がなさすぎる。",
  str_homestory_chat_30724005 = "天空ノ庭をうまく運営して、\n皆にいいサービスが提供できればいいんじゃないの？",
  str_homestory_chat_30724006 = "違う！",
  str_homestory_chat_30724007 = "管理者に魅力がなかったら、誰が住みたいって思うんだ？",
  str_homestory_chat_30724008 = "それなのにキューブたちときたら角ばってて、オーラもない。",
  str_homestory_chat_30724009 = "天空ノ庭は遊園地じゃないよ。\nあえてお客さんを呼び込む必要はないんだ。",
  str_homestory_chat_30724010 = "皆ここにはリラックスするために来てるから、\nキューブたちが日常的な運営を維持してくれればそれでいいんだよ。",
  str_homestory_chat_30724011 = "それがお前たちの経営目標か…分かった。",
  str_homestory_chat_30725001 = "僕に用があるって聞いたよ？",
  str_homestory_chat_30725002 = "ああ、ここに土地を買いたいんだ。",
  str_homestory_chat_30725003 = "まさか誰かがリゾート村を造ろうとして、\n君を責任者にしたとか？",
  str_homestory_chat_30725004 = "おいおい、誤解だよ。\nオレはただ退職後ここで過ごしたいんだ。",
  str_homestory_chat_30725005 = "まだまだ先のことでしょ？",
  str_homestory_chat_30725006 = "ま、急に思いついたんだけどな。\n何しろここは環境に恵まれてる。人目に付かなくて、静かだ…",
  str_homestory_chat_30725007 = "老後はここで暮らせることを願ってるよ。",
  str_homestory_chat_30899999 = "私はここだよ～。",
  str_homestory_chat_30801001 = "こんにちは、バップ！",
  str_homestory_chat_30801002 = "私のこと見えるんだ！",
  str_homestory_chat_30801003 = "だって挨拶してくれたから。",
  str_homestory_chat_30801004 = "R・Wのみんなにはいつも無視されてるんだ。\n挨拶しても返事がないのが当たり前なんだよ。",
  str_homestory_chat_30801005 = "そんな！自己アピールはしてみた？\n何かアイデアを出したりとか？",
  str_homestory_chat_30801006 = "だから私は「軍師」なんだってば！\n大トカゲしかちゃんと計画聞いてくれないみたいだけど…",
  str_homestory_chat_30801007 = "いつかボスにも採用してもらえたらいいな。",
  str_homestory_chat_30801008 = "きっとそういう日が来るよ。頑張って、バップ！",
  str_homestory_chat_30821001 = "最近何してるの？",
  str_homestory_chat_30821002 = "この後なに食べようかなって考えてるよ。\nちょっとお腹が空いちゃった。",
  str_homestory_chat_30821003 = "天空ノ庭はR・W砂漠からちょっと遠いよね。\n私の好きな物はないかも。",
  str_homestory_chat_30821004 = "R・W砂漠の食べ物っていうと…\nトカゲの干物とかサボテンとか？",
  str_homestory_chat_30821005 = "それだけじゃないよ。\n天空ノ庭には、なにか食べるものないの？",
  str_homestory_chat_30821006 = "パンがあるよ",
  str_homestory_chat_30821007 = "普通だね。パンだけ食べるの？ソースはなし？",
  str_homestory_chat_30821008 = "パンだけで十分おいしいよ。",
  str_homestory_chat_30821009 = "そう、わかったよ。",
  str_homestory_chat_30821010 = "コーヒー",
  str_homestory_chat_30821011 = "目を覚ますのにはいいよね。\nただちょっと苦いから、お砂糖たくさん入れなきゃ…",
  str_homestory_chat_30821012 = "炊き込みご飯",
  str_homestory_chat_30821013 = "おかずがおいしければ、お腹いっぱいになりそうだね。",
  str_homestory_chat_30821014 = "フルーツパイ",
  str_homestory_chat_30821015 = "あなたって甘いもの好きだったんだ。意外だね。",
  str_homestory_chat_30821016 = "バップはここの食べ物にはあまり興味ないみたいだね。",
  str_homestory_chat_30821017 = "そうなの。食べ物の話してたら、\nR・W砂漠が恋しくなってきたな。",
  str_homestory_chat_30821018 = "風も砂もすごいけど、食べ物はおいしいんだよね…",
  str_homestory_chat_30821019 = "トカゲ味のアイスやシュークリームとか、\nR・W風ミミズの唐揚げとか…",
  str_homestory_chat_30821020 = "天空ノ庭にR・Wレストランを開いたらどうかな？\nやっていけるかな？",
  str_homestory_chat_30821021 = "おそらく倒産するね。",
  str_homestory_chat_30822001 = "こんにちは。ここには慣れた？",
  str_homestory_chat_30822002 = "どうも～、PlayerName！\nここっていい所だね。静かだし、居心地いいよ。ただ…",
  str_homestory_chat_30822003 = "この後は良くないことみたいだね。",
  str_homestory_chat_30822004 = "ここへ来てから時どき、クシャミばっかり出るんだ。\nほらまた…ハックション！",
  str_homestory_chat_30822005 = "理由はわからないけど、帰ればよくなるよ。",
  str_homestory_chat_30822006 = "環境に慣れてないのかな？それとも…花粉症とか？",
  str_homestory_chat_30822007 = "ハックション！そうかもね。\nR・W砂漠には花なんてめったにないから。",
  str_homestory_chat_30822008 = "見渡す限りの砂、砂、砂…\n砂には慣れてるんだけどな。",
  str_homestory_chat_30822009 = "鼻の中に入ろうと、目の中に入ろうと、\nぶんぶんって顔を振れば、出てくるでしょ。",
  str_homestory_chat_30822010 = "でも、花粉は…ハックション！\nほんと面倒だね。",
  str_homestory_chat_30822011 = "木や花から離れるか、時間をずらしてくればいいんだよ。",
  str_homestory_chat_30822012 = "あるいは数日すれば、慣れて何ともなくなるかも。",
  str_homestory_chat_30822013 = "天空ノ庭の緑いっぱいの自然は、確かにR・W砂漠と違うね。",
  str_homestory_chat_30822014 = "すごくリラックスできるし…いつまでもいたくなっちゃう。\nハックション！",
  str_homestory_chat_30823001 = "何を見てるの？",
  str_homestory_chat_30823002 = "オオワシを探してるんだよ。\nどこに停めてあるの？",
  str_homestory_chat_30823003 = "外だよ",
  str_homestory_chat_30823004 = "危険な目に遭うか心配じゃないの？",
  str_homestory_chat_30823005 = "ソラヴァンは自分の身は自分で守れるんだ。\nどうしてもって時には飛べばいいし。",
  str_homestory_chat_30823006 = "ソラヴァンに何か用？",
  str_homestory_chat_30823007 = "どこにいるのか、自分の身は守れるか、\nただ気になっただけだよ。",
  str_homestory_chat_30823008 = "ソラヴァンなら大丈夫だよ。心配しないで。",
  str_homestory_chat_30823009 = "それより、君が天空ノ庭にいる間、\n大トカゲはどうしてるの？",
  str_homestory_chat_30823010 = "私は車で来たんだ。大トカゲは砂漠を離れたがらなくて。",
  str_homestory_chat_30823011 = "たぶん、砂漠をあちこち散歩してるよ。\nあの信用ならない仲間と一緒に…",
  str_homestory_chat_30823012 = "仲間をそんな風に言っちゃダメだよ…",
  str_homestory_chat_30999999 = "何をしているの？",
  str_homestory_chat_30921001 = "散歩だよ。君は？",
  str_homestory_chat_30921002 = "何か考え事してたの？",
  str_homestory_chat_30921003 = "そうよ。ちょうどよかったわ。あんたの意見を聞かせてちょうだい。",
  str_homestory_chat_30921004 = "どんなこと…？",
  str_homestory_chat_30921005 = "啓光の将軍の中で、誰が大元帥にふさわしいと思う？",
  str_homestory_chat_30921006 = "ううん…そうだなあ。",
  str_homestory_chat_30921007 = "キシローナさん",
  str_homestory_chat_30921008 = "いい人選ね。統率能力にしろ、戦略あるいは忠誠心にしろ、各方面で優れているわ。",
  str_homestory_chat_30921009 = "ただ残念なことに、キシローナは白夜城出身よ。\n過去と縁を切ったとはいえ…",
  str_homestory_chat_30921010 = "「あの人たち」から見れば、キズでしょうね。",
  str_homestory_chat_30921011 = "そうなんだね…",
  str_homestory_chat_30921012 = "バートン",
  str_homestory_chat_30921013 = "バートンはしょせん将軍の器よ。戦場こそ彼の家なの。",
  str_homestory_chat_30921014 = "平和な時代には社会の害になるか、やる事もなくブラブラしてヒマ人になるしか能がないわ。",
  str_homestory_chat_30921015 = "容赦ないね…",
  str_homestory_chat_30921016 = "正しく評価したまでよ。",
  str_homestory_chat_30921017 = "ヒイロさん",
  str_homestory_chat_30921018 = "ヒイロの勇敢さに疑いの余地はないわ。軍団も厳しくうまく統率している。ただ…",
  str_homestory_chat_30921019 = "勇敢さの度が過ぎてるわね。全体の状況をまったく顧みないことも多いわ。",
  str_homestory_chat_30921020 = "軍人には確かに勇敢さが必要だけど、前提はそれが勝利につながること。",
  str_homestory_chat_30921021 = "あんたがこの微妙な違いを理解できるかは分からないけどね。",
  str_homestory_chat_30921022 = "ちょっと分かる気がする。",
  str_homestory_chat_30921023 = "そうなると、ふさわしい人がいないね。",
  str_homestory_chat_30921024 = "別の見方をすれば、優秀な副官もしくは参謀がいれば…",
  str_homestory_chat_30921025 = "全員ふさわしいと言えるでしょう。",
  str_homestory_chat_30922001 = "仲間の所に行くところなんだ",
  str_homestory_chat_30922002 = "仲間と言えば、レインハトはいい仲間だと思う？それともいい上司？",
  str_homestory_chat_30922003 = "いい仲間",
  str_homestory_chat_30922004 = "いい上司",
  str_homestory_chat_30922005 = "どうして急にそんなこと聞くの？",
  str_homestory_chat_30922006 = "知ってるだろうけど、私とレインハトは同期なの。",
  str_homestory_chat_30922007 = "今まではレインハトが上司で、私はあいつの指揮に従っていた。",
