  str_homestory_chat_31523001 = "何をしようか迷ってる",
  str_homestory_chat_31523002 = "ヒマしてんの？",
  str_homestory_chat_31523003 = "だったら、一緒に取り立てに行こうよ。",
  str_homestory_chat_31523004 = "おもしろいよ。",
  str_homestory_chat_31523005 = "やめておくよ",
  str_homestory_chat_31523006 = "心配いらないって。危険なんてないよ。",
  str_homestory_chat_31523007 = "あたしがいるんだから、あんたは特に何もしなくていいんだよ。",
  str_homestory_chat_31523008 = "僕は何をすればいいの？",
  str_homestory_chat_31523009 = "あたしがいるんだから、あんたは特に何もしなくていいんだよ。",
  str_homestory_chat_31523010 = "となりで胸を張って、いかめしい顔してればいいんだよ！",
  str_homestory_chat_31523011 = "雰囲気を盛り上げるって感じかな。",
  str_homestory_chat_31523012 = "あとのことはプロのあたしに任せといて。",
  str_homestory_chat_31523013 = "なかなかおもしろそうだね。",
