  str_homestory_chat_31523015 = "お金がいるの？",
  str_homestory_chat_31523016 = "あたしの仕事を体験させてあげるんだよ。もちろん有料に決まってるでしょ。",
  str_homestory_chat_31523017 = "だったら考え直させて。",
  str_homestory_chat_31523018 = "え？？",
  str_homestory_chat_31524001 = "ちょっと休もうかと思ってる",
  str_homestory_chat_31524002 = "休む？",
  str_homestory_chat_31524003 = "あんた、休みの日はなにしてんの？",
  str_homestory_chat_31524004 = "一日中寝てるよ",
  str_homestory_chat_31524005 = "そんなのもったいないよ。",
  str_homestory_chat_31524006 = "ゲームしてる",
  str_homestory_chat_31524007 = "そう、けっこう普通だね。",
  str_homestory_chat_31524008 = "あたしの休日はすっごく充実してるんだよ。",
  str_homestory_chat_31524009 = "1分1秒ムダにしないんだ。",
  str_homestory_chat_31524010 = "何をするの？",
  str_homestory_chat_31524011 = "もちろん、一番大事な家族と過ごすんだよ。",
