  str_homestory_chat_31699999 = "どうも、何してるの？",
  str_homestory_chat_31621001 = "部屋の掃除をしようと思って。",
  str_homestory_chat_31621002 = "部屋の掃除ねえ……",
  str_homestory_chat_31621003 = "そんなこと、どうして自分でやる必要があるの？カラクリ人形を使えばいいのに。",
  str_homestory_chat_31621004 = "私のカラクリ人形に代わりにやらせるのはどう？",
