  str_homestory_chat_31825015 = "そうか。では、できるだけ詮索しないでおこう。",
  str_homestory_chat_31825016 = "お前のサプライズが面白いことを願っているよ。",
  str_homestory_chat_31825017 = "大丈夫です。がっかりさせません！",
  str_homestory_chat_31825018 = "だって、貴重なお休みですからね。",
  str_homestory_chat_31825019 = "影の見守りを願う…\nでは待っているとしよう。",
  str_homestory_chat_31999999 = "ねぇ、今何かする予定あるかしら？",
  str_homestory_chat_31921001 = "特にないですね。",
  str_homestory_chat_31921002 = "ちょうど届いたばかりの貨物があって、\n購入者を探しているの。",
  str_homestory_chat_31921003 = "興味はないかしら？",
  str_homestory_chat_31921004 = "貨物？どんな貨物ですか？",
  str_homestory_chat_31921005 = "龍州大陸から搬送された玉器よ。",
  str_homestory_chat_31921006 = "玉器？",
  str_homestory_chat_31921007 = "ええ、聞いたことはない？",
  str_homestory_chat_31921008 = "ありません。",
  str_homestory_chat_31921009 = "それなら、ぜひ見に来てちょうだい。\n絶対に失望させないから。",
  str_homestory_chat_31921019 = "ゴホ…でも僕には買えないと思いますけど。",
  str_homestory_chat_31921020 = "本当かしら？でも気にしないで。\n気が変わったらいつでも来てちょうだい。",
  str_homestory_chat_31922001 = "今は何もやることがないんです。",
  str_homestory_chat_31922002 = "つまり、あなたは何もやることがなくて、\n退屈してるってことよね？",
  str_homestory_chat_31922003 = "そう言えますね。",
  str_homestory_chat_31922004 = "じゃあ、私とちょっとしたゲームをやらない？",
  str_homestory_chat_31922005 = "ゲーム？どんなゲームですか？",
  str_homestory_chat_31922006 = "とても簡単なゲームよ。",
  str_homestory_chat_31922007 = "ここに白夜コインが1枚あるでしょう？\nそれを私が空中に投げるの。",
  str_homestory_chat_31922008 = "それから？",
  str_homestory_chat_31922009 = "キャッチしたコインが裏か表か予想するのよ。",
  str_homestory_chat_31922010 = "あなたの予想が当たったら、そのコインはあなたのもの。",
  str_homestory_chat_31922011 = "もし予想が外れたら？",
  str_homestory_chat_31922012 = "外れたなら、外れよ。",
  str_homestory_chat_31922013 = "？",
  str_homestory_chat_31922014 = "簡単に言うと、予想が外れても関係ない、\nあなたには何の負担もないのよ。",
  str_homestory_chat_31922015 = "それだとシェオルさんが損しませんか？",
  str_homestory_chat_31922016 = "あら、優しいのね。\nでも、たかが白夜コイン1枚のことよ。",
  str_homestory_chat_31922017 = "これがもたらす価値は元手をはるかに超えているわ。\nましてや私が必ず負けるとは限らないわよね？",
  str_homestory_chat_31923001 = "今、帳簿をチェックしてるんです。",
  str_homestory_chat_31923002 = "帳簿になにか問題があるの？\n必要ならお手伝いするわよ。",
  str_homestory_chat_31923003 = "いいんですか？",
  str_homestory_chat_31923004 = "ふふ、みずくさいわね。",
  str_homestory_chat_31923005 = "あなたの悩みを分けてちょうだい。",
  str_homestory_chat_31923006 = "…なるほどね。この帳簿はつけ方が大雑把すぎるわね。",
  str_homestory_chat_31923007 = "申し訳ないのでは？",
  str_homestory_chat_31923008 = "大丈夫、気にしないで。帳簿は組織の最重要事項だもの。",
  str_homestory_chat_31923009 = "帳簿管理はかなり経験があるの。\nアドバイスしてもいいかしら？",
  str_homestory_chat_31923010 = "本当ですか？\nアドバイスがもらえたら大助かりです。",
  str_homestory_chat_31923011 = "ありがとうございます！",
  str_homestory_chat_31923012 = "ふふ、どういたしまして。",
  str_homestory_chat_31923013 = "ちょっとした経験やノウハウにすぎないわ。",
  str_homestory_chat_31923014 = "帳簿はできるだけ詳細に、\nでも分かりやすく簡潔に記載するのよ。",
  str_homestory_chat_31923015 = "日付は説明不要よね。用途は項目ごとに列を設けて、\n金額は2種類の形式で記録すればミスを減らせるわ。",
  str_homestory_chat_31923016 = "こうすればチェックする時にも簡単で楽よ。",
  str_homestory_chat_31923017 = "おお、なるほど。",
  str_homestory_chat_31923018 = "それから…",
  str_homestory_chat_31923019 = "あっ、待ってください。メモしますから！",
  str_homestory_chat_31924001 = "喉が渇いたから、何か飲もうと思ってました。",
  str_homestory_chat_31924002 = "それなら、コーヒーはいかが？",
  str_homestory_chat_31924003 = "コーヒー？",
  str_homestory_chat_31924004 = "そうよ。ちょうど良いコーヒー豆を買ったばかりなの。",
  str_homestory_chat_31924005 = "試飲してもらえると助かるわ。",
  str_homestory_chat_31924006 = "僕はコーヒーには詳しくなくて…",
  str_homestory_chat_31924007 = "大丈夫よ。飲んだ後に感想を聞かせてくれればいいの。",
  str_homestory_chat_31924008 = "それでいいなら、喜んで試飲しますよ。",
  str_homestory_chat_31924009 = "シェオルさんはコーヒー好きでしたか？",
  str_homestory_chat_31924010 = "特に好きってわけでもないし、もちろん嫌いでもないわね。",
  str_homestory_chat_31924011 = "それなら、なぜわざわざ\n手間のかかるコーヒー豆を買ったんですか？",
  str_homestory_chat_31924012 = "コーヒー豆はもともと浮遊商会が扱う雑多な業務の一つだし、\n特別な意味はないのよ。",
  str_homestory_chat_31924013 = "ほんの気まぐれで、自分で味を確かめたくなっただけよ。",
  str_homestory_chat_31925001 = "この後は勉強の時間です。",
  str_homestory_chat_31925002 = "勉強？",
  str_homestory_chat_31925003 = "本を読むんですよ。",
  str_homestory_chat_31925004 = "そうなのね。どんな本を読むのか聞いてもいいかしら？",
  str_homestory_chat_31925005 = "人文地理学に関する本です",
  str_homestory_chat_31925006 = "その分野なら少し手を出したことがあるわ。\n面白い本があるんだけど、紹介してもいいかしら？",
  str_homestory_chat_31925007 = "シェオルさんはこの方面の知識もあるんですか？",
  str_homestory_chat_31925008 = "商人なら知識は多いほどいいわ。\n異業種のお客様とも話がしやすくなるもの。",
  str_homestory_chat_31925009 = "優れた商人になるのも大変みたいですね。",
  str_homestory_chat_31925010 = "経済学に関する本です",
  str_homestory_chat_31925011 = "あら、経済学に興味があるの？",
  str_homestory_chat_31925012 = "興味があるというより、ただの好奇心かな？",
  str_homestory_chat_31925013 = "それに本をたくさん読んで損はないですよね。",
