  str_homestory_chat_31925015 = "私の書庫にはあなたにお勧めできる本がたくさんあるはずよ。",
  str_homestory_chat_31925016 = "機会があれば、ぜひ見に来てちょうだい。",
  str_homestory_chat_32099999 = "オフィスを改装したいんだけど、どんなスタイルがいいと思う？",
  str_homestory_chat_32021001 = "北境スタイル。",
  str_homestory_chat_32021002 = "ふむふむ、北境の建物や装飾はメルヘンチックだものね。",
