  str_homestory_chat_32124006 = "そんなにあれこれするのか？",
  str_homestory_chat_32124007 = "わらわはずっと眠っておるが。",
  str_homestory_chat_32124008 = "今度試してみて",
  str_homestory_chat_32124009 = "面白そうじゃな！",
  str_homestory_chat_32124010 = "では……わらわはまず、自分の体を覆う大きな布団を注文せねば！",
  str_homestory_chat_32124011 = "次は僕もシンゲイのようにやってみる",
  str_homestory_chat_32124012 = "よかろう！わらわが傍にいてやろう。龍と一緒に眠るのじゃ～",
  str_homestory_chat_32124013 = "そうすれば、PlayerNameが時間通りにわらわを起こせるじゃろう。",
  str_homestory_chat_32124014 = "PlayerNameの願い事がこれほど素朴だとは思わなかったぞ。",
  str_homestory_chat_32124015 = "「一族の復活」のような願い事をするかと思っていたが……",
  str_homestory_chat_32124016 = "それはもう変えられないことだから……",
  str_homestory_chat_32124017 = "「願い事」って、自分や友人たちをより幸せにするものであるべきじゃない？",
  str_homestory_chat_32124018 = "良きかな。決断をすべき時に決断するのもまた、勇気ではないか？",
  str_homestory_chat_32125001 = "シンゲイがずっと幸せでいられますように",
  str_homestory_chat_32125002 = "むむ。得難き願い事の機会を、わらわのために使うのか？",
  str_homestory_chat_32125003 = "何故じゃ？",
  str_homestory_chat_32125004 = "「願い事」を友達のために使ったっていいんだよ。",
  str_homestory_chat_32125005 = "それに自分のことは、願うより勝ち取りたいんだ。",
  str_homestory_chat_32125006 = "……あはは、かっこいいセリフだと思わない？ずっと言ってみたかったんだ！",
  str_homestory_chat_32125007 = "……うむ。",
  str_homestory_chat_32125008 = "笑ってごまかす必要はない。わらわは嘲笑したりはせぬ。",
  str_homestory_chat_32125009 = "では、わらわも願い事をしよう。",
  str_homestory_chat_32125010 = "え？神様の願い事？珍しいなあ！",
  str_homestory_chat_32125011 = "太陽と月は輝き、河と海は滔々と流れる。",
