  str_homestory_chat_32125014 = "おぬしが健康でよく食べよく眠ることを願ったのじゃ……",
  str_homestory_chat_32125015 = "永遠の幸福を祈っておるぞ！",
  str_homestory_chat_32125016 = "わあ……",
  str_homestory_chat_32125017 = "これで、わらわもPlayerNameも幸せになれるな！",
