  str_homestory_chat_32125020 = "ありがとう、シンゲイ。",
  str_homestory_chat_32299999 = "PlayerName、何してるんだ？",
  str_homestory_chat_32221001a = "はい…",
  str_homestory_chat_32221001 = "一日中ゴロゴロしようと思って。",
