  str_homestory_chat_32221004 = "ああ、俺の面倒をよく見てくれたんだけど……",
  str_homestory_chat_32221005 = "気ままな人でさ、言ってしまえば怠け者なんだ。",
  str_homestory_chat_32221006 = "いつも怠けることばかり考えていたな。",
  str_homestory_chat_32221007 = "でも法術には優れていたし、師匠にも評価されてた。",
