  str_homestory_chat_32223004 = "そう言えば、PlayerNameは、自分と全く違う人と友達になれるか？",
  str_homestory_chat_32223005 = "なれる",
  str_homestory_chat_32223006 = "そう言うと思ってた。",
  str_homestory_chat_32223007 = "この巨像には、祟霊の血統に近い人がかなりいるしな。",
  str_homestory_chat_32223008 = "世界は広い、人も寛大であるべきだ。",
  str_homestory_chat_32223009 = "なれない",
  str_homestory_chat_32223010 = "そうか……俺もその考えが理解できないわけじゃない。",
