  str_homestory_chat_33125006 = "僕は、ずっと地下にいたけどね。",
  str_homestory_chat_33125007 = "ご先祖様のことについては、まだ分からないことばかりなんだよ。",
  str_homestory_chat_33125008 = "これが、僕が大陸を旅する理由のひとつでもあるんだ。",
  str_homestory_chat_33125009 = "そうなんだ、空の末裔でもご先祖様のことが気になるの？",
  str_homestory_chat_33125010 = "マヤたち、なんだかそっくりじゃない？",
  str_homestory_chat_33125011 = "もしかしたら、マヤのご先祖様も空の末裔のご先祖様と知り合いだったりして？",
  str_homestory_chat_33125012 = "そう考えたら、昔はいいお友達だったのかもね！",
  str_homestory_chat_33125013 = "あはは、実に面白い発想だ！",
  str_homestory_chat_33125014 = "えへへ、だからマヤたちが仲良しなのを見たら、ご先祖様もきっと喜ぶと思うんだ！",
  str_homestory_chat_33299999 = "守りたいものはある？",
  str_homestory_chat_33221001 = "守りたいものか…",
  str_homestory_chat_33221002 = "たくさんあるよ。",
  str_homestory_chat_33221003 = "具体的には？",
  str_homestory_chat_33221004 = "ええっと…具体的にと言われると説明しにくいなあ。",
  str_homestory_chat_33221005 = "どういうものを指してる？",
  str_homestory_chat_33221006 = "理想や信念のような壮大なものから――",
  str_homestory_chat_33221007 = "より具体的で細かい事柄まで。",
  str_homestory_chat_33221008 = "もう少し具体的な例を挙げてくれる？",
  str_homestory_chat_33221009 = "例えば…",
  str_homestory_chat_33221010 = "私がコレクションしてる刃物、私のカラス、それからタタのような先輩。",
  str_homestory_chat_33221011 = "そういういことなら…僕には守らなければならないものがあるよ！",
  str_homestory_chat_33221012 = "今日の夕食を守るために、バイスが新しい料理を開発するのを止めたい！！",
  str_homestory_chat_33222001 = "巨像だ。",
  str_homestory_chat_33222002 = "なるほど。",
  str_homestory_chat_33222003 = "君たちの仲間は戦争を放棄し、君たちと数千年もの年月を共にしている。",
  str_homestory_chat_33222004 = "その上、共鳴という奇跡まで起こせる。",
  str_homestory_chat_33222005 = "私も代々伝わる家宝を開ける時には、そんなふうに心が揺さぶられた…\n君の気持ちが分かるよ。",
  str_homestory_chat_33222006 = "そうすると、僕たちは似たような運命だと言える。",
  str_homestory_chat_33222007 = "確かに。私たちの先祖はずっと昔に出会っていたし。",
  str_homestory_chat_33222008 = "君は私が使命を果たすのを手伝ってくれた。だから今度は私が、巨像を守るのを手伝う。",
  str_homestory_chat_33222009 = "ありがとう。ミトラの助けがあれば…",
  str_homestory_chat_33222010 = "必ずできる！",
  str_homestory_chat_33223001 = "先祖の栄光。",
  str_homestory_chat_33223002 = "気持ちは分かるよ。",
  str_homestory_chat_33223003 = "何しろ私も先祖の意志に則ってここまでやってきた。",
  str_homestory_chat_33223004 = "紆余曲折はあって、何度も迷いはしたけど…",
  str_homestory_chat_33223005 = "宿願はすでに果たした。それで君は、どこまで進んだの？",
  str_homestory_chat_33223006 = "僕はある程度まで進めたかな…",
  str_homestory_chat_33223007 = "そうなんだね。おめでとう。",
  str_homestory_chat_33223008 = "まだ努力してるところだよ…",
  str_homestory_chat_33223009 = "うん。そんな君を見守ってる。",
  str_homestory_chat_33223010 = "今後助けが必要な時は何でも言って。",
  str_homestory_chat_33223011 = "君が私の使命を手伝ってくれたことだけが理由じゃなくて、\n私は空の末裔の歴史にも興味があるからね。",
  str_homestory_chat_33223012 = "ありがとう。遠慮しないでおくよ！",
  str_homestory_chat_33224001 = "正義だ！",
  str_homestory_chat_33224002 = "えっ？",
  str_homestory_chat_33224003 = "君も正義の味方になりたいの？",
  str_homestory_chat_33224004 = "もうなってる！",
  str_homestory_chat_33224005 = "確かに。君と関わるうちに、君の正義を深く感じた。",
  str_homestory_chat_33224006 = "正義の味方として君は誰よりも適任だと思う。",
  str_homestory_chat_33224007 = "もちろんなりたいよ！",
  str_homestory_chat_33224008 = "そう？その決意と信念は素晴らしい。",
  str_homestory_chat_33224009 = "でも楽な仕事じゃないからね。",
  str_homestory_chat_33224010 = "私のアシスタントをやる？",
  str_homestory_chat_33224011 = "君と一緒なら、夜の悪党退治も今より思い通りにできるはず。",
  str_homestory_chat_33224012 = "えっと、それについてはもう少し考えさせてよ。",
  str_homestory_chat_33225001 = "友情だ。",
  str_homestory_chat_33225002 = "友情？確かに素晴らしいものだ。",
  str_homestory_chat_33225003 = "以前はよく仕事を変えて転々として過ごしてたから、友達なんていなかった。",
  str_homestory_chat_33225004 = "でも今はクーリエ隊の先輩にしても夜の特殊な友人にしても…",
  str_homestory_chat_33225005 = "私にとっては守りたい友情だ。",
  str_homestory_chat_33225006 = "君が守りたい友情って具体的にどんなの？",
  str_homestory_chat_33225007 = "巨像にいるみんなとの友情！",
  str_homestory_chat_33225008 = "巨像にいる人たちは確かにみんないい人。",
  str_homestory_chat_33225009 = "ただ、私は他人と距離を置く生活に慣れてる。",
  str_homestory_chat_33225010 = "みんなと交流する心の準備はまだできてないみたい。",
  str_homestory_chat_33225011 = "だから今だと…",
  str_homestory_chat_33225012 = "君との友情だ！",
  str_homestory_chat_33225013 = "ごめんね、さっき…君のことを挙げなかった。",
  str_homestory_chat_33225014 = "君がそばにいることが、すでに当たり前になってしまったから。",
  str_homestory_chat_33225015 = "どうか訂正させて。",
  str_homestory_chat_33225016 = "君との友情を守ることが何よりも重要だ。",
  str_homestory_chat_33225017 = "それは光栄だよ！僕もこの友情を大切にするね！",
  str_homestory_chat_33399999 = "ある日目覚めて、この世に自分しかいないと分かったら、あんたはどうする？",
  str_homestory_chat_33321001 = "二度寝する",
  str_homestory_chat_33321002 = "夢を見てるだけだ",
  str_homestory_chat_33321003 = "なんでそーなんの。すぐに探索に出かけて、普段はやっちゃいけないことをするでしょ？",
  str_homestory_chat_33321004 = "バカ言え！",
  str_homestory_chat_33321005 = "普段やっちゃいけないことを普段からやるのが僕みたいな「主人公」だよ。",
  str_homestory_chat_33321006 = "ははは！あんたって私以上にぶっ飛んでるね。",
  str_homestory_chat_33321007 = "みんなが消えたら、あんたの感知能力も使い道がなくなると思わない？",
  str_homestory_chat_33321008 = "だったら…どのみちやることはないから、なおさら二度寝するよ。",
  str_homestory_chat_33321009 = "君がやりたい「やっちゃいけないこと」って？",
  str_homestory_chat_33321010 = "う～ん…たくさんあるように思えたけど、よく考えてみるとそうでもないな。",
  str_homestory_chat_33321011 = "やりたいと思ったらやる。ルールには縛られないのが私だから。",
  str_homestory_chat_33321012 = "「普段やっちゃいけないこと」なんてそもそもないんだよ！",
  str_homestory_chat_33321013 = "本当に危険人物だ…",
  str_homestory_chat_33322001 = "まずは影ノ街かハーバーシティの遊園地へ行く",
  str_homestory_chat_33322002 = "それから普段は並ばないと乗れないアトラクションを思い切り楽しむ！",
  str_homestory_chat_33322003 = "あんたって…堅実というかつまらないというか…",
  str_homestory_chat_33322004 = "あんたの夢は夜中に遊園地に忍び込めば叶うでしょ？",
  str_homestory_chat_33322005 = "…そんなことしようなんて普通は思わないでしょ！",
  str_homestory_chat_33322006 = "私は光り輝く自由の女神、ペピータ様だよ！",
  str_homestory_chat_33322007 = "さあ、今晩私が連れてってあげる。",
  str_homestory_chat_33322008 = "（まずい…ちょっと心が動いてる…）",
  str_homestory_chat_33323001 = "書店へ行って立ち読みする",
  str_homestory_chat_33323002 = "一日中読んでいられるし、そのへんに座ってもいい。\nそれに店員の目を気にすることもないとなれば…まさに天国だよ！",
  str_homestory_chat_33323003 = "…",
  str_homestory_chat_33323004 = "しみったれた願い事だとは分かってるけど、そう冷たい目で僕を見なくても…",
  str_homestory_chat_33323005 = "それは誤解だよ。しみったれてるだなんて少しも思ってない。",
  str_homestory_chat_33323006 = "けど本をタダで読みたいなら、豪華な服に着替えればいいだけ…\nそれで書店に入って好きな本を選ぶ。",
  str_homestory_chat_33323007 = "選んだら店の人には適当に貴族の名前を言って、月末に請求させればいいんだよ。",
  str_homestory_chat_33323008 = "貴族なんて毎月カネを水のように使ってるんだから、細かくチェックしたりしないよ。",
  str_homestory_chat_33323009 = "そ、それは…犯罪じゃないか！",
  str_homestory_chat_33323010 = "バカ言わないでよ。無学無能の貴族たちに代わって、\n世の中に知識を広めてあげるんだよ…これのどこが犯罪なの？",
  str_homestory_chat_33323011 = "徳を積んでると言って。",
  str_homestory_chat_33323012 = "…",
  str_homestory_chat_33324001 = "川で体を洗う。",
  str_homestory_chat_33324002 = "ブッ！",
  str_homestory_chat_33324003 = "ゴホン…正直に言うと、ずっとやりたかったんだ。",
  str_homestory_chat_33324004 = "でもやっぱりさ…心配でしょ？",
  str_homestory_chat_33324005 = "そんなことないよ。私はよくやってる。",
  str_homestory_chat_33324006 = "えっ！？平気なの？",
  str_homestory_chat_33324007 = "人に見られるかもしれないでしょ？",
  str_homestory_chat_33324008 = "魔獣ちゃんがそばにいてくれるもん。\nしかも他人が風呂に入ってるのを見るヤツなんていないでしょ？",
  str_homestory_chat_33324009 = "それに人の体なんてみんな同じなのに、何を憚る必要があるのよ。",
  str_homestory_chat_33324010 = "…いや、おかしいぞ。今すぐ僕を川で水浴びさせる気なら、その手には乗らないから！",
  str_homestory_chat_33324011 = "人食い魚に襲われない？",
  str_homestory_chat_33324012 = "私が川で体を洗う時って、全身泥だらけだよ。",
  str_homestory_chat_33324013 = "人食い魚どころか、サメだって食あたりになっちゃうよ。",
  str_homestory_chat_33324014 = "壮観だな…あ、その様子が見たいわけじゃないからね。",
  str_homestory_chat_33325001 = "白夜城城主の玉座に座る",
  str_homestory_chat_33325002 = "しかも足を崩して座る！",
  str_homestory_chat_33325003 = "何それ。創造性に欠けるね。私ならとっくに座ったことあるよ。",
  str_homestory_chat_33325004 = "何だって！？き、聞いておくけど、それって許可を得てないよね…？",
  str_homestory_chat_33325005 = "カレンの父親から玉座に座るよう誘ってくると思う？",
  str_homestory_chat_33325006 = "座り心地はよかった？",
  str_homestory_chat_33325007 = "ダメだね、ちっともよくなかった。ひどく硬かったよ！",
  str_homestory_chat_33325008 = "カレンのためを思ってクッションを置いてきてあげた。",
  str_homestory_chat_33325009 = "城主様が感謝してくれてたらいいけど…あはは！",
  str_homestory_chat_33325010 = "なんでそこへ行ってたの？",
  str_homestory_chat_33325011 = "あの晩、美しい白い壁に落書きをしてたら、衛兵が来て…",
  str_homestory_chat_33325012 = "そこで初めてそこが白夜城の法廷だって知ったんだ。",
  str_homestory_chat_33325013 = "…",
  str_homestory_chat_33325014 = "それから私は逃げた。城主の玉座がある場所まで逃げたんだ。",
  str_homestory_chat_33325015 = "身の安全のために、君とは一定の距離を置かないとな…",
  str_homestory_chat_33429999 = "この時代のことを聞かせてもらえるか？",
  str_homestory_chat_33421001 = "あ、そんな改まって言われると恐縮しちゃいます。",
  str_homestory_chat_33421002 = "私は長い間眠っていた。この世界のことをよく知らない。",
  str_homestory_chat_33421003 = "このままでは、君に迷惑をかけるやもしれん。",
  str_homestory_chat_33421004 = "だから、頼む。",
  str_homestory_chat_33421005 = "迷惑なんてそんな…そういう僕も、\n地下に17年「封印」されてたようなもので…",
  str_homestory_chat_33421006 = "今もこの世界を絶賛探索中なんです！",
  str_homestory_chat_33421007 = "だから、お互いに見たことや聞いたことを話しましょう！",
  str_homestory_chat_33421008 = "一緒にこの世界を知って、感じていきましょう！",
  str_homestory_chat_33421009 = "確かにその通りだな。私もこの世界を知り、感じたい。",
  str_homestory_chat_33421010 = "君の経験を分かち合ってもらえるとは、実に光栄だ。",
  str_homestory_chat_33421011 = "アクリュスの名にかけて、\n私も余すことなく君に分かち合うことを誓おう。",
  str_homestory_chat_33421012 = "君の先人たち――偉大な空の末裔たちの物語を知りたいのなら、\n私が話してあげよう。",
  str_homestory_chat_33421013 = "はい、知りたいです！\nあなたたちの冒険の話を今度ぜひ聞かせてください！",
  str_homestory_chat_33422001 = "R・Wでカーレースがあるんですけど、\nアクリュスさんは興味ありますか？",
  str_homestory_chat_33422002 = "カーレース…「カー」とは「車」のことだな。言葉は知っている。",
  str_homestory_chat_33422003 = "だが、私のいた時代にはまだ馬車しかなかった。",
  str_homestory_chat_33422004 = "「車」とは馬車よりも速く走れるにもかかわらず、\n実に安定していると聞く。",
  str_homestory_chat_33422005 = "この時代の技術には驚かされるばかりだ。",
  str_homestory_chat_33422006 = "車、運転してみますか？",
  str_homestory_chat_33422007 = "残念ながら、私にはまだその技術がない。",
  str_homestory_chat_33422008 = "危険であるだけでなく、余計な面倒を起こしてしまうだろう。",
  str_homestory_chat_33422009 = "ドライブに連れていってあげましょうか？",
  str_homestory_chat_33422010 = "素晴らしい息抜きができそうだな。",
  str_homestory_chat_33422011 = "だが、戦士の性分だろう。私はやはり己の手で戦車を動かしたい。",
  str_homestory_chat_33422012 = "じゃあ…今度運転の練習をしませんか？\n巨像のシミュレーションで教えてあげます。",
  str_homestory_chat_33422013 = "そのような便利なものがあるのか？",
  str_homestory_chat_33422014 = "ならば、今度ぜひ試させてくれ。\nこの時代の新しい技を私も学んでみたいのだ。",
  str_homestory_chat_33422015 = "はい！",
  str_homestory_chat_33423001 = "ハーバーシティの水族館なんてどうですか？\nすごく楽しいですよ。",
  str_homestory_chat_33423002 = "初めて聞く言葉だ。そこは何をする所なのだ？",
  str_homestory_chat_33423003 = "夢のような場所です",
  str_homestory_chat_33423004 = "幻想的な深海の世界に入り込んだような気分になるんです。",
  str_homestory_chat_33423005 = "陸の上では見られない風景がたくさん見られるんですよ。",
  str_homestory_chat_33423006 = "とても面白い場所です",
  str_homestory_chat_33423007 = "海底に棲む色々な生物が集まっているんです。",
  str_homestory_chat_33423008 = "1度行っただけでも、海に関する知識をたくさん学べるんですよ。",
  str_homestory_chat_33423009 = "素晴らしい所のようだな。\n確かに言葉で聞いただけでも心を奪われる。",
  str_homestory_chat_33423010 = "それに水族館は一緒に行く人が多いほど、楽しいんです。",
  str_homestory_chat_33423011 = "今度星の戦士たちを誘って行くといいですよ。",
  str_homestory_chat_33423012 = "心遣いに感謝する。",
  str_homestory_chat_33423013 = "その時には、ぜひ君に案内をお願いしたい。",
  str_homestory_chat_33423014 = "君も私たちの仲間だ。",
  str_homestory_chat_33423015 = "はい、僕はいつでも大丈夫ですよ！",
  str_homestory_chat_33424001 = "啓光の合同演習に興味はありますか？",
  str_homestory_chat_33424002 = "合同演習…",
  str_homestory_chat_33424003 = "光霊たちが集まって軍事演習をする、ということか？",
  str_homestory_chat_33424004 = "はい。各勢力の光霊たちが集まって――",
  str_homestory_chat_33424005 = "自分たちの力を磨くんです",
  str_homestory_chat_33424006 = "栄誉のために戦うんです",
  str_homestory_chat_33424007 = "盛大な演習のようだな。興味が湧いてきた。",
  str_homestory_chat_33424008 = "君も参加したことがあるのか？戦績はどうだったのだ？",
  str_homestory_chat_33424009 = "まあまあ、でしょうか…",
  str_homestory_chat_33424010 = "結局、最後の最後で優勝を逃したので…",
  str_homestory_chat_33424011 = "なかなかだったんですよ！",
  str_homestory_chat_33424012 = "何せ最後まで残ったんですから！",
  str_homestory_chat_33424013 = "そういうことか。",
  str_homestory_chat_33424014 = "機会があれば、皆と共にこの時代の光霊たちの活躍をこの目で見てみたいものだ。",
  str_homestory_chat_33424015 = "でも、そうなると…星の戦士たちが参加して…\n演習はもっと激しい戦いになるかも…",
  str_homestory_chat_33425001 = "だったら龍州の異国情緒は外せません！",
  str_homestory_chat_33425002 = "海の向こう側にある、もう一つの神秘の大陸なんです。",
  str_homestory_chat_33425003 = "古い歴史をもつ帝国が多くの諸侯国を従えているんです。",
  str_homestory_chat_33425004 = "そこに暮らす光霊は僕たちと少し違っているだけでなく、\n祟霊って呼ばれる生き物もいるんですよ。",
  str_homestory_chat_33425005 = "古代国家か…",
  str_homestory_chat_33425006 = "何百年、何千年にもわたる苦難を乗り越えてきたのか。",
  str_homestory_chat_33425007 = "その国は今も続いているのか？",
  str_homestory_chat_33425008 = "はい！不思議でしょう？",
  str_homestory_chat_33425009 = "龍州については、僕もまだ勉強中なんですけど…",
  str_homestory_chat_33425010 = "アクリュスさんが興味あるなら、龍州での冒険の話を聞かせてあげます。",
  str_homestory_chat_33425011 = "それから、龍州の古い書物も貸してあげます。",
  str_homestory_chat_33425012 = "ありがとう。読ませてもらおう。",
  str_homestory_chat_33425013 = "それから…冒険といったか？",
